addon_table.spoken_places_uk = {
    [1411] = {
        text = [[Потрісканий і червоний Дуротар — край скель та ущелин, сухий і спекотний, бідний на воду й зелень. Він лежить на східному узбережжі Калімдору. Орки бачать у ньому сувору красу, що нагадує їм Дренор. Після Третьої війни воєвождь Тралл привів сюди свій народ, щоб збудувати нову батьківщину, і назвав її на честь убитого батька Дуротана.

Спокій тривав недовго. Великий адмірал Делін Праудмур, герой Другої війни й ворог орків, привів із Кул-Тіраса великий флот проти Дуротару. Він хотів знищити Орду, перш ніж та встигне пустити коріння. Його донька Джайна Праудмур вирішила інакше. Біля Терамора вона виступила проти власного батька й билася пліч-о-пліч із Траллом. Делін загинув у битві, і вони так і не примирилися. На знак вдячності Тралл дозволив воїнам Джайни безпечно відступити до Терамора.

Тролі Темного Списа тримають південне узбережжя, живучи у вигнанні. Їхній власний знахар Залазейн вигнав їх із рідних островів Ехо. Відтоді вони так і не змогли їх повернути.]],
        areas = {
            ["bladefist bay"] = [[Кожен приплив приносить із моря уламки. Ці води навіть прозвали смітником Великого моря. Затока лежить біля північно-східного берега Дуротару, навколо Скелі Черепа, а через воду на півночі видно берег Азшари. Названо її на честь Карґата Гострорука, ватажка клану Скаліченої Руки.]],
            ["burning blade coven"] = [[Запилені червоні гори утворюють північну межу долини Випробувань. Одна з печер веде до покинутих підземель. Орк-чорнокнижник Ярроґ Погибелетінь очолює місцевих культистів. Кажуть, усередині чаяться служителі Палаючого Клинка, культу шанувальників демонів. Із печери в долину висипають біси й інші слабкі демони, а сильніші, кажуть, ховаються в глибині.]],
            ["darkspear strand"] = [[Тролі Темного Списа зійшли тут на берег після вигнання з островів Ехо. Трохи віддалік від води Вол’джин заснував рибальське селище й назвав його Сен’джин на честь батька. Там зібралися вцілілі, щоб почати життя спочатку.]],
            ["deadeye shore"] = [[Берег Мертвого Ока дістав назву від Кілроґа Мертвого Ока, орочого героя, який утратив око й колись очолював клан Кривавої Очниці. Величезна піщана смуга, наче вирвана з пустелі, має форму черепа без одного ока. Ніби сама земля носить рану, про яку нагадує це ім’я.

Нині берег майже ніхто не турбує, крім рапторів, скорпідів і кабанів. Колись тут Палаючий Клинок напав на орка-рибалку Байрока.]],
            ["den"] = [[Із цієї печери в урвищі, майже посеред долини Випробувань, Зурііта Далековзірна посилає у світ здібних молодих орків і тролів. Тут живуть і працюють вербувальники та наставники молоді. Вони мають усе найнеобхідніше для табору, а вхід стережуть рубаки.]],
            ["drygulch ravine"] = [[Сухощільний яр лежить нижче від довколишньої землі. Ним тече річка. На урвищах гніздяться пиловійні гарпії, які взялися розбишакувати. Вони грабують припаси караванів і складають здобич високо на скелях, де найсильніші гарпії стережуть яйця. Потрапити до яру можна лише крізь малу печеру з каньйону Бритвовітру або впавши згори.]],
            ["dustwind cave"] = [[Новобранці культу Палаючого Клинка приходять навчатися до невеликої печери на скелях каньйону Бритвовітру, на північний схід від Колючого Пагорба. Там їх навчають культисти.]],
            ["echo isles"] = [[На цих тропічних островах біля південно-східного берега Дуротару блукають раптори й рисі. Колись тут був дім тролів Темного Списа. На розквіті імперії Ґурубаші тропічні тролі володіли землями від Тернистої долини до цих островів.

Тролі Темного Списа ледве встигли оселитися, коли їх зрадив власний знахар Залазейн. Він опанував таємниці невмерлості й нацькував на свій народ зомбі та інших поплічників. Вол’джин і вцілілі втекли на материковий берег. Острови досі тримає Залазейн. На головному острові він закопав між хатинами осквернені фетиші. Вони спотворюють рух магії Дуротаром і псують місцевих тварин. Його невмерлі тролі переправляються на материк, щоб проклясти ще більше одноплемінників і підкорити їх знахареві.]],
            ["hidden path"] = [[Таємна стежка здіймається горами, що обступають долину Випробувань. Нею молоді шамани, які щойно стали на свій шлях, дістаються Каменя духів. Із найвищої точки внизу видно Степи.]],
            ["jaggedswine farm"] = [[На одній із кількох ферм поблизу головної брами Орґріммара тримають свиней у великому загоні біля ставка й комори.]],
            ["kolkar crag"] = [[Воєвода Колканіс очолює кентаврів Колкарів, які тримають цю кам’янисту ущелину на півдні Дуротару. Він готує напад на орочі поселення від долини Випробувань і селища Сен’джин до Колючого Пагорба. Колканіс має намір дійти аж до брами Орґріммара.]],
            ["razor hill"] = [[Невдовзі після Третьої війни військо Кул-Тіраса призначило Траллові зустріч на цьому пагорбі. То була засідка. Рексар запідозрив підступ і наполіг, що піде замість Тралла. Він здолав найманих убивць, які там чекали.

Тепер орки утримують містечко на цьому роздоріжжі. Орґніл Духошрам наглядає за ним і стежить за пересуваннями Палаючого Клинка в околицях.]],
            ["razor hill barracks"] = [[Казарми — найбільша будівля Колючого Пагорба. За їхніми розмірами видно, що це одне з головних поселень Дуротару після Орґріммара.]],
            ["razormane grounds"] = [[Землі Бритвогривих усіяні обгризеними кістками, а з червоних гір нависають колючі хащі. Колись ця земля належала бритвогривим свинобразам. Орки воєвождя Тралла багатьох звідси вигнали. Нині свинобрази знову наступають зі Степів, і орки боронять свою батьківщину. Здається, на кожного вбитого свинобраза з хащів виходять двоє. Табір очолює геолорд Цятка, а його боєстражами командує капітан Плаский Бивень.]],
            ["razorwind canyon"] = [[Пиловійні гарпії гніздяться в каньйоні Бритвовітру. Дорога між Колючим Пагорбом та Орґріммаром ділить його надвоє. Цих птахожінок багато, і вони агресивні. Не готового до бою мандрівника вони швидко здолають або вб’ють. Печера у східній частині каньйону веде до Сухощільного яру.]],
            ["rocktusk farm"] = [[Свині з ферми Кам’яних Бивнів годують Орду. Ферма лежить трохи далі західною дорогою за брамою Орґріммара, і її господарі почуваються там досить безпечно.]],
            ["scuttle coast"] = [[На скелях узбережжя Затоплених човнів, на сході Дуротару перед Великим морем, лежать розбиті кораблі Кул-Тіраса. Вони загинули в боях орків із флотом великого адмірала Деліна Праудмура. Орки досі нишпорять у корабельних трюмах і витягують звідти рештки гном’ячої техніки.]],
            ["senjin village"] = [[Вол’джин привів тролів Темного Списа на цей відтинок південного берега після того, як їхній власний знахар Залазейн зрадив їх і вигнав з островів Ехо. Він назвав рибальське селище на честь батька Сен’джина, який поліг, рятуючи свій народ від мурлоків у Третій війні. Біля причалу стоять три зовсім малі хатини, дві трохи більші й одна велика.]],
            ["shrine of the dormant flame"] = [[Вівтар Дрімаючого полум’я — одне з найсвятіших місць для всіх шаманів Орди. Таємний шлях спіраллю підіймається на найвищу гору краю від Південнолютної річки на північний захід від долини Випробувань. З вершини видно весь край. Там чекає незапалена жарівня. Шаман доводить, що опанував вогонь, коли долає вогняного елементаля й запалює жарівню його жаринкою. Хранитель вівтаря Телф Джуулам наставляє тих, хто прийшов на випробування.]],
            ["skull rock"] = [[Орк-чорнокнижник Ґазз’уз очолює загін Палаючого Клинка зі Скелі Черепа, печери на північному сході Дуротару. Це одне з кількох місць у краю, де культ утримався.]],
            ["southfury river"] = [[Південнолютна річка бере початок в озері на горі Гіджал і спадає низкою великих водоспадів на землі внизу. Вона широка й стрімка, чи не найпомітніша річка Калімдору. Вона відділяє Ясенеділ від Азшари, а далі на півдні — Степи від Дуротару. Через неї перекинуто три мости: з Азшари до Ясенедолу, до Орґріммара й із Дуротару до Степів.]],
            ["spirit rock"] = [[Камінь духів стоїть у пагорбах високо над долиною Випробувань. До нього веде Прихована стежка. Шамани Орди шанують це місце як священне. Учні шаманів п’ють біля каменя сапту, щоб поспілкуватися із землею.]],
            ["thunder ridge"] = [[В ущелині на північному заході Дуротару, на південний захід від Орґріммара, колись густо росли прадавні дерева. Серед них жили громові ящери в злагоді з лісом. Потім людський лісорубний табір почав оголювати кряж, і ящери збожеволіли. Рексар, якого послали зібрати мерехтливу траву для провидця Тралла Дрек’Тара, помітив зміни у звірах. Разом вони знайшли табір і мусили вбити ящерів, щоб відвернути лихо. Рексар зібрав їхні яйця для досліджень Дрек’Тара.

Нині в ущелині отаборився загін культистів Палаючого Клинка під проводом Фіззла Темнопазура. Вони сіють хаос.]],
            ["tiragarde keep"] = [[На червоних скелях узбережжя Затоплених човнів біліє Тіраґардська твердиня. Ця фортеця взагалі не мала постати в Дуротарі. Великий адмірал Делін Праудмур наказав звести її поспіхом, коли привів флот із Кул-Тіраса воювати з орками. Напад відбили, і твердиня впала. Делін загинув біля Терамора, але за його залишеним наказом лейтенант Бенедикт вирушив відбити руїни. Нині їхні обсипані мури патрулюють добре навчені кул-тіраські морські піхотинці й моряки, сповнені зневаги до Орди. Молодих воїнів Орди раз по раз посилають випробувати сили в бою з ними, та ще ніхто їх не вигнав. Іноді солдати грабують Колючий Пагорб.]],
            ["torkren farm"] = [[Міша Тор’крен тримає цю свиноферму на північному заході Дуротару. Її господарство ніколи не приносило стільки прибутку, як сусідні ферми. Кілька днів тому її син Крон пішов полювати на кроколісків уздовж Південнолютної річки на заході й досі не повернувся.]],
            ["valley of trials"] = [[Молоді орки й тролі Орди починають свій шлях тут, у чаші випаленої землі, оточеній скелями на півдні Дуротару. Вони проходять обряди посвяти. Тіла тих, хто не витримав випробувань і загинув, лишають під палючим сонцем. На півночі старі печери захопив Палаючий Клинок. Подейкують, що Рада Тіней закріпилася в окрузі.]],
        },
    },
    [1412] = {
        text = [[Таурени століттями мандрували без власної землі. Коли Тралл зі своїми орками висадився на Калімдорі, таурени зустріли їх, і Керн Криваве Копито побачив у них споріднені душі, сповнені честі й сили. Під захистом Тралла Керн привів свій народ до Мулґора. За допомогою орків плем’я Кривавого Копита відкинуло кентаврів і здобуло ці трав’янисті землі.

Це захищена долина, велике зелене пасовище з рідкими деревами. З усіх боків її оточують гори, і лише один перевал веде назовні. Посередині над полями здіймаються скелі Громового Бескиду й кидають довгі тіні на рівнину. На пласкій вершині Керн заснував притулок, відкритий для тауренів кожного племені. Під його владою розпорошені племена об’єдналися.

Намети й шкіряні хатини стоять поблизу вітряків, що мелють зерно. Кентаври й досі нападають на рівнини, та укріплення на вершинах витримали їхні набіги. Кожен таурен, досягнувши повноліття, мусить вирушити в дику місцевість Мулґора й довести свою спроможність на Великому полюванні.]],
        areas = {
            ["baeldun digsite"] = [[Дворфська експедиція з Бель-Модана вирубала великий кар’єр у схилі гори на західному краю Мулґора. Бейн Криваве Копито застеріг дворфів, бо вважав розкопки образою Матері-Землі. Перемовини ні до чого не привели, і плем’я Кривавого Копита має намір вигнати дворфів.

Дворфи не слухають і копають далі. Їхній кар’єр — шрам на землі Мулґора.]],
            ["bloodhoof village"] = [[Барабани із селища Криваве Копито не схожі на жодні інші, і селище славиться цим ремеслом. Воно стоїть на центральних рівнинах Мулґора довкола озера Кам’яного Бика й носить ім’я племені Кривавого Копита. Тут приручають диких рівнинних кодо й привчають їх носити вершників-тауренів.

Селище очолює Бейн Криваве Копито, син Керна. Він дбає про його захист. Зарлман Два-Місяці піклується про духовні потреби племені й молодих тауренів, які тут проходять.]],
            ["brambleblade ravine"] = [[Щетиноспині свинобрази тримають ущелину Лезожини на північно-східному краю плато Червоної Хмарини. Звідси вони нападають на тауренів. Вождь Гостробивень Терношкур живе у великій хатині в глибині ущелини.]],
            ["camp gevrek"] = [[Коло Землі осіло в таборі Гев’река на плато Небесного Вартового на північному заході Мулґора. Тут перебуває Мулн Лють Землі, очільник Кола. Нещодавно Коло уклало союз із Формувачами Вітру, шаманськими провідниками небонароджених ельфів острова Зефрас, і привело їх до Орди. Небонароджені, які звуть себе шен’дореями, працюють у таборі разом із тауренами-шаманами, друїдами й жерцем Ан’ше.

Старійшина-далекогляд Нуара Тремтливе Копито каже, що останнім часом природний плин магії порушився, і навіть маги Даларана спантеличені. Ніхто тут іще не може сказати, чи причина в арканічній магії, чи в неспокої самих стихій.]],
            ["camp narache"] = [[Табір Нараче — головне поселення племені Соколиного Вітру на північному краю плато Червоної Хмарини в південному Мулґорі. Вождь Соколиний Вітер навчає тут молодих тауренів і посилає здібних у світ. Ґрулл Соколиний Вітер зустрічає кожного новоприбулого, адже звістка про приїзд швидко шириться племенем.

Мати вождя, праматір Соколиний Вітер, є старійшиною табору. Вона тримається біля колодязя на плато Червоної Хмарини.]],
            ["galak camp"] = [[Кентаври племені Галак розбили табір у Мулґорі. Вони вважають ці рівнини своїми й клянуться спалити селища тауренів.

Галаки живуть у Тисячі Шипів. Тут на рівнині біля межі зі Степами стоїть лише їхній невеликий розвідувальний загін. Вершники Галаків їздять східним Мулґором, часто по двоє. Табір тримають Герак Грабіжник, який ловить здобич сіткою, та буревісник Укта.]],
            ["gloomrise"] = [[Сходом мороку блукають павуки, зокрема кришталеві. Там також вештаються невмерлі таурени.]],
            ["golden plains"] = [[Великі стада кодо збираються на Золотих рівнинах, у западині з хвилястою зеленою травою на південний схід від Громового Бескиду. Таурени вважають рівнини одним із найдорожчих куточків батьківщини й улюблених місць полювання. Кажуть, десь у траві тут живе знаменита самиця кодо Арра’чеа.]],
            ["kodo rock"] = [[Камінь кодо — природний кам’яний пам’ятник приблизно на півдорозі між табором Нараче й ущелиною Лезожини. Здалеку його не видно, тому мандрівникові треба придивлятися, щоб його знайти.]],
            ["palemane rock"] = [[Ґноли Бляклогривого племені живуть у скелі Бляклогривів. Печера заходить глибоко в схил гори на заході Мулґора. Крім житла всередині, вони мають табір зовні. Ґноли агресивні й нападають на кожного, хто підходить надто близько.]],
            ["ravaged caravan"] = [[На пагорбі біля північно-східного берега озера Кам’яного Бика лежить спалений караван «Авантюри». З уламків і досі здіймається чорний дим. Караван віз припаси до копальні наглядача Шуморакети, коли на нього напали таурени, які вже бачили цих гоблінів по всьому Мулґору. Уцілілі гобліни лишилися біля розбитих возів. Вони стережуть тліючий вантаж і відганяють усіх, хто наближається.]],
            ["red cloud mesa"] = [[Плато Червоної Хмарини — відкрита рівнина на високих скелях південного Мулґора, відома своєю тихою красою. У північно-західному куті стоїть табір Нараче, головний навчальний табір молодих тауренів. Тут вони доводять свою спроможність у бою зі щетиноспиними свинобразами, які тримають ущелину Лезожини на північному сході.]],
            ["red rocks"] = [[На північному сході Мулґора здіймається червоний пісковик. Тут таурени проводжають своїх найвідважніших мертвих до Матері-Землі й Батька-Неба крізь очищувальне полум’я. Такої честі удостоюються лише воїни, що допомагали заснувати й боронити Громовий Бескид або віддали життя за племена й вождів. Молоді воїни також приходять до скель, щоб ступити в доросле життя й почути благословення предків у вітрі. Нещодавно щетиноспині свинобрази увірвалися сюди й осквернили священну землю. Таурени Громового Бескиду лютують.]],
            ["rolling plains"] = [[Вовки, кодо, високоногі та пуми ділять трав’янисті Рокочучі рівнини. Вони вкривають значну частину південного Мулґора й простягаються від селища Криваве Копито до межі зі Степами. Вершники кентаврів блукають відкритими полями. На сході є гніздо вітролютих гарпій.]],
            ["skywatcher plateau"] = [[Стежка здіймається на високе плато на північний захід від Громового Бескиду й закінчується біля розмальованого каменя. Коло Землі має на вершині табір Гев’река. Його шамани наглядають за плато, де доглядач пильнує гурт вітробігів.

Між плато й небесними причалами Валанаара на острові Зефрас пролягає шлях. Тут спускаються на землю ті, хто щойно прибув до Азероту. Їх зустрічає гоблін-підприємець Брікс Ксіззікс. Він пропонує допомогти їм влаштуватися, якщо в них є гроші.]],
            ["stonebull lake"] = [[Довга підкова прохолодної води огортає селище Криваве Копито з трьох боків посеред Мулґора. Риби тут вдосталь, і багато годин минає з вудкою над озером. У найвужчому місці його перетинає міст. Дорога через нього сполучає Громовий Бескид із селищем.]],
            ["thunderhorn water well"] = [[У траві біля північної дороги між Громовим Бескидом і селищем Криваве Копито стоїть колодязь Громового Рога, один із трьох священних колодязів тауренів. «Авантюра» захопила його, щоб контролювати запаси води.]],
            ["venture co mine"] = [[«Авантюрі» відмовили в праві на видобуток у Мулґорі, але компанія все одно почала копати. Її шахта врізається у східні скелі. Гоблін-наглядач Шуморакета, відповідальний за роботи компанії у Мулґорі, керує шахтою від головного входу. Таурени обурені вторгненням.]],
            ["wildmane water well"] = [[На північ від Громового Бескиду лежить найпівнічніший зі священних колодязів тауренів — колодязь Дикої Гриви. Його теж захопила «Авантюра».]],
            ["windfury ridge"] = [[На висотах кряжа Вітролютих гніздяться гарпії. Вони пікірують на кожного, хто підходить до гнізд, щоб убити або забрати із собою. Довколишніми пагорбами ходять дикі пуми й вовки. Таурени Громового Бескиду й досі полюють на гарпій, бо їхнє яскраве пір’я прикрашає весілля й бенкети.]],
            ["winterhoof water well"] = [[Колодязь Зимового Копита лежить на краю Рокочучих рівнин у південному Мулґорі. Через кілька років після Третьої війни «Авантюра» захопила колодязь і отруїла його, щоб позбавити тауренів води. Мулл Громовий Ріг робить тотеми, щоб очистити отруту, та колодязь іще не очищено.]],
        },
    },
    [1413] = {
        text = [[Колись тут не було самого лише пилу. На цих землях ріс ліс, за яким доглядали нічні ельфи, і стояло кілька їхніх великих міст. Після Великого Розколу війна й лихо перетворили зелену долину на випалену сонцем рівнину. Тут спекотно й переважно рівно, лише де-не-де здіймаються пагорби та є кілька оаз, де збирається вода.

Незліченні покоління тауренів мандрували рівнинами слідом за кодо й громовими ящерами. Кентаври полювали на них заради розваги. Таурени відбивалися, коли доводилося, але не любили воювати й радше згортали намети та йшли далі. За роком миру завжди наставав рік війни. Потім на берег зійшли орки Тралла й тролі Темного Списа. Вони виступили проти кентаврів разом із тауренами Кривавого Копита.

Нині більшість краю утримує Орда. Серед трави стоять орочі господарства й дозорні вежі, а з півночі на південь простягається Золота дорога. З усіх боків нападають свинобрази й кентаври, а на півночі діють культисти Палаючого Клинка.]],
        areas = {
            ["agamagor"] = [[На північ від дороги, що веде від табору Таурахо на захід, щетиношкурі свинобрази тримають велике поселення. Вони викопують із землі криваві уламки й несуть їх у бій як тотеми сили й магії.]],
            ["bael modan"] = [[Кам’яна фортеця Бель'дун здіймається поруч зі старим селищем тауренів Кам’яного Шпиля. Поряд дворфи Залізогарта відкрили розкопки. Під пагорбом лежить давній дослідний комплекс титанів. Дворфи копають до нього, а більшість його реліквій досі лежить у темряві.

Дворфи використовують вибухівку, а Кам’яний Шпиль вважав цю землю священною. Більшість племені вбили або прогнали, а старе селище рознесли землерийні машини. Таурен Ґанн Кам'яний Шпиль, який ходить тутешніми дорогами, намагався владнати справу розмовою, та даремно. Тепер він жадає помсти.]],
            ["baeldun keep"] = [[Хитрий воєначальник генерал Двокосий править дворфською фортецею над розкопками Бель-Модана на півдні Степів. Його дворфи вороже ставляться до Орди. Твердиню стережуть воїни Бель'дуна, а ще вона має власні літальні машини.]],
            ["blackthorn ridge"] = [[Долину одразу на північ від краалю Бритвоболотих, столиці свинобразів, заполонив терен. Землю тут тримають бритвогриві свинобрази. На пагорбі в північному кінці кряжа стоїть табір орчині-шаманки Бріни. Вона добре знається на духах і природі води. Одразу під табором лежить ставок із напрочуд прозорою й чистою водою.]],
            ["boulder lode mine"] = [[Цю шахту на північному сході Степів тримає компанія «Авантюра», а керує нею бос Мідноштепсель. Колись він був найкращим інженером Спілки штукарів. Потім він перейшов до «Авантюри», прихопивши з собою свої найкращі винаходи.

У штольнях досі лишилися орочі дерев’яні підпори та прапори Орди. Схоже, колись шахта належала Орді.]],
            ["bramblescar"] = [[В Ожиновому прузі тримає лігво плем’я бритвогривих свинобразів. Через дорогу, в Аґама'ґорі, є поселення щетиношкурих. Ці племена воюють між собою. Бритвогриві нападають на кожного, хто наближається до їхнього лігва.]],
            ["camp taurajo"] = [[Поблизу гірського проходу з Мулґора до Степів таурени тримають заставу. Тут є корчма для подорожніх, які виходять із земель тауренів. У таборі також тримають бритвогривого свинобраза Кривозуба. Орки й таурени взяли його в полон, і тепер він чекає на страту.]],
            ["crossroads"] = [[Тут перетинаються дві дороги. Золота дорога веде з півночі на південь, а інша сполучає Брашпиль із Каміннопазуристими горами. Перехрестя — найбільше містечко Орди в Степах. Ночівлю знайти важко, зате торгівля жвава, і купці навперебій вигукують біля яток, що мають на продаж.

Обороною керує орк Торк. Якось ящери викрали з дозорної вежі вантаж срібла, призначеного на платню вартовим. Одразу за містечком лежить цвинтар, де Орда вшановує полеглих.]],
            ["dreadmist den"] = [[У вершині Зловісного Туману Палаючий Клинок має схованку, повиту темно-червоним туманом і вічними сутінками. Культисти, які там мешкають, поклоняються демонам, а туман ховає їх від очей.]],
            ["dreadmist peak"] = [[На північний захід від Перехрестя здіймається вершина Зловісного Туману. Червона імла густішає до самої верхівки. Це все, що лишилося від давнього демонічного прокляття. На вершині оселилися культисти Палаючого Клинка.]],
            ["dry hills"] = [[Попри назву, Сухі пагорби — один із найзеленіших куточків Степів. Вони лежать на крайньому північному заході, при підніжжі Каміннопазуристих гір. Їх утримують чарокрилі гарпії під проводом Серени Кривавоперої. Останнім часом вони нападають на каравани на півночі Золотої дороги. Посеред пагорбів стоять покинута ороча дозорна вежа й кілька катапульт.]],
            ["far watch post"] = [[Одразу на захід від мосту між Дуротаром і Степами Орда тримає дозорну вежу й кілька катапульт. Поруч стоїть ороча землянка, а трохи на південь двоє батраків доглядають загін їздових вовків. Служба тут нелегка. Від застави залежать каравани з припасами, і вона допомагає боронити Дуротар від Альянсу та свинобразів.]],
            ["field of giants"] = [[Стада громових ящірок і кодо блукають Полем велетнів на крайніх південних рівнинах Степів. Через них проходить південний відтинок Золотої дороги, який захищено гірше за північний. Його дозорні вежі здаються покинутими.

Орда досі тримається за поле. На кряжі вздовж його південної межі живе мудра шаманка Бріна. Тут шукає помсти й таурен Ґанн Кам'яний Шпиль, чиє плем’я втратило селище через дворфів.]],
            ["forgotten pools"] = [[На північ від дороги, що веде з Перехрестя на захід, лежать Забуті стави — найпівнічніша оаза Степів. Їхні береги зеленіють, а у воді живуть черепахи. Між дикими звірами біля ставів патрулюють колкарські кентаври.]],
            ["fray island"] = [[На острові Битв під проводом людини на ім’я Кланнок Маклеод тренуються воїни всіх народів і вірувань. Невеликий посушливий острів лежить біля східного берега Степів, на південь від Брашпиля. Бійці приходять сюди зустрітися й зійтися в бою перед натовпом глядачів.]],
            ["gold road"] = [[Довгий тракт Степів, Золота дорога, починається біля оплоту Мор'шан на півночі й тягнеться краєм до мосту, що сполучає північні й південні Степи. За мостом її називають південною Золотою дорогою.]],
            ["groldom farm"] = [[Кранал Фісс із дітьми розводять свиней на фермі Ґрол'дом, одній із багатьох орочих ферм, що постали після заснування Орґріммара. Бритвогриві свинобрази постійно на неї нападають.]],
            ["honors stand"] = [[Землянки й дозорні вежі, подекуди сильно пошкоджені, стережуть західну дорогу між Перехрестям і Сонцескельною криївкою. Тут відбулося багато великих битв Орди з її ворогами. Орки на форпості Честі добре знають його славетну, хоч і недовгу історію. Дорогу стережуть вартові Степів, а останнім часом на неї нападають колкарські кентаври.]],
            ["lushwater oasis"] = [[Оазис Рясноводдя лежить одразу на південь від Перехрестя. Це один із трьох великих оазисів Степів. До його ставів приходять пити дикі звірі, а колкарські кентаври скрадаються між деревами й полюють на них.

Тут є вхід до Плачучих печер, які вважають проклятими. Кажуть, звідти в озера оазису й тече життєва сила.]],
            ["merchant coast"] = [[Узбережжя Торговця назвали на честь торгівлі, що йде вздовж нього й неодмінно проходить крізь заповзятливі руки гоблінів Брашпиля. На цьому березі стоїть їхній порт, а в морі неподалік лежить острів Битв. Південний відтинок берега тримають флібустьєри Південних морів. Ґазлоу, очільник Брашпиля, призначив винагороду за голову барона Довгоберега за піратство й командування кораблями флібустьєрів.]],
            ["morshan base camp"] = [[Опорний табір Мор'шан стоїть одразу на південь від межі Ясенедолу, неподалік однойменного оплоту. Це одне з більших поселень Орди в Степах і осідок Вершників Пісні Війни.]],
            ["morshan rampart"] = [[Там, де на півночі закінчується Золота дорога, Орда звела оплот Мор'шан, щоб стримувати наступ Альянсу з Ясенедолу. Це нашвидкуруч зведена застава довкола дозорних веж. Звідси ж орки вирушають у набіги на Астранаар, містечко нічних ельфів на півночі.]],
            ["northwatch hold"] = [[Уцілілі учасники людської експедиції звели фортецю Північної варти одразу після битви за гору Гіджал. Тоді ці землі вважали нейтральними, але орки ніколи не довіряли фортеці. Коли великий адмірал Делін Праудмур прибув до Калімдору, щоб викорінити Орду, він зробив фортецю своєю твердинею. Орки билися тут із його кул-тіраським військом і перемогли.

Після смерті Деліна варта Терамора повернула фортецю. Джайні Праудмур це не подобалося, але її переконали залишити тут залогу. Мури фортеці перекривають прибережний підхід до Бруднолипкої трясовини з півночі. У залозі служать морські піхотинці Терамора. Капітан Честостанна командує з верхівки центральної магічної вежі. Каноніри Смайт і Вессан тримають дві дозорні вежі.]],
            ["raptor grounds"] = [[У маленькій долині південних Степів кишать сонцелускі раптори. Серед собі подібних вони незвичайні. Вони напрочуд розумні, споруджують грубі хатини й роблять власне знаряддя. Їх вабить усе блискуче чи просто незвичне. Вони вже поцупили багато речей із сусідніх поселень Орди.]],
            ["ratchet"] = [[Після Третьої війни воєвождь Тралл щедро заплатив Ґазлоу та його робітникам за допомогу в будівництві Орґріммара. Невдовзі по завершенні робіт Ґазлоу заснував Брашпиль на східному березі Степів. Починали тут контрабандисти, а згодом зійшлися й інші вигнанці.

Тепер це гоблінський порт. Більшість його торгівлі йде через Бухту Наживи й барона Ревілґаза за морем. У вежі над містечком живе гурт чорнокнижників.]],
            ["razorfen kraul"] = [[Десять тисяч років тому, під час Війни Древніх, велетенський вепр-напівбог Аґамаґґан виступив проти Палаючого Легіону. Він поліг, та його спротив допоміг урятувати світ від загибелі. Там, де його кров просочила землю, згодом виросли велетенські колючі лози. Свинобрази вважають себе його смертними дітьми. Вони оселилися серед терну й шанують його як святиню. Серце їхніх тернових поселень зветься краалем Бритвоболотих.

Ці велетенські тернові зарості на крайньому півдні Степів підкорила стара відьма Чарлґа Бритвобока. За її правління шамани-свинобрази нападають і на ворожі племена, і на селища Орди.]],
            ["shrine of the fallen warrior"] = [[Коротка стежина веде на невеликий пагорб на захід від Перехрестя. Там стоїть вівтар, кам’яний обеліск з ініціалами M K, вирізьбленими в основі. Перед ним стоїть цілитель духів Койтер.]],
            ["sludge fen"] = [[Колись тут лежало озерце з кришталево-блакитною водою. Потім компанія «Авантюра» звела над ним нафтову вишку й перетворила воду на трясовину з промислових відходів. Гоблін-бригадир Зубошип керує роботами з диспетчерської на верхівці вишки.]],
            ["southern barrens"] = [[Південні Степи — відкриті рівнини. На заході лежить Мулґор, на сході — Бруднолипка трясовина, на півдні — Тисяча Шипів. Травою блукають кодо, жеври, жирафи й громові яструби. Тут також полюють темноімлі павуки. На крайньому півдні свинобрази захопили землю й звели поселення серед терну.]],
            ["southern gold road"] = [[Південна Золота дорога завдячує назвою торговим караванам. Вона веде від Великого Підйомника на півдні Степів до мосту, що з’єднує північну й південну частини краю. На північ від мосту це просто Золота дорога.

Сюди приїжджають купці аж зі Штуковинська в Танарісі, Аубердіна на Темнобережжі й Нічної Гавані на півночі.]],
            ["southfury river"] = [[Південнолютна річка відділяє Степи від Дуротару. Одним із трьох мостів через неї проходить дорога з Дуротару до Степів. У гирлі ріка каскадом спадає у Велике море на північний схід від Брашпиля.

Одразу на північ від західного мосту до Орґріммара є ділянка води, де сходяться Ясенеділ, Азшара, Дуротар і Степи.]],
            ["stagnant oasis"] = [[Колкарські кентаври розбили табір на околиці Застійного оазису, між узбережжям Торговця та Золотою дорогою. Тут блукають заблукалі кодо Степів, слабкі й самотні, тож полювати на них значно легше, ніж на південних кодо. У воді плавають спотворені риби й озерні тріскощелепи.]],
            ["thorn hill"] = [[Бритвогриві свинобрази тримають Колючий згірок, чимале поселення на північному схилі гори між Перехрестям і Дуротаром. Останнім часом вони нападають тут на каравани Орди, чим розлютили місцеву варту.]],
            ["tidus stair"] = [[На південний схід від Брашпиля над берегом здіймаються широкі кам’яні тераси. Вони лежать одна над одною, мов велетенські сходи, з яких видно частину узбережжя Торговця. Дві тауренки, Іслен Морська Провидиця й Марен Небесна Провидиця, сидять тут, ловлять рибу й розмовляють із духами води.]],
            ["wailing caverns"] = [[Нічний ельф-друїд Наралекс відкрив ці печери й назвав їх на честь жалібного виття вітру й пари у скелях. Підземні річки тягнуться за багато миль під саваною й виходять на поверхню невеликими оазисами по всіх Степах. Якщо дивитися спереду, вхід трохи нагадує зміїний череп.

Наралекс вірив, що знову вкриє землю зеленню, якщо поєднає ці води зі Смарагдовим Сном. Він спустився з відданими учнями й поринув у медитацію, даючи Сну торкнутися Азероту крізь його тіло. Натомість його здолав Смарагдовий Кошмар. Вода просякла скверною, звірі набули спотворених подоб, а більшість його учнів збожеволіли й стали друїдами Ікла.]],
        },
    },
    [947] = {
        text = [[Десять тисяч років тому суходіл цього світу був єдиним материком — прадавнім Калімдором. Високородні необачно черпали магію з Криниці Вічності, і її відгомін сягнув Круговерті Порожнечі. Палаючий Легіон помітив це. Сарґерас спокусив королеву Азшару обіцянкою незмірної сили, якщо вона прикличе Легіон. Високородні відчинили в глибині Криниці велетенську браму.

Малфуріон Шаленство Бурі й нічні ельфи, які чинили опір, побачили, що Криниця відкрила шлях самому Сарґерасові. Малфуріон скористався Душею Дракона й перервав обряд бурею. Сарґераса та більшість його демонів відкинуло назад у Круговерть Порожнечі. Тоді Криниця обвалилася, й земля розкололася під ногами вцілілих. Більша частина давнього материка пішла під воду. З руїн постали розколоті материки, а затоплене серце суходолу стало Великим морем. Там, де стояла Криниця, досі крутиться Вир.]],
    },
    [1414] = {
        text = [[Коли Високородних не стало, нічні ельфи, що лишилися на розколотому материку, вирішили відгородитися від світу. Над краєм осів туман і сховав його від моряків. Серед людей Калімдор жив лише в старій легенді про країну, що розкололася й пішла під воду. Вищі ельфи Квел’Таласа знали правду, адже впродовж довгих років до них навідувалися нічні ельфи.

Навіть із початком Третьої війни більшість людей вважала Калімдор вигадкою. Серед тих, хто сумнівався, був і посол Кірін-Тору при дворі короля Теренаса. Дехто дослухався до застереження Медіва й відплив на захід, зокрема нова Орда Тралла й експедиція Джайни Праудмур. Вони знайшли цілий материк із льодами й лісами на півночі та пустелею на півдні. Тепер центральні й східні землі тримає Орда, а нічні ельфи живуть на північному заході.]],
    },
    [1415] = {
        text = [[Ці землі були частиною прадавнього Калімдору, доки Великий Розкол не відділив їх як три материки. На півдні лежить Азерот, а на півночі — Лордерон. Між ними — Каз-Модан, прабатьківщина дворфів і гномів. Його назва означає «гора Каза» на честь титана Каз’ґорота.

У Другій війні орки захопили Каз-Модан. Усі гірські твердині дворфів упали, окрім Залізогарта. Решту зайняли клани Кривавої Очниці й Драконової Пащі. Спустошені пустки розросталися, і диких звірів ставало дедалі менше. Дворфи, які могли втекти, утекли. Решта сховалася під землею й чинила опір.

Лордерон назвали на честь Лордейна, полководця імперії Аратора, який пожертвував собою в Трольських війнах. Північні, західні й південні землі здавна утримували люди, а східні — тролі. Вищим ельфам належать ліси далекої півночі, а Відреченим — Підмісто, де колись жили лордеронці.]],
    },
    [1416] = {
        text = [[Над цими вершинами важкі хмари майже не розходяться, і дощ іде частіше, ніж буває сухо. Нижче від засніжених вершин схили вкриті лісом. Біля підніжжя гір люди й вищі ельфи розгромили імперію Амані в останній битві Трольських воєн.

Колись тут стояли дві могутні держави. Альтерак був містом-державою серед гір, що згодом підкорила чималу частину північних земель. Даларан, місто Кірін-Тору, стояв біля Лордамерського озера. Альтерак упав за зраду під час Другої війни. Даларан зруйнували в Третій війні. Тепер, поки триває відбудова, його чарівники відкрили купол, яким накрили місто.

Руїни Альтерака тримають оґри Скелелами. Синдикат, збіговисько розбійників, яке зібрав принц занепалого королівського дому Аліден Перенольд, утримує Странбрад і навколишні угіддя. За решту земель точаться сутички. Глибоко в горах орки Морозних Вовків і дворфи з Варти Грозової Вершини змагаються за окрему долину.]],
        areas = {
            ["city of dalaran"] = [[Кірін-Тор відкрив великий магічний купол, який звів над серцем Даларана. За ним і досі триває відбудова міста. Чарівники, що пережили його знищення, повернулися, щоб підняти його з руїн, і до завершення роботи ще далеко.

Небонароджені з Високого Ордену знайшли тут друзів. Архімаг Ансірем Рунопис доклав зусиль, щоб зробити переправу повітряним катером між Далараном та островом Зефрас безпечною. Міські маги зустрічають небонароджених після прибуття. Вони попереджають гостей, що землі за межами міста значно небезпечніші, ніж здаються.]],
            ["dalaran"] = [[Маги Араторської імперії заснували Даларан після Трольських воєн. Згодом він став державою, якою правив Кірін-Тор на чолі з Радою Шістьох. Його Лілова Цитадель була святилищем дослідників арканічної магії. За межами Кель'Таласа жодне місто не зосередило в собі стільки магічної сили. Більшість магів-людей і вищих ельфів визнавали верховенство Кірін-Тору.

Скара взяла місто в облогу, а володар демонів Архімонд знищив його. Уцілілі чарівники повернулися відбудовувати місто. Вони звели величезний магічний купол над його серцем і під час робіт відбивалися від Відречених.

Тепер купол відкрито. Місто досі відбудовують, а вулиці стереже варта Кірін-Тору. Даларан однаково остерігається Орди й Альянсу, але прийняв небонароджених ельфів з острова Зефрас, що лежить над хмарами. Їхній Високий Орден сподівається врятувати острів арканічною магією за допомогою Кірін-Тору. Між островом і містом ходить повітряний катер.]],
            ["dandreds fold"] = [[На західному краю Верхогір'я стоїть невелика ферма з маєтком, від якої є вихід до гавані на Лордамерському озері. Тут живе лорд Аліден Перенольд, старший син короля Альтерака Ейдена Перенольда й останній відомий очільник Синдикату. Він називає себе володарем гір і наміряється знову закувати орків у кайдани.

З ним живе його коханка Еліза, а поблизу розквартировані вбивці й громили Синдикату.]],
            ["lordamere internment camp"] = [[Лордамерський ізоляційний табір стоїть на пагорбі над Далараном. Це єдиний такий табір в Альтерацьких горах. Його тримають даларанські чарівники, а залогою командує вартова Беламур. Вона приділяє своїм дослідженням більше часу, ніж службі.]],
            ["old dalaran ruins"] = [[На околицях Даларана розкидані рештки будинків, комор, веж і мурів. Руїни патрулюють чарівники Кірін-Тору та їхні елементалі землі.]],
            ["ruins of alterac"] = [[Під час Другої війни король Альтерака Ейден Перенольд зневірився в перемозі людей і уклав угоду з Ордою. В обмін на захист він дозволив оркам безперешкодно проходити своїми землями. Альтерацьких вояків бачили в бою на боці орків, а в таборі неподалік міста утримували полонених даларанців. Коли зрада викрилася, інші людські королівства рушили на Альтерак. Король Лордерона Теренас Менетіл II запровадив у місті воєнний стан і ув’язнив Перенольда.

Тепер у руїнах живуть скелеламські оґри на чолі з воєначальником Муґ'Толом. Палац уцілів наполовину, а церква й ратуша лежать у руїнах. Міська брама дуже схожа на браму Штормовію. Біля неї стоять розбиті м’ясні вози, а серед уламків валяються розтрощені балісти.]],
            ["uplands"] = [[Ці пагорби були житницею Альтерацького королівства. Коли королівство впало, Синдикат захопив їх і розбив тут кілька таборів. Ніде в горах він не має стільки сили, як тут.

У цих таборах можна зустріти барона Вардуса, колишнього альтерацького шляхтича, а нині інтенданта Синдикату.]],
        },
    },
    [1417] = {
        text = [[У цьому сухому й кам’янистому краї король Торадін звів Стром, столицю Аратора. Неподалік він збудував велику стіну, щоб захистити свій народ від тролів Амані. Коли імперія впала, імператорська варта, що лишилася там, заснувала Стромварт у старому місті. Стіна Торадіна й досі тягнеться північним краєм височини, подекуди обвалена й з широкими проломами.

Стромварт оминув чуму Скари, але впав під натиском Синдикату й брилоруких оґрів. Рештки його війська відступили до невеликої ущелини на півночі, яку тепер називають Опорним пунктом. Людських захисників очолює принц Ґален Тролебій. Вони й досі б’ються за зруйноване місто із Синдикатом та оґрами.

На сході Орда утримує Молотобій. Це колишній табір полонених орків, який вона захопила й перейменувала на честь полеглого воєвождя Орґріма Молота Згуби.]],
        areas = {
            ["boulderfist hall"] = [[Кор'ґреш Стужелют, оґр-маг і вождь клану Брилоруких, зайняв більшу з печер у цьому добре укріпленому оґрському пагорбі. Табір стоїть на півдні, поблизу віадука Тандола й селища Зів'ялої Кори.]],
            ["bouldergor"] = [[На північ від фортеці Стромварт здіймається нерівний, побитий тріщинами пагорб. Брилорукі оґри тримають на ньому укріплення, а поруч, на схилах, тиняються лісові тролі Сухокорі.]],
            ["circle of east binding"] = [[Камінь Східного Поневолення стоїть на сході височини Араті, поблизу Молотобою. За ним наглядають водяні елементалі. Це один із чотирьох каменів поневолення, розставлених по височині.]],
            ["circle of inner binding"] = [[Найсильніший із чотирьох каменів поневолення лежить тут, на півдні біля фортеці Стромварт. Камінь Внутрішнього Поневолення стережуть елементалі землі.]],
            ["circle of outer binding"] = [[Елементалі повітря кружляють біля Каменя Зовнішнього Поневолення посеред височини, поблизу Опорного пункту. Це один із чотирьох каменів поневолення, розставлених по височині.]],
            ["circle of west binding"] = [[Вогняні елементалі стережуть Камінь Західного Поневолення на заході височини, біля стіни Торадіна. Це один із чотирьох каменів поневолення, розставлених по височині.]],
            ["dabyries farmstead"] = [[Кената Дабірі господарює на півночі височини Араті зі своїми дітьми, Фарделом і Марселем. Вони мешканці Стромварта й вірні Альянсу, а їхні поля охороняє ополчення. Родина пережила Третю війну й зажила в достатку. Кіннота Стромварта під проводом лейтенанта Доблеклича патрулює дорогу між садибою й фортецею.]],
            ["drowned reef"] = [[Під водою бухти на південному узбережжі лежить затоплене ельфійське місто. Його захопили наґи Клинкоспини під проводом принца Назжака. Об риф над руїнами розбилося чимало кораблів, зокрема «Примха діви» й «Дух Срібнохвойного пралісу».

Схоже, наґи можуть керувати припливами в бухті. Команди, які заходять у бухту Фалдіра, сподіваючись знайти безпечну гавань, опиняються на скелях.]],
            ["drywhisker gorge"] = [[Ущелина прорізає гори на сході височини Араті, на північний схід від Молотобою, і закінчується печерою. Там живуть суховусі кобольди, союзники велетнів. В ущелині працюють їхні землекопи й землеміри. Поміж ними живе геомант Кремнештрик.]],
            ["faldirs cove"] = [[Коли Рейдери Чорноводдя на трьох кораблях увійшли в бухту по ельфійський скарб, їх зустрів дивний приплив. Ними командували капітан Сталепуз і капітан О'Брін. Приплив здійняли наґи, які стережуть затоплені руїни біля берега. Два кораблі пішли на дно. До берега дістався лише «Провісник», і його команда опинилася в пастці в бухті.

Бухту названо на честь Фалдіра. Кажуть, він позначив це місце, коли вирушив зі своїми послідовниками за море.]],
            ["goshek farm"] = [[Колись цією садибою володів Прімвелл Скай, ветеран Другої війни. Після Третьої війни її захопили Відречені й орки з Молотобою. Орки беруть тут припаси для Молотобою, а Відречені використовують землю для алхімічних дослідів. Ферму стережуть бугаї Молотобою.

Двоє агентів Альянсу, Кві й Кінелорі, прибули з’ясувати, що тут варять Відречені.]],
            ["hammerfall"] = [[Тут поліг Орґрім Молот Згуби. Після Другої війни Альянс Лордерона тримав на цій землі полонених орків в одному зі своїх найбільших ізоляційних таборів. Тралл і Молот Згуби повели Орду визволяти полонених. У сум’ятті бою лицар наскочив на воєвождя й простромив його списом зі спини.

Після Третьої війни Орда зайняла руїни як передову базу й назвала її Молотобоєм на честь Орґріма. Тут знайшли прихисток ті, хто відчував, що для них нема місця у світі. Брилорукі оґри й тролі Сухокорі уклали союз, щоб стерти Молотобій із землі.]],
            ["northfold manor"] = [[Ферма на північно-західному краю височини Араті після падіння Стромварта стала заставою Синдикату. Нині маєток і поля утримують розбійники, найманці й ловчі Синдикату.]],
            ["refuge pointe"] = [[Коли столиця Стромварта після Третьої війни обернулася на руїни, більшість її мешканців утекла на південь. Рештки війська лишилися, сповнені рішучості відвоювати свою землю, і тримають цю заставу. Звідси Альянс збирається відбити фортецю Стромварт і взяти під захист багатства височини.

Кіннотники Стромварта патрулюють дорогу до фортеці під проводом лейтенанта Доблеклича, командувача кінноти стромвартського війська.]],
            ["stromgarde keep"] = [[За переказами, король Торадін побачив чорного вовка, який блукав цим сухим краєм, і обрав це місце для столиці. Мечем Стром'каром він прокреслив у землі межі міста, і його каменярі почали зводити Стром, столицю першого людського королівства.

Під час Другої війни й після неї місто було однією з провідних сил Альянсу Лордерона. Тепер його розграбовано й поділено на три частини. Внутрішню твердиню тримає Синдикат. Колишнім кварталом магів володіють Брилорукі оґри за підтримки тролів Сухокорих. Останнім кварталом командує принц Ґален Тролебій із рештками свого війська.]],
            ["thandol span"] = [[Дві великі кам’яні арки несуть дорогу між Заболоттям Каз-Модана й височиною Араті. Дворфи Залізогарта звели їх після Війни Трьох Молотів, щоб підтримувати зв’язки й торгівлю з родичами з клану Дикого Молота. Рід Ковмарів стереже їх уже три покоління. Мости витримували цілі війська й були головним торговим шляхом між дворфами й людьми. Коли орки програли битву за Лордерон, Андуїн Лотар погнав Стару Орду через віадук назад до Каз-Модана.

Нині напад Чорного Заліза майже зруйнував один міст. Дворфи б’ються, щоб утримати другий і відбити містечко Дун-Модр. Багато з них уже загинуло.]],
            ["thoradins wall"] = [[Невдовзі після заснування Строма, столиці Аратора, король Торадін звелів звести великий мур для захисту від тролів Амані. Поколіннями він стеріг межу між височиною Араті й Передгір’ям Гіллзбраду.

За багато століть мур досі стоїть, хоча сильно пошкоджений. Каміння покришилося, а в стіні зяють широкі проломи.]],
            ["tower of arathor"] = [[Вежа Аратора стоїть у колишньому кварталі магів фортеці Стромварт. Її названо на честь Араторської імперії.

У цій вежі колись навчався архімаг Трелейн. Коли Синдикат і Брилорукі оґри взяли Стромварт в облогу, він намагався втримати вежу, але не зміг і втік із міста. Оґри захопили вежу й довколишній квартал. Тепер у вежі живе оґр-маг Руул Один Камінь.]],
            ["witherbark village"] = [[Довкола невеликого озера на південному сході височини Араті стоїть селище тролів Сухокорих. За селищем є велика печера, у якій часто можна зустріти ватажків племені.

Сухокорі уклали нетривкий союз із сусідніми Брилорукими оґрами проти Стромварта й Молотобою. Разом вони тримають частину самого Стромварта.]],
        },
    },
    [1418] = {
        text = [[Безплідні краї — суха потріскана земля, всіяна валунами й порізана звивистими ущелинами. З усіх боків її замикають гори. Тут виживають лише найвитриваліші тварини, зокрема койоти й канюки. У велетенській ущелині на далекому сході живуть нащадки чорних драконів.

Дворфи-старателі із Залізогарта приїздять на північ, де відкопали руїни Ульдамана. У його стінах знайшли перші підказки про походження дворфів. Каменесклепі троґґи, що прокинулися після тисячоліть сну, перебили дослідників і тепер боронять місто наче власне. Трохи південніше від руїн стоїть велика фортеця Чорного Заліза. Її дворфи воюють з оґрами клану Пиложерів і молодими драконами.

На північному заході стоїть Карґат, єдиний опорний пункт Орди в Каз-Модані. Воєвождь Тралл послав туди орків наглядати за відступниками з клану Чорнокаменю.]],
        areas = {
            ["agmonds end"] = [[Розвідувач Аґмонд керував дворфськими розкопками в Безплідних краях. Ці невеликі розкопки в південній частині краю лежали найдалі на південь. Їх заполонили троґґи, і тут Аґмонд зустрів свій кінець. Розкопки стоять покинуті й названі на його честь.]],
            ["angor fortress"] = [[З фортеці Анґора темнозалізні дворфи керують своїми роботами в Безплідних краях. Тут вони організовують дослідження Ульдамана, чиї багатства хочуть обернути на власну користь. У твердині також живе посол Інферн, вогняний елементаль на службі Раґнароса. Він наглядає за розкопками клану Тінегарта.]],
            ["apocryphans rest"] = [[На південь від Карґата в Безплідних краях розкинулися кості Спочину Апокрифана. Велетенський драконячий кістяк лежить там, де впав, і біліє на сухій спеці. Його облюбувала зграя голодних канюків, які гніздяться між ребрами.]],
            ["camp boff"] = [[Лише троє оґрів стережуть табір Бофф, південно-східний із чотирьох таборів Пиложерів у Безплідних краях.]],
            ["camp cagg"] = [[Бос То'ґрун, ватажок найманців із клану Пиложерів, обходить табори племені зі своїми охоронцями. Табір Каґґ — одна з його зупинок. Тут оселилася частина Пиложерів.]],
            ["camp kosh"] = [[Оґри з табору Кош нападають на каравани з припасами, які мусять перетинати Безплідні краї. Це найпівнічніший із таборів Пиложерів.

Зіґран Залізотес зі своїми дворфами мусив покинути розкопки Ульдамана. Вони залишили на дорозі вози та ящики, які пограбували оґри з табору Кош. Ті забрали всю зброю й усю їжу.]],
            ["camp wurg"] = [[Частина оґрів клану Пиложерів живе в таборі Вурґ на північному заході Безплідних країв. Ватага найманців боса То'ґруна зупиняється тут під час обходів.]],
            ["dustbelch grotto"] = [[На південному заході Безплідних країв здіймається великий пагорб із землі й каменю, домівка оґрів Пиложерів. Решта племені живе в таборах, розкиданих по обпаленій сонцем потрісканій землі довкола.]],
            ["dustbowl"] = [[Пиловий чан — широка рівнина на північному заході Безплідних країв, укрита сухими тріщинами. Нею блукають койоти, над нею кружляють канюки, а серед каміння ворушаться скельні елементалі. Тут зуміли прижитися лише кактуси й кілька дерев.

У цій пустці стоїть табір Вурґ, один із таборів оґрів Пиложерів.]],
            ["dustwind gulch"] = [[Пиловійна розколина прорізає суху, потріскану землю на захід від ущелини Летлор. Нею блукають каменесклепі троґґи, а скажені скельні койоти, гірські ловці й голодні канюки тут полюють.]],
            ["hammertoes digsite"] = [[Дворф Молотопалий Ґрез заклав ці розкопки на півночі Безплідних країв, коли шукав загублені артефакти титанів разом з істориком Карником. Тепер Ґрез покинув це місце. Його захопив гурт темнозалізних дворфів, імовірно, з того самого війська, яке зайшло в Ульдаман.]],
            ["kargath"] = [[Карґат — єдина застава Орди в Каз-Модані. Її названо на честь Карґата Гострорука, вождя клану Скаліченої Руки.

Воєвождь Тралл послав сюди Карґатський експедиційний корпус дослідити Безплідні краї. Його розвідники знайшли Ульдаман, розкопки, які високо цінують дворфи. Головна мета корпусу — знайти дорогу через Випалену ущелину до Чорноскельної гори, щоб Орда змогла вдарити по Ренду Чорноруку, воєвождю Темної Орди. Дорогою корпус натрапив на темнозалізних дворфів, і обидві сторони знову воюють.]],
            ["lethlor ravine"] = [[Широка скеляста долина тягнеться сходом Безплідних країв. Нею блукають молоді й дорослі чорні дракони. Серед скель стоять кристалічні обеліски.]],
            ["makers terrace"] = [[Темнозалізні дворфи патрулюють великі розкопки на Терасі Творця, одразу перед входом до Ульдамана. Землю зняли широкими пластами, залишивши розкопи просто неба.]],
            ["mirage flats"] = [[На Примарних рівнинах, на схід від Пилорижного гроту, живуть велетенські канюки, гірські ловці-патріархи й скажені скельні койоти.]],
            ["uldaman"] = [[За легендою, титани створили троґґів із каменю, визнали свою працю невдалою й замкнули їх у підземному сховищі. Потім вони спробували ще раз, і так з’явилися дворфи. Це сховище — Ульдаман.

Ще до Третьої війни дворфи із Залізогарта докопалися до нього й розбудили троґґів. Тепер усередину пробиваються темнозалізні дворфи. Вони сподіваються здобути для свого пана Раґнароса Диски Норґаннона, на яких записано, як створили дворфів.]],
            ["valley of fangs"] = [[Посеред Безплідних країв між двома масивними скелями лежить невелика долина. Там полюють вовки й пуми, і проходити нею небезпечно. Мартек Вигнанець, Смиколяп і Джазрік розбили в долині табір.]],
        },
    },
    [1419] = {
        text = [[Скелі Спустошених земель колись були жовтувато-бурими. Коли Темний Портал зруйнували, пекучий жар і нестримна енергія забарвили їх у багряне. Відтоді край лишився пустелею. Раніше він був частиною Чорних драгв, похмурого болотистого краю. Дні тут спекотні, а ночі пронизливо холодні. Гори затримують вологу з півночі. Тут не тече жодна річка, а коли зі східного моря насуваються бурі, дощ швидко збігає щільною землею назад у море.

Блискавки без упину б’ють у землю. Пустку заселили василіски й скорпіони, нею також блукають оґри. Тут знайшли прихисток рештки Палаючого Легіону під проводом лорда Каззака.

Лише одна дорога веде сюди з півночі. Її стережуть похмурі маги фортеці Підсвітньої Варти.]],
        areas = {
            ["altar of storms"] = [[Під час Другої війни Олтарі Бур витесали з рунічного каменя Каєр-Дерроу й увінчали бронзовими постатями. Крізь них текли темна й арканічна сили, спотворюючи ельфійські чари каменя. На цих олтарях маги-оґри здобували свої закляття. Навіть решта Орди трималася подалі від холодного каменя. Ельфи довідалися, що їхній священний камінь осквернено, й поклялися знищити кожен олтар у Східних Королівствах.

Залишилося тільки кілька олтарів. Цей стоїть на заході Спустошених земель. Тепер його займає культ тінеклятів зі своїми громилами, чорнокнижниками й жахоткачами. Серед них є леді Севіна, орчиня-чорнокнижниця, яка стала демоницею на службі повелителя жаху Разеліха.]],
            ["dark portal"] = [[Медів, людський маг під владою Сарґераса, й орк-чорнокнижник Ґул'дан прорвали в Чорних драгвах розлом між Дренором і Азеротом. Крізь нього прийшла Орда. Наприкінці Другої війни архімаг Кадґар зі своїми магами знищив браму, щоб орки не змогли повернутися.

Кам’яну арку, що стоїть тут тепер, звели, коли Нер'зул знову відкрив розлом. Обабіч стоять охоронці в каптурах із мечами в руках, а над ними вишкіряє ікла кам’яний змій. У вирву б’ють блискавки. Сама брама непорушна.]],
            ["dreadmaul hold"] = [[Оґри Жахобою тримають свій головний табір у фортеці Жахобою, давній твердині серед скель Спустошених земель. Тут править Ґрол-Винищувач, а в скелях довкола нишпорять голодні хихотуни й скорпоки.

Поблизу двоє магів крові досліджують місцевих звірів. Вони вважають, що сила, яка вивільнилася, коли відкрився Темний Портал, проникла в цих істот і надала їм нинішньої страхітливої подоби.]],
            ["dreadmaul post"] = [[Оґри Жахобою прийшли в Азерот із Дренору й ніколи не відходили далеко від Темного Порталу. Цей пагорб належить їм, і довкола них чимало. Маги фортеці Підсвітньої Варти кажуть, що вони служать лордові Каззаку.]],
            ["garrison armory"] = [[У понівеченій землі Спустошених земель шахтарі Альянсу видобувають корисні копалини для фортеці Підсвітньої Варти. Копальня зветься Збройницею Гарнізону. Видобуте відправляють до Штормовію, а натомість фортеця отримує припаси, потрібні, щоб вистояти в цьому проклятому краю.]],
            ["nethergarde keep"] = [[Фортеця Підсвітньої Варти стоїть на високому урвищі над єдиною дорогою до Спустошених земель. Її мури звели, щоб наглядати за руїнами брами, якої ніхто не хотів знову відчиняти. Після Другої війни архімаг Кадґар закликав збудувати фортецю, щоб крізь Темний Портал не прийшло нове військо загарбників. Даларанські маги заступили тут на варту й досліджували, як сила порталу змінила землю та звірів.

Даларан знищили в Третій війні. Тепер фортеця тримається завдяки караванам зі Штормовію. Її маги й вояки щодня б’ються з оґрами й демонами. Приводів для радості в них майже не залишилося.]],
            ["rise of the defiler"] = [[Поблизу середини Спустошених земель здіймаються гострі гори. Поміж ними живе могутній демон. Разеліх-Губитель, повелитель жаху й найстрашніший поплічник лорда Каззака, поставлений тут утримувати ці землі.]],
            ["serpents coil"] = [[Біля входу в ці звивисті печери на сході стоять вигорілі орочі будівлі, що лишилися з Другої війни. У печерах за ними культисти тінеклятів поклоняються демонові. Звідти їхнім культом править архімаг Аллістарж.]],
            ["tainted scar"] = [[Цей відтинок на заході Спустошених земель колись належав до Чорних драгв. Скверна Темного Порталу висушила воду й згубила дерева, а ґрунт забарвила в колір крові. Тепер тут нишпорять демонічні звірі.

Після поразки Палаючого Легіону на горі Гіджал лорд Каззак привів у Проклятий Рубець значну частину військ Легіону, що лишилися в Азероті, й оголосив його своїм. Він досі тут, і йому служить повелитель жаху Разеліх-Губитель. Біля тамтешнього олтаря оселився старий чорнокнижник Дайо Дряхлий. Він проводить обряди з демонами й навчає новачків пекельного мистецтва.]],
        },
    },
    [1420] = {
        text = [[Над Тірісфальським переліссям нависає похмуре зелене небо. Ці лісисті пагорби на північному узбережжі Лордерона просякла проклята чума Короля-Ліча. Дерева й чагарники тримаються за останні крихти життя.

За короля Теренаса тут були мирні господарства й містечка, де поколіннями щасливо жили родини. Перелісся впало одним із перших, коли принц Артас Менетіл плюндрував Лордерон. Люди помирали й повставали рабами Скари. Для решти викопували братські могили. Згодом леді Сильвана Вітрогін і її вільні Відречені зробили ці землі своїми.

У Відречених тут є вороги. Багряний Похід утримує кілька опорних пунктів, серед них Багряний монастир — твердиню своєї віри. Поплічники Скари досі оскверняють занедбані хутори й млини. У західних пагорбах паладини Відречених із Варти Тіра утримують фортецю Бандаріон і зберігають відданість Світлу.]],
        areas = {
            ["agamand family crypt"] = [[Одразу на північ від млинів Аґамандів лежить склеп, де цей рід ховав померлих. Командир Скари капітан Дарґол зробив його своїм штабом і найміцнішою твердинею млинів. Некромантією він підняв предків родини, кожне тіло й кожен дух у склепі, щоб воювати проти Відречених. У склепі темно й курно, а мстиві мерці нападають на кожного, хто заходить без дозволу.]],
            ["agamand mills"] = [[Вітряки Аґамандів стоять на пагорбах північного Тірісфальського перелісся. Колись вони мололи для заможної родини. Коли Скара вперше вдерлася в перелісся, Ґреґор Аґаманд відмовився йти. Його сім’я укріпила млини, запаслася харчами й переконала робітників залишитися та битися.

Оборону зламали зсередини. Девлін, молодший син, став на бік Скари, вбив двох вартових і провів невмерлих крізь пролом туди, де спали люди. Третина захисників загинула. Решти було замало, щоб утримати млини. Потім чума забрала всю родину. Тепер Аґаманди ходять власними млинами як бездумні мерці, а Скара тримає тут заставу.]],
            ["balnir farmstead"] = [[На північний схід від занепалої столиці Лордерона стоїть зруйнований хутір Бальнірів. Вони розводили великих білих коней, на яких їздив королівський рід Лордерона. Серед руїн нині ховаються слуги Скари, які прослизнули сюди з Чумнозем’я. У садку досі ростуть лев’ячі ротики, які тут колись доглядали.]],
            ["bandarion keep"] = [[Фортецю Бандаріон заклали як заставу лордеронського війська на вершині Північної скелі, на заході Тірісфальського перелісся. У перші дні Відречених залогу тут тримав Сріблястий Світанок під орудою лорда Максвелла Тіроса. Скелеламські оґри взяли фортецю в облогу, сподіваючись її пограбувати й з’їсти захисників. Відтоді Сріблястий Світанок відійшов до Східного Чумнозем’я. Тепер фортецю тримають паладини Варти Тіра під проводом Даніти Морр. Її названо на честь Ґарека Бандаріона, першого паладина Відречених.]],
            ["brightwater lake"] = [[Найбільше озеро Тірісфальського перелісся лежить на північний схід від Брілля. На великому острові посеред нього живе вільний ліч Ґюнтер Арканус.]],
            ["brill"] = [[Брілль був звичайним містечком Лордерона під владою роду Барових. Аґаманди тримали в ньому власний маєток. Кел'Тузад, тоді ще живий, обрав Брілль для перших дослідів із чумою невмерлих. Досліди вдалися настільки добре, що він переконав Короля-Ліча почати вторгнення раніше, ніж планувалося. За містечком заклали цвинтар для численних померлих. Захисники Брілля не змогли врятувати мешканців, їх вигнали з міста. Вони приєдналися до принца Артаса Менетіла в пошуках джерела чуми. Відречені відбудували Брілль, і тепер ним править війт Севрен.]],
            ["brill town hall"] = [[Ратуша — найпомітніша будівля Брілля. Зі свого помосту війт Севрен керує містечком і дає розпорядження та завдання Відреченим, які йому служать. Відречені керують небагатьма ратушами у світі. Ця — одна з них.]],
            ["bulwark"] = [[Верховний каратель Деррінґтон командує Валом, останнім бастіоном Відречених проти Скари на сході, де Тірісфальське перелісся сходиться із Західним Чумнозем’ям. Відречені й Сріблястий Світанок об’єдналися, щоб утримати межу. Деррінґтон наміряється знищити опорний пункт Скари по той бік. Над табором висить чумна імла, яка забарвлює небо в жовто-сірий колір. Таке небо є в Західному Чумнозем’ї, а в Тірісфальському переліссі більше ніде.]],
            ["cold hearth manor"] = [[Садиба Холодне Вогнище славилася затишком і багатими врожаями. Чума невмерлих убила всіх, хто тут жив або працював, і поля стали безплідними. Тепер вони кишать бездумними зомбі Скари. Будинок при головній дорозі тримають Відречені.]],
            ["crusader outpost"] = [[У східних пагорбах Тірісфальського перелісся стоїть дозорна вежа Багряного Походу. Звідти поборники стежать за головною дорогою, що йде переліссям на південь. Вони також використовують вежу, щоб ударити з флангу по кожному війську, яке спробує взяти Багряний монастир. Вежею командує капітан Вачон.]],
            ["deathknell"] = [[Решта поселень Відречених зберегла назви, які мали за людей. Смертедзвін перейменували, і ніхто не знає чому. Він лежить у добре захищеній долині. Щойно підняті Відречені спускаються до нього зі склепу, де вперше розплющують очі.

Скара, яку селяни звуть Бездумними, тримає північний кінець долини з кузнею, тож Відречені укріпилися довкола церкви. Тут важко вижити, а найбільше бракує золота. Золоту копальню на північному заході заполонили павуки, і селяни не полишають спроб її очистити. Долину стереже добірна Смертна варта.

Не всі підняті душі втратили Світло. У церкві паладин Араміс Молотобій зустрічає тих, хто й досі його відчуває, і навчає їх.]],
            ["faols rest"] = [[Тут, на сході Тірісфальського перелісся, поховано архієпископа Алонса Фаола, шанованого очільника Церкви Святого Світла. Він помер за якийсь час до приходу Скари.

До чуми невмерлих могилу часто відвідували скорботні. Тепер її майже забули й ніхто за нею не доглядає.]],
            ["gallows end tavern"] = [[У Бріллі Відречені тримають єдину свою відому корчму, яка працює на повну. У її льосі тримають у полоні багряного ревнителя й дворфа-горянина.]],
            ["garrens haunt"] = [[Пристанище Ґаррена колись було врожайною садибою на півночі Тірісфальського перелісся, з будинком, коморою, кількома зерносховищами й широким полем. Коли Скара захлиснула Лордерон, її слуги вбили Ґаррена і всю його родину. Чума зробила землю сірою й мертвою.

Тепер будинок і комору зайняли гнилошкурі ґноли на чолі з Червивим Оком. Вони нападають на кожного, хто наближається.]],
            ["gunthers retreat"] = [[На острові Ясноводного озера живе Ґюнтер Арканус, ліч із власною волею. Він не покидає острова, а його зомбі нападають на кожного, хто наближається.]],
            ["kings alley"] = [[Барон тримає Королівську алею в руїнах Лордерона. Він вимагає свіжого м’яса на плаху.]],
            ["lordaeron graveyard"] = [[Рат'маель блукає цвинтарем Лордерона й жаліє нещасні душі, які забрідають сюди. Місце разом із ним тримають полеглі берсерки.]],
            ["night webs hollow"] = [[Павуки зайняли цю невеличку долину й золоту копальню, прориту в ній. Молоді нічні колопряди блукають відкритою долиною, а дорослі снують копальнею й чатують по закутках у павутинні.

Молоді Відречені приходять випробувати себе на павуках надворі, перш ніж наважитися зайти глибше. У найдальшому закутку копальні сидить нічний колопряд-матріарх, найменша з павуків, до якої найважче дістатися.]],
            ["nightmare vale"] = [[Ця широка долина колись зеленіла й була повна лісових звірів. Тепер дерева повсихали, а голодні темні гончаки й велетенські кажани-вампіри пожерли решту звірини. Серед них полює рідкісний білий кажан на ім’я Рессан-Голкар.]],
            ["north coast"] = [[Пляж уздовж північного краю Тірісфальського перелісся виходить до Великого моря. Його тримають ненажерливі мурлоки й інші морські істоти.

Після чуми невмерлих берег потемнів і вихолов. На краю води гниють мертві морські істоти.]],
            ["ruins of lordaeron"] = [[Принц Артас Менетіл обернувся проти власного народу. Він повернувся до Лордерона на чолі війська й застав батька, короля Теренаса, у тронній залі. Там він його й убив. Стоячи над тілом, Артас проголосив, що королівство впаде й із попелу постане новий лад, який сколихне світ. Тоді за його наказом Скара ввійшла в місто й вирізала його мешканців.

Палац Лордерона досі стоїть над Підмістом, і в ньому досі чути звуки тієї години, коли загинув король. На подвір’ї шепочуть голоси, при вході калатають дзвони, вітальні вигуки зустрічають принца, а з тронної зали долинає гомін. Містяни Лордерона досі блукають подвір’ям, і ті, хто бачить мертвих, можуть зустріти їх там.]],
            ["scarlet monastery"] = [[Монастир на північному сході Тірісфальського перелісся колись був собором Церкви Святого Світла. У ньому були великі книгозбірні й семінарія, де навчали паладинів. Александрос Моґрейн у молодості провів тут кілька місяців у молитві й навчанні.

Після Третьої війни Багряний Похід зробив монастир своєю твердинею у війні проти Скари й Відречених. Поборники влаштували тут військовий табір і в’язницю. Вони ненавидять усі народи, крім людей, і вважають кожного чужинця можливим носієм чуми. Справжня господиня монастиря — верховна інквізиторка Білогрива.]],
            ["scarlet watch post"] = [[Капітан Мелрач командує дозорною вежею на північ від Багряного монастиря. Вона стоїть у глухому місці. Багряний Похід тримає її, щоб вороги не змогли вдарити по монастирю з півночі, де його важче обороняти.

Це одна з чотирьох застав поборників у Тірісфальському переліссі.]],
            ["shadow grave"] = [[Щойно підняті Відречені прокидаються в цьому склепі на вершині схилу в горах Тірісфальського перелісся. Тут на чатах стоять смертні вартові Балтеус і Гензель. Від входу протоптана стежка спускається до Смертедзвону.]],
            ["shadowvale"] = [[У зруйнованих будинках села Тіньова долина оселилися Заплямовані. Це паладини Відречених, які не змирилися з невмертям. Вони зберегли свою прижиттєву ненависть і тепер обертають її проти собі подібних. Ними керує командир Рудольф Ґельгардт.

Руїнами також блукають бездумні невмерлі.]],
            ["solliden farmstead"] = [[Фермер Солліден володіє цим гарбузовим хутором і вороже ставиться до Орди й Альянсу. Його люди — одні з небагатьох на півночі Лордерона, кого не торкнулася чума невмерлих. Вони досі працюють на грядках, хоч довколишній край занепав.

Переселенці з Аратора почали обробляти землю Тірісфаля, коли їхнє королівство зростало. Згодом шляхетні родини зі Строма викупили великі ділянки, які розчистили перші поселенці. Серед них був і рід Солліденів.]],
            ["stillwater pond"] = [[До чуми на Тиховодному ставку молодь тішилася життям. Родини з перелісся приходили на його береги відпочити, а діти, яким було зарано плавати в глибокому Ясноводному озері, вчилися плавати тут.

Тепер вода сіра. Риби під поверхнею — самі кістяки, що й далі плавають, наче ніхто не сказав їм спинитися. Берегом проходять бродячі невмерлі й дикі звірі. При воді нишпорить темний гончак Гибль і пожирає все, що необачно тут затримається.]],
            ["terrace of repose"] = [[На північ від входу до Багряного монастиря лежить невеликий клапоть землі, якого чума невмерлих ніколи не торкнулася. Багряний Похід доглядає тут зелені живоплоти, а у фонтані тече свіжа вода, тоді як вода в решті Тірісфальського перелісся застоялася.]],
            ["venomweb vale"] = [[Виводок отруйних павуків на чолі зі смертоносним Шрі'скрадом тримає долину Отрутоткачів, яка від них і дістала назву. До їхнього приходу тут зеленіла трава й росли здорові дерева, а мисливці знаходили оленів і кролів. Північним кінцем долини нишпорять темні гончаки.

Камінь із піритом позначає місце, де Ейґвін колись зустрілася з членами Ради Тірісфаля.]],
            ["whispering forest"] = [[Стрімка Північна скеля відтинає Шепітливий ліс від решти Тірісфальського перелісся високо в західних горах. Ліс стережуть паладини Відречених із Варти Тіра, що стоять у фортеці Бандаріон на скелі. Мурлоків Злобного Плавника вигнали з фортеці, і тепер вони заполонили урвища й озеро поблизу. Під деревами полюють скажені вовки.

В озері плаває невмерлий молотозавр, відомий як Чумногріб. На південний захід від озера лежать руїни села Тіньова долина. Поблизу середини лісу, у кільці велетенських грибів, блукає привид лицаря, прикутий до цього місця присягою.]],
            ["whispering gardens"] = [[На цьому пагорбі на південь від входу до Багряного монастиря відбулася велика битва. З одного боку стояли люди, які згодом заснували Багряний Похід, з іншого — військо Скари. У сутінках тут досі можна почути ледь чутний шепіт духів полеглих. Тепер землю тримають багряні маги, охоронці й розвідники.]],
            ["whispering shore"] = [[Вода біля Шушукаючого берега холодна й темна. Багатство, яке колись вабило сюди рибалок, зникло. Берег захопила ватага мурлоків під проводом лютого Муада. Вони нападають на кожного, хто забреде поблизу.]],
        },
    },
    [1421] = {
        text = [[Над трав’янистими пагорбами височать високі сосни зі сріблястою корою. До Третьої війни Альянс беріг цей праліс зеленим і неушкодженим. Потім сюди прийшла Скара, спалила врожай і перебила людей. Після падіння Лордерона доглядати за лісом не було кому. Дерева зблідли й захворіли, поміж ними повис примарний туман. Тепер у лісі тихо, лише часом долинає виття. По всьому краю розкидані занепалі хутори й покинуті копальні, де оселилися темні лісові створіння.

Відречені утримують північ і ведуть невпинну партизанську війну з гнилошкурими ґнолами. Їхнє право на ці землі оспорюють чарівники Даларана й агенти Скари, які зайняли частину спустошених полів. На півдні ще тримається кілька людських поселень. Їх захищають чарівники, надіслані з Даларана також для вивчення чуми й ворґенського прокляття. На південному заході під місяцем мешканці села Поховальні Вогнища перетворюються на ворґенів. Їх прокляв верховний маг Аруґал, який не полишає темних веж фортеці Тіньового Ікла.]],
        areas = {
            ["ambermill"] = [[До Третьої війни Бурштиновий Млин був непримітним лісорубним містечком. Потім Скара й Палаючий Легіон пройшли північчю. Кірін-Тор, що відбудовував Даларан, знайшов застосування містечку. Воно стоїть на завмерлій лінії сили, яку чарівники хочуть пробудити. За їхньої підтримки Бурштиновий Млин став єдиним справжнім осередком людського спротиву в пралісі. Млини, стайні й ратушу тримає Кірін-Тор, а Відречені бояться втратити Срібнохвойний праліс.]],
            ["berens peril"] = [[На пагорбах на південний захід від Бурштинового Млина, між головною дорогою й бічною дорогою з містечка, у Згубі Берена ховається ватага невмерлих. Вони готують напад на Крипту й служать некромантові Тулу Воронокігтю.]],
            ["dawning isles"] = [[Колись Світанкові острови були мальовничим гуртом низеньких острівців, що здіймалися над прозорою водою Лордамерського озера. До них дісталася чума невмерлих, і дерева захворіли. Берегами блукали мурлоки Злобного Плавника. Тепер їх так побільшало, що острови цілком у їхній владі.]],
            ["dead field"] = [[Ніхто не знає, хто господарював на Мертвому полі. Покинута ферма на півночі Срібнохвойного пралісу гниє. Гнилошкурі ґноли, слуги Скари, зробили її своєю базою. Їх дедалі більшає, і схоже, що вони готують напад. Відречені вже багато разів нападали на ферму й щоразу зазнавали поразки. Коли на ґнолів нападають, серед них іноді з’являється їхня провідниця, банші Нічнохльостка.]],
            ["decrepit ferry"] = [[Колись із цього берега на острів Фенріса ходив пором і за невелику платню возив людей та вантажі. Сусідні ферми продавали частину врожаю багатому острівному володареві та його родині. Потім Скара вдерлася до Лордерона. Поромника вбили, а пором знищили. Тепер біля причалів тісняться гулі, скелети й гнилошкурі ґноли. Тут небезпечно.]],
            ["deep elem mine"] = [[Чари Аруґала дісталися шахти Глибинний Елем у пагорбах середини Срібнохвойного пралісу. Тут оселилися ворґени зграї Місяцесказу. Її тунелі повняться ненажерами й темнодухами. Вони слухаються Ґрімсона Блідого, хитрого десятника, який колись керував шахтою.]],
            ["fenris isle"] = [[Острів Фенріса зі Світанковими островами утворює розірване кільце суходолу посеред Лордамерського озера. На цьому великому острові до Третьої війни стояла фортеця Фенріса, важлива військова застава Лордерона. Коли Скара захопила країну, усі на острові або втекли, або були вбиті. Тоді гнилошкурі ґноли зробили фортецю своєю базою, а їхній підступний господар Тул Воронокіготь тримає весь острів.]],
            ["fenris keep"] = [[У фортеці Фенріса колись стояла чимала частина війська Лордерона. Коли Скара захлиснула край, фортеця не встояла. Тул Воронокіготь, амбітний молодий маг, який колись служив Кірін-Тору, став на бік Скари й підкорив своїй волі місцевих ґнолів. Так вони стали Гнилошкурими. Він править фортецею, а його ґноли кидаються на кожного, хто наближається.]],
            ["greymane wall"] = [[Король Ґенн Сивогрив звів цю стіну, щоб відгородити Ґілнеас від світу. Йому набридло витрачати ґілнеаські податки на утримання таборів для полонених орків і слухати чвари між королями Альянсу Лордерона. У велетенській стіні є одна велика брама. Стіна не пустила Скару в його королівство. У її тіні таборують біженці, які тікають на південь із Лордерона. Вони виснажені й хворі, а брама для них зачинена.]],
            ["ivar patch"] = [[Ферма Айвара була приємним, заможним місцем. На нього працювало багато наймитів і слуг. Потім прийшла чума невмерлих. Айвар, його родина й усі наймити перетворилися на гнилих гулів і тепер кидаються на кожного, хто підходить. Самого господаря тепер звуть Айваром Нечистим. Тут у засідку потрапив загін розвідників Відречених, а Айвар поранив смертолова Квінна Йоріка. Квінн і Рейна Йорік тримаються в старому будинку Айвара.]],
            ["lordamere lake"] = [[За часів Альянсу Лордерона довкола Лордамерського озера процвітало багато людських королівств. На північному березі Лордерон звів столицю. Вірогідно, від неї озеро й дістало назву. Неподалік стояли Даларан і Альтерак. Та доба минула, а озеро стало межею між землями Відречених, Тірісфальським переліссям і Срібнохвойним пралісом, та спірними Альтерацькими горами.

Посеред озера лежить острів Фенріса, де гнилошкурі ґноли тримають стару фортецю війська Лордерона. На схід від нього невеликі Світанкові острови заполонили мурлоки Злобного Плавника.]],
            ["maldens orchard"] = [[Дерева саду Мальдена потемніли й стали вічнозеленими. Їхні плоди не збирають роками. Сад дістав ім’я від власника, який покинув дім, коли Скара вдерлася в Лордерон.

Тепер між деревами й довкола єдиної малої хатини саду мають лігва чорні варґи.]],
            ["north tides hollow"] = [[Западина Північного прибою лежить одразу на північ від Крипти у Срібнохвойному пралісі. Це один із багатьох притулків ворґенів Місяцесказу, слуг архімага Аруґала. Тут вони ставлять грубі табори з найнеобхіднішим для виживання. Істотам, що живуть завдяки іклам і силі, такого прихистку досить.]],
            ["north tides run"] = [[Північно-західний берег Срібнохвойного пралісу, де пляж зустрічається з Великим морем, зветься узбережжям Північного прибою. Найпомітніше тут старе покинуте судно, що лежить на березі. У воді блукають спотворені водяні духи. Рибалка Кілліан Саната тримає на пляжі вогнище й продає рибальські рецепти. Берега тримається й троль Тьєв Мордун.]],
            ["olsens farthing"] = [[Клапоть Олсена колись був жвавою садибою на головній торговій дорозі Срібнохвойного пралісу. Тепер вона лежить у руїнах. Ферму тримають невмерлі під проводом Тула Воронокігтя — скелети-рейдери й поневолені ним гулі. Вони нападають на кожного, хто наближається.]],
            ["pyrewood village"] = [[Удень Поховальні Вогнища — людське село з ратушею, кузнею й каплицею. Його мешканці пережили прихід Скари й досі продають подорожнім тканину, шкіру й кольчуги.

Потім настає ніч. Архімаг Аруґал прокляв село зі своєї фортеці Тіньового Ікла на урвищі. Щовечора люди стають ворґенами Місяцесказу й нападають на всіх поблизу, хоч би на чиєму боці ті були. На світанку вони знову прокидаються людьми.]],
            ["sepulcher"] = [[Крипта лежить у західних пагорбах над узбережжям Лордерона. Колись це був тільки великий цвинтар біля дороги через Срібнохвойний праліс. У його криптах спочивали померлі. Після Третьої війни Відречені зробили старий цвинтар своєю базою в краї, і місце, збудоване для мертвих, тепер служить невмирущим.

На півдні ворґени, на сході Скара, а на південному сході війська Кірін-Тору. Оточені майже звідусіль, Відречені тримають одне з небагатьох місць у пралісі, де Орда може стояти безпечно.]],
            ["shadowfang keep"] = [[Колись барон Срібляр володів цією твердинею на високому урвищі над селом Поховальні Вогнища. Коли Скара захлиснула Лордерон, архімаг Аруґал усупереч пораді Кірін-Тору викликав ворґенів.

Ворґени перебили військо Скари, а потім взяли фортецю в облогу й убили барона. Аруґал, збожеволівши від провини, прийняв ворґенів як дітей і зачинився всередині. Він назвав твердиню фортецею Тіньового Ікла. Кажуть, архімаг досі там, під охороною свого велетенського улюбленця Фенруса, а фортецею блукає привид барона.]],
            ["shining strand"] = [[Довгий берег Лордамерського озера тягнеться від столиці Лордерона на півночі до крутих пагорбів між Срібнохвойним пралісом і Альтерацькими горами. Це Сяйливий пляж.

Мурлоки Злобного Плавника тримають тут кілька поселень. Подорожнім, які не знають берега, тут небезпечно.]],
            ["skittering dark"] = [[Павуки захопили Дріботливу Темряву, покинуту копальню поблизу північно-західного берега Срібнохвойного пралісу. Мохові ловці повзають копальнею й довкола її входу, туманні павуки чатують у лісі одразу на схід, а між ними полюють велетенські сиві ведмеді. Час від часу поблизу нишпорить рідкісний павук Кретіс Тінеткач.]],
            ["south tides run"] = [[Південно-західне узбережжя Срібнохвойного пралісу, де земля зустрічається з Великим морем, зветься берегом Південного припливу.]],
            ["valgans field"] = [[На полі Валґана вирощували пшеницю, і воно назване на честь свого власника. Коли Скара прийшла до Срібнохвойного пралісу, його або вбили, або змусили втекти. З полів відкривався гарний краєвид на Лордамерське озеро.

Тепер це одна з покинутих ферм на півночі пралісу, на захід від Сяйливого пляжу. Спорожнілою фермою блукають здичавілі ворґени Місяцесказу.]],
        },
    },
    [1422] = {
        text = [[До чуми на схід від столиці Лордерона були ліси й сільські угіддя. Вогнеділ був осідком крайової влади, а до Андорала звозили зерно з північних провінцій і розподіляли його по всьому королівству.

Кел’Тузад і Культ Проклятих знали, що через зерно чума пошириться найшвидше. Вони заразили його й поставили по велетенському казану на полях чотирьох найбільших господарств. Коли Лордерон упав, ліси почали гинути. Із сосен осипається хвора бура глиця, а на їхніх стовбурах набухають нарости, мов пухлини. Над землею висить димчаста сіра імла.

Здається, сам край і досі чинить опір з усіх сил, які в нього лишилися. Багряний Похід тримає Вогнеділ і звідти завдає ударів по Скарі. Єдине мирне місце тут — могила Утера, пам’ятник Утерові Світлоносцю.]],
        areas = {
            ["bulwark"] = [[Після падіння Лордерона Утер Світлоносець влаштував тут табір для вцілілих, на межі Тірісфальського перелісся й Західних Зачумлених земель. Нині Відречені тримають цю землю проти Скари, а пліч-о-пліч із ними стоять вояки Сріблястого Світанку.]],
            ["caer darrow"] = [[Люди збудували фортецю Каєр-Дерроу багато років тому й поставили в ній стародавній рунічний камінь вищих ельфів. У Другій війні Орда вдерлася на острів, розграбувала фортецю й розтесала камінь на брили, з яких зробили Олтарі Бур. Ґул'дан скористався ними, щоб наділити магією своїх союзників-оґрів.

Після війни фортецю відновили. Вона стала маєтком роду Барових. У роки перед Третьою війною Барови стали жадібними й озлобленими. Вони хотіли зберегти багатство й землі навіть після смерті. Кел'Тузад, очільник Культу Проклятих, запропонував спосіб. Катакомби під маєтком стали Некроситетом, школою некромантії, а чуму невмерлих випробовували на слугах родини. Не минуло й пів року, як хвороба вирвалася назовні й убила всіх на острові. Їхні духи залишилися тут, і кожен мусить знову переживати останнє, що пам’ятає. Біля фонтана досі бігають наввипередки дві дівчинки, а пекар і далі продає хліб.]],
            ["chillwind camp"] = [[Табір Студовій стоїть при південному вході до Західних Зачумлених земель, там, де дорога спускається з Альтерацьких гір. Для подорожніх Альянсу це останнє безпечне місце. Його тримає невеликий загін Сріблястого Світанку. Вояків і знавців тут обмаль, тож Світанок покладається на найманців і веде партизанську війну проти Скари біля Андорала й чумних казанів. Тут також є командир Ашлам Доблокулак, якого королівство Штормовій і його союзники послали протистояти Скарі.]],
            ["dalsons tears"] = [[Сад Дальсона колись давав плоди родині, на честь якої його назвали. Тепер ферму тримає Скара. На полі височіє чумний казан, що дихає хворобою. Його стережуть гнилі зомбі, трухляві трупи й кістяні страхіття.]],
            ["darrowmere lake"] = [[Озеро Дарроумер — одне з найбільших у Східних Королівствах і одне з найпам’ятніших місць занепалого Лордерона. На півночі з ним сполучається ріка Тондроріл, на півдні — ріка Дарроумер. Посеред озера лежить острівне місто Каєр-Дерроу, де колись жив рід Барових. Тепер місто покинуте, а під ним лежить Некроситет, де Культ Проклятих працює серед своїх невмерлих.]],
            ["felstone field"] = [[Сквернокам'яне поле колись годувало живих. Скара захопила його й поставила посеред поля казан, із якого відтоді вириваються густі випари хвороб. Його стережуть скелетні чаклуни й потрошителі та слиняві гулі. Тут є і загін Багряного Походу, який мститься живим і мертвим однаково. У будинку на північно-східному краю поля Дженіс Сквернокамінь досі вдома.]],
            ["gahrrons withering"] = [[Ферма на східній межі Західних Зачумлених земель колись належала Ґарронові. У кращі часи її звали Розквітом Ґаррона. Нині тут нічого не росте. Скара захопила поле й поставила казан посередині. Його стережуть примарні видіння, голосливі мерці й голодні привиди, що пливуть над занапащеними грядками.]],
            ["hearthglen"] = [[Орда не взяла Вогнеділ у Другій війні. Скарі це теж не вдалося, хоча перед приходом мерців містяни щойно спекли хліб із зараженого зерна з Андорала. За мурами стоять ратуша, магічна вежа, лісопильня, стайні, копальня й фортеця Марденгольд, звідки керували краєм. Тепер місто й фортецю тримає Багряний Похід, а його воїни з-за мурів виходять у вилазки проти Скари.]],
            ["mardenholde keep"] = [[Тіріон Фордрінґ був володарем фортеці Марденгольд до відлучення. Після нього фортецю прийняв син Тейлан. Тепер він верховний лорд Багряного Походу, а фортеця — штаб Походу в Західних Зачумлених землях.

За Тіріона Марденгольд був центром торгівлі князівства Вогнеділ. За кілька років до Третьої війни фортеця повнилася високопосадовцями народів Альянсу, які проїжджали Вогнеділом у таємних дипломатичних справах.]],
            ["northridge lumber camp"] = [[Багряний Похід утримує цю лісопильню на півночі Західних Зачумлених земель, неподалік Вогнедолу. Похід високо цінує деревину, яку тут заготовляють. До Третьої війни лісопильнею керувала родина Натаніеля Дюма.]],
            ["ruins of andorhal"] = [[Андорал був житницею північного Лордерона. Його зерно розвозили містечками півночі. Перш ніж воно вирушило в дорогу, некромант Кел'Тузад і його Культ Проклятих заразили його чумою невмерлих.

Коли Скара прийшла по місто, відчайдушні захисники підпалили його, щоб Скара не змогла підняти з мертвих більше воїнів. Тепер воно лежить у руїнах. Гулі волочаться між поваленим камінням, скелети стоять там, де колись була варта, банші ридають над руїнами, а потвори човгають поміж уламків осель. Ліч Араж-Закликач зробив місто своєю базою й наглядає за чумними казанами по всіх Західних Зачумлених землях.]],
            ["scholomance"] = [[Рід Барових тримав свій маєток на цьому пагорбі над Каєр-Дерроу. Щоб зберегти статки після смерті, родина віддала маєток і склепи Кел'Тузадові та його Культові Проклятих в обмін на дар безсмертя від Короля-Ліча.

Культ зробив зі склепів школу некромантії, а Барови досі тут як невмерлі потвори. Ліч Рас Кригошепт править цим місцем і стереже його для Скари, а смертний некромант, темний магістр Ґандлінґ, очолює школу.]],
            ["sorrow hill"] = [[У мирні часи на пагорбі Скорботи ховали померлих Андорала, і багатих, і бідних. Коли прийшла чума й Скара почала нападати без упину, могил більшало швидше, ніж їх устигали позначати. Поспіхом насипані горбки досі вкривають землю, де полягли захисники. Зрештою вцілілі перестали ховати померлих. Вони спалювали їх у братській могилі на південь від кладовища, боячись того, на що чума їх перетворить. Коли принц Артас Менетіл убив Утера Світлоносця, на пагорбі звели велику гробницю й поклали до неї понівечене тіло паладина.

Чумні казани все одно підняли мертвих пагорба. Вояки й містяни стоять на варті над власними могилами.]],
            ["thondroril river"] = [[Ріка Тондроріл розділяє Західні й Східні Зачумлені землі. Вона тече на південь до озера Дарроумер, а за ним продовжується як ріка Дарроумер. На її берегах кишать личинки, кажани-вампіри, чумні ведмеді й павуки.]],
            ["uthers tomb"] = [[Могила Утера стоїть на пагорбі Скорботи. Це єдине місце в Західних Зачумлених землях, де Світло досі протистоїть загибелі краю.

Утер Світлоносець колись обороняв Андорал від Скари пліч-о-пліч із мудрецем Правдоносцем і Балладором Ясним. За його спиною стояли лицарі Срібної Десниці. Артас Менетіл поклав край їхньому спротиву. Він привів до міста військо невмерлих і вбив Правдоносця, Балладора й самого Утера.

Воїни Утера забрали його тіло, перенесли на південь від руїн Андорала й звели над ним велику гробницю. Надгробок показує його таким, яким він був за життя: з книгою Світла в одній руці та бойовим молотом у другій. Верховний жрець Тель'даніс доглядає й охороняє гробницю. Могила священна для всіх, хто йде за Світлом.]],
            ["weeping cave"] = [[Вхід до Скиглячої печери лежить на північному сході Західних Зачумлених земель, одразу на захід від ріки Тондроріл. У закутках повно болотних звірів і слизнів, а в темряві човгають гнилі бегемоти й трухляві страхіття. Серед них ховається рідкісний елементаль на ім’я Лузга.]],
            ["writhing haunt"] = [[У борознах Крученого Привида колись вирощували збіжжя для живих. Скара захопила поля й поставила посеред них великий казан, який відтоді працює без упину. Над борознами безперервно котяться випари хвороб.

На варті стоять гнилі й крижані гулі та смердючі зомбі, прив’язані до місця як охоронці. В одному з будинків ферми лежить Мулґріс Глибока Річка, таурен-друїд, що прийшов зцілити природу від наслідків чуми. Він помирає.]],
        },
    },
    [1423] = {
        text = [[До чуми тут були господарства й невеликі села. Усі вони тягнулися до Стратгольма, найбільшого міста Лордерона. Принц Артас Менетіл прибув до Стратгольма в пошуках джерела чуми й влаштував у місті очищення. Звідти він вирушив на північ, повернувся одним із лицарів смерті Короля-Ліча й убив власного батька, поклавши край королівству Лордерон.

Тепер тут панує Скара. Стратгольм — її південна столиця, якою править ліч Кел’Тузад. Багряний Похід утримує західні квартали, марно продовжує боротьбу й не пускає туди чужинців. Земля бура й хвора, дерева розпухли й стали схожими на велетенські гриби, а в повітрі висить помаранчева імла. Дорогами нишпорять некроманти й культисти Проклятих. З півночі нападають лісові тролі Амані. Лише біля Каплиці Надії Світла, в невеликому таборі Сріблястого Світанку, радо приймають кожного, хто готовий битися.]],
        areas = {
            ["blackwood lake"] = [[На цьому березі колись стояло містечко Чорнолісся, домівка великого маршала Отмара Ґарітоса, який правив ним як барон. Від містечка лишилася сама назва.

Тепер вода отруєна, і в ній звиваються спотворені водяні елементалі.]],
            ["browman mill"] = [[Скелети, банші й потвори тісняться на лісопилці Лобара, де блукають привиди, одразу на північ від Каплиці Надії Світла.]],
            ["corins crossing"] = [[Перехрестя Коріна лежить між Чумним Шрамом і озером Мерелдар. Тут сходяться дороги до Андорала, Дарроушира, Стратгольма й Десниці Тіра. Ратуша й кузня досі стоять серед руїн, але вулиці переповнені Скарою. Тут діють наставники й заклиначі Культу Проклятих, а над руїнами верещать банші.

Серед мерців ходять істоти, яких зовсім не видно, незримі слуги. Повз них ніхто не прослизне непоміченим.]],
            ["crown guard tower"] = [[Лордерон зводив такі дозорні вежі, щоб наглядати за кордонами й помічати ворогів здалеку. Коли Скара захлиснула королівство, вежу Королівської варти зруйнували. Тепер вона лежить у руїнах.

Орда й Альянс сперечаються за зруйновану вежу, бо кожен сподівається з її допомогою закріпитися в Лордероні.]],
            ["darrowshire"] = [[Дарроушир лежить у південних пагорбах Східних Зачумлених земель. У Третій війні Скара напала на нього й перебила захисників.

Вони піднялися гулями, духи яких замкнені в гнилій плоті, і служать Скарі. Дарроушир лежить у тиші й руїнах. Тут лишилися самі привиди та спогади. Привид маленької Памели Редпат досі не покинув його.]],
            ["eastwall gate"] = [[Східна брама — бічний вхід у Стратгольм. Вона виходить просто на площу Старійшин поруч із каплицею Алонсія. Там іще до Другої війни висвятили перших паладинів Срібної Десниці.

За брамою Багряний Похід і Скара б’ються за місто.]],
            ["eastwall tower"] = [[Східна вежа біля Каплиці Надії Світла була дозорною вежею Лордерона. Вторгнення Скари зруйнувало її, і над мертвою землею височіють самі руїни.

Орда й Альянс б’ються за ці руїни, бо кожен хоче утримати підступи до Лордерона.]],
            ["fungal vale"] = [[На північ від маєтку Маррісів і вежі Королівської варти лежить Грибкова долина. Земля тут стала темно-багряною під каламутною імлою. Чума невмерлих особливо глибоко вкорінилася в цій долині. Скара й Культ Проклятих вільно ходять спотвореним краєм.]],
            ["infectis scar"] = [[Чумний Шрам — глибока ущелина в зараженій землі неподалік перехрестя Коріна.

Її дном повзають слизні з живої гнилі та трухлявого намулу, а поміж ними пливуть примарні трупи й мародери.]],
            ["lake mereldar"] = [[Спотворені водяні елементалі рухаються озером Мерелдар, великою водоймою на південь від перехрестя Коріна. Його воду отруїла чума. На березі стоять руїни старого будинку, хижка й пором, які колись належали фермі.]],
            ["lights hope chapel"] = [[Каплиця Надії Світла, одна з найдавніших і найшанованіших святинь Церкви Святого Світла, стоїть на схилах гір на сході краю. Тепер її тримає невеликий табір Сріблястого Світанку. Світанок приймає бійців усіх народів і вважає союзниками і Альянс, і Орду.

Усередині командир Еліґор Світанковий із Братства Світла підтримує мир між Світанком і Багряним Походом. Він зустрічався тут із посланцями Походу, щоб скласти плани боротьби проти Кел'Тузада й Скари.]],
            ["marris stead"] = [[Маєток Маррісів стоїть на невеликому кряжі біля головної дороги. Тут багато років жив Натанос Марріс. Якийсь час тут жив і його двоюрідний брат Стефон, а леді Сильвана Вітрогін іноді навідувалася сюди.

Натаноса вбили, коли Скара захлиснула Лордерон, а потім Сильвана його звільнила. Тепер він один із Відречених і за її наказом повернувся додому зі своїми чумними гончаками. Він набирає воїнів Орди для боротьби проти Скари й Багряного Походу.]],
            ["mazraalor"] = [[Темні мисливці лісових тролів із племені Моходерів утримують Мазра'Алор, великий зикурат у серці Зул'Машара. У Зул'Машарі живуть воєвода Молот'джин і Зул'Брін Криводрев.]],
            ["northdale"] = [[Банші й незримі безокі наглядачі блукають розбитими будинками Північнодолу, знищеного містечка на північ від Каплиці Надії Світла й на південний схід від входу до Квел'Таласа. Поблизу є озеро, повне спотворених водяних елементалів.]],
            ["northpass tower"] = [[Вежа Північного ходу стоїть найдалі на півночі серед дозорних веж Східних Зачумлених земель і позначає дорогу до Квел'Таласа. Скара захлиснула Лордерон, і вежа досі носить шрами того часу.]],
            ["noxious glade"] = [[На Отруйній галявині стоїть густе хворобливо-зелене повітря, а земля забарвлена в темно-багряний колір. Галявина лежить на пагорбі на північ від Каплиці Надії Світла. Пошесть занапастила її більше за решту Зачумлених земель. Скара поставила тут чумний казан і спорудила бійню, а її створіння ходять отруєною землею.]],
            ["pestilent scar"] = [[Глибока ущелина розтинає заражену землю Східних Зачумлених земель. Схоже, вона природна. Можливо, тут колись було озеро, яке висохло з приходом чуми невмерлих. У глибині досі живуть слизні.]],
            ["plaguewood"] = [[До чуми цей ліс на південь від Стратгольма називали Зеленоліссям. Він зеленів і стояв у спокої, нагадуючи Ельвиннський ліс. Біля вхідної арки було невелике село. Коли Кел'Тузад почав свою справу, до села привезли отруєне зерно з Андорала. Першим лихо помітив місцевий вояк Лордерона, сержант Моріґан. Принц Артас ішов крізь ліс дорогою до Стратгольма.

Відтоді його годі було назвати лісом. Земля під ногами стала губчастою. Гриби й поганки сягнули висоти дерев і здіймалися над рештками старого лісу. Вони видихають темно-бурий газ, схожий на випари чумних казанів Скари. Ніхто не знає, чи гриби самі ростуть в отруєній землі, чи Скара вирощує їх для поширення недуги. Через ці зміни ліс прозвали Чумоліссям.]],
            ["quellithien lodge"] = [[Колись багато подорожніх зупинялися в хижині Квел'Лішен, таборі Далекоходців біля входу до Квел'Таласа. Це був один із двох великих осередків вищих ельфів у Лордероні.

На час Другої війни мисливцями тут керував ватажок слідопитів Соколиний Спис. Після вторгнення Скари до Квел'Таласа для хижини настали тяжкі часи. Її досі тримають його слідопити, серед яких Аврора Небоклич і Крісс Злотосяйна.]],
            ["scarlet base camp"] = [[Опорний табір Багряного Походу — невелике укріплення з барикад на східному березі озера Мерелдар, неподалік Десниці Тіра. Його тримають багряні вартові, священники й чарівники Походу.]],
            ["scarlet basilica"] = [[Багряна базиліка, великий собор у Десниці Тіра, — осідок найвищої духовної влади Багряного Походу. Тут можна зустріти лорда Походу Вальдемара. Базиліка стоїть поблизу абатства Десниці Тіра й пов’язана з далеким Багряним монастирем у Тірісфальському переліссі. Споруда дуже схожа на Собор Світла у Штормовії.]],
            ["stratholme"] = [[Загибель Стратгольма почалася із зерна. Збіжжя з Андорала, заражене Культом Проклятих, спекли на хліб. Містяни їли його й не знали, що помирають. Коли принц Артас Менетіл прибув з Утером Світлоносцем і Джайною Праудмур, чума вже ширилася. Артас вирішив, що єдиний спосіб не дати місту стати твердинею Скари — очистити його. Він наказав убити заражених містян. Утер і Джайна вважали це безумством і відмовилися. Артас пішов далі зі своїми воїнами. Вогонь пройшов вулицями, і майже всіх мешканців Стратгольма вирізали. Повелитель жаху Мал'Ґаніс, якого Артас прийшов убити, утік.

У місті оселилися невмерлі, і воно стало столицею Скари в Лордероні. Стратгольм досі горить. Одну половину руїн тримає Багряний Похід під орудою верховного лицаря Датрогана, іншу — Скара під проводом барона Рівендера. Вони б’ються без упину.]],
            ["terrordale"] = [[Страходіл — невелике містечко в північно-західному кутку Східних Зачумлених земель, на краю Чумолісся. Нині це місто-привид. Ним блукають Скара й зачумлені звірі, а з решти тут тільки купець Август Зворушений і мисливець на привидів Іґан. До приходу Скари торгівля Августа процвітала. Він купував і продавав усе, і досі торгує з кожним, хто проходить повз.]],
            ["terrorweb tunnel"] = [[Страхохід, довгий звивистий тунель крізь гору від Страходолу на півночі до ріки Тондроріл на півдні, повниться нападниками зі склепів. Часом тунелем скрадається нерубський наглядач, значно дужчий за решту. При виході до ріки стоїть Тіріон Фордрінґ.]],
            ["thondroril river"] = [[Тіріон Фордрінґ, один із перших паладинів Срібної Десниці, тримається східного берега ріки Тондроріл, неподалік зруйнованого фермерського будинку. Ріка позначає межу Західних і Східних Зачумлених земель. Вона бере початок на півночі й тече на південь до озера Дарроумер, за яким продовжується як ріка Дарроумер.]],
            ["tyrs hand"] = [[Лорд Багряного Походу Вальдемар тримає Десницю Тіра проти Скари. Це одна з останніх твердинь живих у Лордероні. В укріпленому місті багато церков. Церква Святого Світла вважає його однією з найдавніших і найшанованіших святинь. Тут стоять Багряна базиліка й укріплене абатство, а місто оточують міцні мури. Звідси посилають припаси й підкріплення іншим багряним твердиням, а кур’єри щодня з боєм прориваються сюди зі Стратгольма з донесеннями. Довколишня земля в кращому стані за решту Зачумлених земель, хоча дерева досі гниють.]],
            ["undercroft"] = [[Невмерлі тролі племені Моходерів облаштували лігво в склепі на південному заході Східних Зачумлених земель. Тут є і зомбі, і неживі Моходери. Ними керує Зельдарр-Вигнанець, велетенський троль, піднятий із мертвих. Час від часу його ватага грабує братську могилу Сріблястого Світанку біля Каплиці Надії Світла й тягне тіла до Підземної крипти.]],
            ["zulmashar"] = [[Моходери, невелике плем’я лісових тролів, колись правили із Зул'Машара. Довгі війни з людьми Лордерона спустошили їхні землі. Тролі відбили частину краю, та потім прийшла чума невмерлих і завдала ще більшої шкоди. Місто — лише тінь колишньої слави.]],
        },
    },
    [1424] = {
        text = [[Скара спотворила більшу частину Лордерона, але передгір’я Гіллзбраду досі виглядає так, як за часів королівства. Пагорби зелені, луки родючі, земля багата. Серед ланів де-не-де ростуть сосни, а дороги через пасовища з’єднують містечка. З озера Дарроумер на південь витікає річка.

І все ж це найкривавіше поле бою Азероту. Саме тут у Другій війні зійшлися в першій битві Альянс і Орда. Орочі рейдери нападали на прибережні містечка, а лісові тролі билися пліч-о-пліч з ними проти людей і вищих ельфів, які боронили узбережжя. Під час Третьої війни Тралл зібрав орочі клани, вночі пробрався до Південнобережжя й викрав кораблі, щоб перевезти нову Орду за море, до Калімдору.

Скара знищила Тарренський Млин. Відречені зробили містечко своїм найпівденнішим опорним пунктом і тепер тіснять людей Південнобережжя й полів Гіллзбраду, які стоять за Альянс. Обом сторонам дошкуляють розбійники Синдикату, мурлоки й наґи.]],
        areas = {
            ["azurelode mine"] = [[У Лазуровій копальні видобувають залізо для зброярень Альянсу. Шахтарі з полів Гіллзбраду працюють під наглядом десятника Бондса, а вартові стережуть їх. Копальня лежить на південному заході передгір’я, на південь від полів.]],
            ["chillwind point"] = [[З Чумних земель униз ущелиною дме холодний вітер. Саме він дав назву проліску Студовій. Колись цей перевал належав королівству Лордерон. На вершині пагорба стоять давні трольські руїни, де оселився самітник Бат’рах Вітрогляд, шаман із племені тропічних тролів і вправний зброяр.]],
            ["corrahns dagger"] = [[Височину Коррана тримають розбійники Синдикату. Це людські злочинці, якими керує знать занепалого королівства Альтерак. Вони ворогують як з Альянсом, так і з Ордою.]],
            ["crushridge hold"] = [[Біля руїн Альтерака, у печері під земляним пагорбом, оселилося чимало оґрів Скелеламів. Інші розбили табір довкола. У Другій війні королівство Альтерак уклало угоду з Ордою, і за цю зраду решта людських королівств ударила по його столиці. Більшість мешканців утекла. Тепер порожні руїни належать оґрам.]],
            ["darrow hill"] = [[Пагорб Дарроу лежить у північній частині передгір’я Гіллзбраду, під Верхів’ям. Відкритими полями блукають гірські леви й олені. У печерах передгір’я, серед жил альтерацького граніту, облаштували лігво єті.]],
            ["dun garok"] = [[Цю фортецю в південно-східних пагорбах утримують дворфи під проводом капітана Залізопагорба. Вони захищають людей Гіллзбраду й наглядають за Лазуровою копальнею. Відречені не терплять такого сусідства й прагнуть їх знищити.]],
            ["durnholde keep"] = [[У Другій війні сам Орґрім Молот Згуби напав на фортецю Дарнгольд, щоб визволити з її підземель трольського воєводу Зул’джина. Згодом фортеця стала центром управління таборами для полонених орків. Ними керував генерал-лейтенант Еделас Блекмур, самозакоханий п’яниця. Він знайшов ороче немовля біля тіл його вбитих батьків, назвав хлопця Траллом і виростив тут рабом і гладіатором.

Тралл утік, визволив орків із таборів, а тоді повернувся й узяв Дарнгольд в облогу. Він убив Блекмура в поєдинку й покликав дух землі, щоб зрівняти фортецю із землею.

Нині на схід від Тарренського Млина лежать її руїни. Колись у фортеці були казарми, вежа мага й арена. Тепер це опорний пункт Синдикату в передгір’ї. Звідси розбійники вирушають красти коней і вантажі з Південнобережжя.]],
            ["eastern strand"] = [[Східне узбережжя тягнеться вздовж південно-східного берега передгір’я Гіллзбраду. Західне лежить далі тим самим берегом. Ця піщана смуга належить наґам Клинкоспинів, які тримають пляжі й прилегле мілководдя.]],
            ["gallows corner"] = [[На перехресті Негідників в Альтерацьких горах, де сходяться дороги неподалік руїн Альтерака, стоїть порожня напівзруйнована дозорна вежа. Перехрестям заволоділи оґри Скелелами. Вони бродять поміж камінням довкола решток вежі, і більше тут нікого не видно.]],
            ["gavins naze"] = [[Височиною Ґевіна блукають гірські леви. Серед них іноді можна зустріти рідкісну левицю Араґу.

Дворфи з Варти Грозової Вершини стережуть тунель до Альтерацької долини, де їхній клан б’ється з орками Морозних Вовків. Разом з ними на варті стоїть сержант Дурґен Бурешпиль. Доброго слова про Морозних Вовків від нього не почуєш.]],
            ["growless cave"] = [[У глибині Охлялої печери в Альтерацьких горах горить Полум’я Узела, давнє обрядове вогнище. Довкола нього знайшли прихисток гірські єті, а біля входу часто можна зустріти єті на ім’я Зревун.]],
            ["headland"] = [[На схилі урвища Верхів’я відпочиває гірська левиця з невеликою гривою та смугастим хвостом. Це Араґа. Іншої такої кішки в цих пагорбах немає.

Дворфи з Варти Грозової Вершини тримають тут пост неподалік дороги до Альтерацької долини, де їхній клан веде відкриту війну з орками Морозних Вовків. Лейтенант Гаґґердін набирає новобранців до Варти.]],
            ["hillsbrad fields"] = [[Поля Гіллзбраду вкриті яблуневими садами й гарбузовими грядками, поміж якими пасеться худоба. Їхній урожай годує все передгір’я. У Другій війні Орґрім Молот Згуби наказав знищити містечко, щоб залякати інші людські королівства. Звістка швидко розійшлася. Після війни містечко відбудували.

Гіллзбрад і Південнобережжя — єдині землі колишнього Лордерона, яких Третя війна не спустошила вщент. Жодне з містечок не приєдналося до Багряного Походу, а їхні вартові й досі носять гербові накидки Лордерона. Війт Шкваростін керує з ратуші. Йому допомагають рада Гіллзбраду й писар Горрас Білогрив.

Відречені з Тарренського Млина на чолі з верховною карателькою Дарталією загрожують господарствам. Селяни влаштовують засідки. Зброю їм дають коваль Веррінґтан і його учні.]],
            ["misty shore"] = [[Туманне узбережжя тягнеться вздовж Лордамерського озера, між садибою Дандреда й Далараном. На мілководді неквапно рухаються черепахи.

Цей берег утримують двоє людей, союзники Багряного Походу. Вони нападають на кожного, хто підходить надто близько.

По той бік озера видно Світанкові острови, а вдалині — моторошну фортецю Фенріса.]],
            ["nethander stead"] = [[Маєток Нетандера лежить одразу на схід від Південнобережжя. Його покинуті поля заполонили брудноморді ґноли. Це єдине місце, де можна зустріти їхнє плем’я. Тут самі собою ростуть велетенські білі гриби, відомі як брудномордий цвіт.]],
            ["purgation isle"] = [[На південь від берегів Гіллзбраду з води здіймається висока спіральна скеля. На її вершині — цвинтар і руїни дозорної вежі. До Першої війни острів Позбавлення належав Кул-Тірасу.

Тут блукають десятки приречених духів людей і дворфів: паладини, жерці, ченці й маги, які досі не можуть знайти спокою.]],
            ["ravenholdt manor"] = [[Лорд Джорах Воронгольдт керує своєю Лігою вбивць із цього прихованого маєтку Рейвенхольдт в Альтерацьких горах. Вузька стежка піднімається сюди з плоскогір’я й петляє серед гір та крізь невелику печеру. До Ліги приймають лише винятково вправних. Чужинець, який пішов звідси без ножа в спині чи отрути в крові, може вважати, що йому пощастило.

Ліга роками воює із Синдикатом. Її агенти викрадають емблеми синдикатівців: із тим, хто загубить свою, розправляються його ж товариші.]],
            ["slaughter hollow"] = [[Оґри Скелелами живуть у кітлині Убивць, в оґрському кургані в глибині Альтерацьких гір.

У клітці вони тримають полоненого гнома Різза Незатяга. Він благає кожного перехожого не дати оґрам його з’їсти й торгує інженерними припасами крізь ґрати.]],
            ["soferas naze"] = [[Мис Софери над Гіллзбрадом тримає Синдикат. Тут отаборилися його грабіжники й злодії. Дехто з них уже дістався до темного пива з Південнобережжя.]],
            ["southpoint tower"] = [[Смертоловка Леш із Відречених стереже напівзруйновану Південну вежу на західному краю передгір’я Гіллзбраду, трохи південніше від дороги до Срібнохвойного пралісу. Звідти вона стежить за діями Альянсу в околицях.]],
            ["southshore"] = [[Південнобережжя було звичайним рибальським селом, коли сюди прибули тисячі човнів. Вони привезли вцілілих мешканців Штормовію, чиє королівство Орда знищила в Першій війні. Утікачі оселилися поруч із селом й присягнули новому Альянсові. У Другій війні містечко стало жвавим військовим портом. Орда прагнула заволодіти нафтою, на яку були багаті тутешні води. Зрештою вона захопила порт, і Орґрім Молот Згуби поставив свій флот на якір у гавані. По війні Альянс відбудував Південнобережжя.

На початку Третьої війни орки Тралла вночі прокралися до містечка й викрали кораблі, щоб попливти до Калімдору.

Тепер Південнобережжя — тихий порт, одне з небагатьох місць у Лордероні, де люди досі вірні Альянсу. Тут оселилися вцілілі після Третьої війни. Дехто з них колись був лицарем Срібної Десниці або магом Кірін-Тору. Вулицями ходять вартові, а трохи на північ живуть Відречені з Тарренського Млина.]],
            ["strahnbrad"] = [[Странбрад стоїть у північно-східних передгір’ях Альтерацьких гір. Це місто-привид із покинутою ратушею та кузнею. Колись воно належало королівству Альтерак, а після Другої війни відійшло до Лордерона.

Незадовго до Третьої війни орки Чорної Скелі напали на місто, щоб захопити рабів для жертвопринесення Палаючому Легіону. Странбрад боронила лише жменька піхотинців, та звістка все ж дійшла до лицарів Срібної Десниці. Утер Світлоносець вирушив до орочого табору, а принц Артас Менетіл поспішив боронити місто. Коли Артас прибув, напад уже тривав. Багато мешканців загинуло, але принц і вцілілі захисники розгромили орків та вбили їхнього ватажка, Рабовласника.

Тепер Странбрад — головна база Синдикату.]],
            ["tarren mill"] = [[На початку Другої війни лучники вищих ельфів зі Срібномісяця вирушили на південь, щоб оцінити загрозу від орків. На луках біля Тарренського Млина вони потрапили в засідку. Їх доправили до сусіднього табору полонених. Король Теренас послав воїнів Альянсу, і ті визволили бранців. Після цього рада Срібномісяця надала війська Квел’Таласа в розпорядження Альянсу Лордерона.

Нині містечко утримують Відречені. Церква, кілька будинків і всохлі сади занепали. Звідси Відречені воюють із містечками Альянсу — Південнобережжям і Дун-Ґароком. Землі між Тарренським Млином і Південнобережжям сумнозвісні через безперервні бої.]],
            ["thoradins wall"] = [[Невдовзі після заснування Аратора, коли його столицею став Стром, король Торадін наказав звести велику стіну, щоб захистити людство від тролів Амані. Вона тягнеться між передгір’ям Гіллзбраду та височиною Араті.

За багато століть стіну Торадіна тяжко пошкоджено. Від неї лишилися руїни.]],
            ["western strand"] = [[Західне узбережжя лежить на південно-західному березі передгір’я Гіллзбраду. Мурлоки Розірваного Плавника розбили вздовж берега невеликі табори, а Енді Мурґол патрулює околиці.]],
        },
    },
    [1425] = {
        text = [[Захід Внутрішніх земель тримають дворфи Дикого Молота. Тут вони приручають диких грифонів. Зв’язок між ними став таким міцним, що дворфи звели у своєму місті велетенський пам’ятник у подобі грифона. Лісові тролі, які володіли цим краєм раніше й лишилися тут після падіння імперії Амані, вважають, що дворфи захопили землі їхніх предків. Вони нападають на грифонячі гніздів’я.

Дворфи Дикого Молота майже нічого не знали про Орду, коли під час Другої війни орки ввійшли у Внутрішні землі. Вершники на грифонах під проводом тана Курдрана Дикого Молота зустріли загарбників із неба, жбурляючи в їхні колони заряджені грозою молоти й не даючи їм перепочинку. Воєвождь Орґрім Молот Згуби хотів цим нападом відтягти Альянс, поки сам ударить по Квел’Таласу. Андуїн Лотар розгадав задум, послав половину війська до ельфів, а сам бився поруч із Курдраном. Разом вони вигнали орків і їхніх союзників, лісових тролів. Курдран присягнув від імені свого королівства на вірність Альянсу.

Із трьох тутешніх трольських племен лише Сколотий Бивень став на бік Орди.]],
        areas = {
            ["aerie peak"] = [[Після Війни Трьох Молотів дворфи Дикого Молота повернулися додому, до Ґрім-Батола, і виявили, що смерть Модґуд осквернила фортецю. Жити там вони вже не могли. Після боїв із темнозалізними дворфами в тунелях вони не хотіли знову зариватися в камінь, тож звели Орлиний пік зовні гори.

Посередині височіє велике грифоняче гніздів’я, а в дальньому кінці стоїть форт Дикого Молота.]],
            ["agolwatha"] = [[Аґол'вату звели як храм імперії Амані, якої давно немає. Його зруйновані двори заполонили зелені слизні й нефритові драглі.]],
            ["altar of zul"] = [[Лісові тролі Миршавого Гілля тримають тут олтар. Це одна зі стародавніх твердинь Амані. Миршаве Гілля, наймогутніше з трьох трольських племен Внутрішніх земель, володіє нею й Джінта'Алом. На верхівці стоїть К'яґа-Хранителька.]],
            ["bogens ledge"] = [[Грот Боґена — печера на південному заході Внутрішніх земель. Довкола нишпорять люті совозвірі.]],
            ["creeping ruin"] = [[Холуйську руїну звели лісові тролі, а те, що вони залишили, заполонили ворожі слизні. Вони повзають серед розбитого каміння.]],
            ["featherbeards hovel"] = [[Поруч з Орлиним піком стоїть невелика хатина, домівка Пероборода.]],
            ["hiriwatha"] = [[Лісові тролі Сухокорі живуть серед давніх руїн Гірі'вати на південь від оселі Квел'Даніл. Коли до Внутрішніх земель прийшли посланці Орди, Сухокорі відразу їм відмовили. Час від часу тут можна побачити Зул'арека Лютолова, троля із цього племені.]],
            ["jinthaalor"] = [[Тролі імперії Амані звели Джінта'Алор і назвали його на честь Джінти, одного зі своїх давніх правителів. Серед міст лісових тролів більшим за нього є лише Зул'Аман. Нині місто тримає Миршаве Гілля й використовує його яруси як фортецю для жертвоприношень.

Підступна жриця Гекс править тут від імені Гаккара Здирача Душ. Щоб нагодувати його, Миршаве Гілля нападає на слабше плем’я Сколотого Бивня. Під час одного з набігів захопили старійшину Розірваного Бивня. Його досі тримають у місті. Капітана його варти, мисливця Малхора, вбили, а рештки кинули вовкам і слизням усередині мурів.]],
            ["overlook cliffs"] = [[Велика ріка Внутрішніх земель закінчується на Оглядових кручах. Там, де гори переходять у східне узбережжя, вона падає з краю одним могутнім водоспадом. Кручі стрімкі й оманливо високі. Багато подорожніх неправильно оцінили висоту й розбилися на смерть.]],
            ["plaguemist ravine"] = [[Над яром Чумної Імли висить туман. Вузька стежка пролягає на північ через гори в бік Каєр-Дерроу в Західних Зачумлених землях. Вхід лежить у лісі на захід від оселі Квел'Даніл. Яр дістав назву від хворобливої імли, що отруює цей єдиний шлях серед чистого, свіжого повітря решти Внутрішніх земель. Тут ніхто не живе.]],
            ["queldanil lodge"] = [[Високодільні ельфи тримають цю оселю як опорний пункт біля Орлиного піка. Це більший із двох великих осередків вищих ельфів, що лишилися в Лордероні, й одне з останніх їхніх поселень.

Після Третьої війни оселя стала осередком зв’язку. Посли високодільних ельфів зверталися до інших народів Альянсу й ділилися тим, що знали про тролів Сухокорих. Згодом ельфи уклали союз із дворфами Дикого Молота, чим розгнівили тролів Сколотого Бивня.]],
            ["revantusk village"] = [[Коли Друга війна розбила Стару Орду, багато лісових тролів без вагань покинули союзників-орків. Сколотий Бивень зберіг певну вірність Орді. Тролів було замало, щоб визволити полонених орків, та й ті, схоже, не надто прагнули свободи. Через це на плем’я напали інші лісові тролі. Воно перебралося на узбережжя Внутрішніх земель, сподіваючись лишитися непоміченим, і звело це село.

Згодом вони довідалися, що Тралл зібрав нову Орду й повернув свій народ до шаманських традицій. Тролі послали до нього найпрудкіших гінців і уклали угоду про дружбу. Інші лісові тролі звуть Сколотий Бивень слабкодухими ворогами, а Сколотий Бивень вважає їх зрадниками нової Орди.]],
            ["seradane"] = [[На північному сході Внутрішніх земель стоїть великий круглий портал, один із чотирьох входів у Смарагдовий Сон. У цьому лісі оселилися зелені дракони, серед них Ротос і Пантрувач сну.

Більшу частину лісів тримають зелені драконіди. Кожен загін очолює смарагдін-оракул, а поруч ідуть смарагдіни-гілкостражі й вартові дерев. На пагорбі на північ від порталу лежить череп невідомого дракона.]],
            ["shadraalor"] = [[Головне поселення Сухокорих лежить у Шадра'Алорі, серед старих храмів, які звели лісові тролі імперії Амані. Тут Сухокорі поклоняються лоа Шадрі.]],
            ["shaolwatha"] = [[Від Шаол'вати, старого храму лісових тролів на північному сході Внутрішніх земель, лишилося небагато.]],
            ["shindiggers camp"] = [[Рапсодій Жартогін, дворф, охочий до випивки, тримає невеликий табір у Внутрішніх землях разом із вищим ельфом Ґілверадіном Сонцеслідом. Дивна з них пара.]],
            ["skulk rock"] = [[Під час Другої війни Стара Орда влаштувала базу в цих руїнах лісових тролів, доки Альянс Лордерона не вигнав її звідси.

Відтоді руїни заполонили слизні. Тутешня печера — одне з небагатьох місць, де досі ростуть примарні гриби.]],
            ["valorwind lake"] = [[На північний схід від Шадра'Алора лежить тихе невелике озеро Звитяговій. На вигляд у його водах нема нічого особливого, та лише тут, наскільки відомо, росте таємничий гриб фіолетовий траґан.]],
            ["wildhammer keep"] = [[В одному кінці Орлиного піка, навпроти великого грифонячого гніздів’я, стоїть форт дворфів Дикого Молота. Їхній верховний тан Фальстад Дикий Молот править із вершини піка.

Більшість дворфів видовбує зали в горах. Дикий Молот будує просто неба. Так вони звикли після жахіть підземних боїв, які вели проти темнозалізних дворфів.]],
            ["zunwatha"] = [[Серед давніх руїн Зун'вати оселилися тролі Сухокорі. Скальпорізи й ревнителі племені пильнують поміж камінням.]],
        },
    },
    [1426] = {
        text = [[Дун-Морог укритий глибоким снігом, а його гори — найвищі у Східних Королівствах. Льодовики живлять річки, що зрошують зелені поля Каз-Модана, а з гірських надр дворфи видобувають руду без кінця. Гори оточують край з усіх боків, і нечисленні перевали стережуть дворфські війська.

Колись тут панували крижані тролі племені Морозної Гриви. Дворфські війська розбили їхню імперію й відтіснили їх до пагорбів. Дворфи й гноми стали близькими друзями. Дворфи допомогли гномам збудувати Гномреґан, а гноми поділилися знаннями про машини. Коли в Другій війні орки вторглися до Каз-Модана, обидва народи вступили до Альянсу. Завдяки силі дворфів і винаходам гномів орки так і не захопили жодної з їхніх столиць.

Тепер Гномреґан упав, а вцілілі гноми знайшли прихисток у Залізогарті. По всьому краю з’являються троґи. Тролі Морозної Гриви бачать, що війська Залізогарта зайняті троґами та війнами Альянсу, і дедалі частіше нападають на дворфів.]],
        areas = {
            ["amberstill ranch"] = [[На своїх угіддях біля дороги до Лох-Модана, на північ від кар’єру Ґол’Болар, дворфи Бурштинники розводять гірських баранів, на яких дворфи їздять верхи. Молодий Иарлин Амберстілл доглядає загін білих зайців. За отарою полює вендиго Ваґаш, і Рудра Амберстілл хоче його прогнати.]],
            ["anvilmar"] = [[Ковмар стоїть у Морозній долині. Це перше чимале містечко на її півночі. Посередині височіє зала, збудована довкола великої кузні.]],
            ["brewnall village"] = [[Родина Ячміноварів оселилася в селищі Всезвар у долині Крижаний Бриз поблизу Гномреґана. Реджольд Ячміновар очолює пошуки найкращого рецепта елю. Родина вдосконалює давнє дворфське пивоваріння й посилає молодих стерегти селище від диких звірів та шукати рідкісні складники для найдосконалішого елю.

Селище радше нагадує табір. Воно підпорядковане Залізогартові, хоч стоїть на гном’ячих землях.]],
            ["chill breeze valley"] = [[На снігу в північному й південному відгалуженнях долини Крижаний Бриз видно кров. Великі плями розповзлися по білому снігу, а пошматовані туші тварин лежать там, де їх кинули. Цими відгалуженнями ходить мало людей. Мисливці вистежують винних звірів, сподіваючись позбавити дворфські землі загрози. Багато хто не повертається. В одній із печер має лігво небезпечний вендиго.

Шлях зі сходу на захід легший. Він пролягає між Гномреґаном і Хараносом, тож молоді дворфи й гноми часто ним ходять.]],
            ["coldridge pass"] = [[Троґи заполонили Морозний тунель, що сполучає Морозну долину з рештою Дун-Морога. Новобранці-дворфи поодинці прямують ним до прикордонного Хараноса. Їм доводиться пробиватися крізь троґів або бігти повз них.]],
            ["coldridge valley"] = [[Морозна долина, відрізана від світу в південно-західному кутку Дун-Морога, лежить під глибоким снігом. Єдиний вихід із неї — Морозний тунель на північному сході. Тут стоять на варті дворфи-горяни, та долині все одно дошкуляють троґи й тролі Морозогривих.

Троґи з’явилися в пагорбах на південному сході й довкола замерзлого озера. Тролі здебільшого тримаються печери на півдні.]],
            ["frostmane hold"] = [[Поселення Морозогривих лежить біля західного краю холодних гір Дун-Морога, на південь від Гномреґана. Розкидані будівлі прилягають до мережі печер у схилі гори. Це головний табір крижаних тролів Морозогривих. Мисливці за головами й шкуродери стережуть усі підходи.]],
            ["gates of ironforge"] = [[Величну браму Залізогарта видно здалеку по всьому Дун-Морогу. Вона стоїть угорі широкого підйому, що веде на північ до гори, і відкривається в саме місто. Одразу за брамою чатує велетенська статуя верховного короля Модімуса Ковмара.

Він був останнім королем об’єднаних дворфів, справедливим і мудрим володарем, знаним за дипломатію з трьома великими дворфськими кланами. Коли він помер від старості, ще до коронації його старшого сина, клани почали війну між собою.]],
            ["gnomeregan"] = [[Гноми збудували Гномреґан під землею в передгір’ї Дун-Морога й наповнили місто залізом та винаходами. У Третій війні місто заполонили троґи-мутанти. У відчайдушній спробі їх винищити верховний майстер Ґелбін Меккаторк наказав відкрити резервуари з відходами, і зали заповнила радіація. Гноми сховалися від випарів і чекали, що троґи загинуть або втечуть. Троґи хворіли, та наступали далі. За кілька днів загинуло майже четверо з п’ятьох гномів. Уцілілі втекли до Залізогарта, а інші обернулися на прокажених гномів, бездумних і жорстоких.

Сікко Термоштепсель, колись довірений радник Меккаторка, збожеволів від отрути. Тепер він править зруйнованими залами як техноволодар троґів і прокажених гномів.]],
            ["golbolar quarry"] = [[На південному сході Дун-Морога дворфи тримають невеликий шахтарський табір біля великого кар’єру Ґол’Болар. Троґи захопили розкопки й копальню під ними. За шахтарями лишився тільки табір.]],
            ["grizzled den"] = [[Вендиго Посивілого лігва не розбігаються при появі чужинців. Вони збираються докупи, дихають морозом і виганяють зайд із великої мережі печер на південний захід від Хараноса. Мисливці йдуть по їхні гриви, цінні для оббивки сидінь. У скелях є жили міді, а в глибині чаїться міцніший вендиго.]],
            ["helms bed lake"] = [[Крига вкриває майже все озеро Постеля Гельма, але одну ополонку тримають відкритою, щоб набирати прісну воду. Кригою ходити безпечно. Берегом — ні, бо там бродять дикі тварини й заблукалі троґи.

На південь від озера дворфи Чорного Заліза захопили покинуту будівлю. Вони нападають на кожного, хто підходить надто близько.]],
            ["iceflow lake"] = [[Озеро Кригохвиля міцно замерзає на холоді Дун-Морога, та дворфи із селища Всезвар тримають у кризі одну ополонку й дістають із-під замерзлої поверхні прісну воду та рибу.

Ближче до середини озера здіймаються два острови, яких краще не чіпати. Ними заволоділа зграя голодних вовків на чолі з варґом на ім’я Тимбер. На островах більше ніхто не живе.]],
            ["ironbands compound"] = [[На південь від озера Постеля Гельма майстерня Залізоплета служить опорним пунктом дворфів Чорного Заліза. Вони нападають на кожного, хто підійде надто близько. Колись це було володіння Стурґі Залізоплета, майстра-коваля, який навчав тут свого ремесла. Потім загін Чорного Заліза напав на майстерню й убив усіх усередині.]],
            ["kharanos"] = [[Харанос стоїть поміж вершинами Дун-Морога, жваве містечко серед зимової глушини. Тут палає велика кузня, гуркотить гном’яча майстерня, а у винокурні Громовара наливають один із найкращих елів світу. За цим затишком Харанос є центром військової діяльності. Він обороняється від усіх загроз, що приходять із глушини.

Просто на захід лежить велика печера, повна лютих вендиго. На північному заході тролі Морозогривих укорінилися на вершині Блискучого кряжа й стежать за містечком унизу. Сенір Білобород вирішив їх звідти вигнати.]],
            ["misty pine refuge"] = [[Прихисток Імлистої Сосни — мала застава Сріблястого Світанку посеред Дун-Морога. Отець Ґевін — єдиний представник ордену, який тут стоїть.]],
            ["north gate outpost"] = [[Найпівнічно-східніше поселення дворфів у Дун-Морозі стоїть посеред проходу Північних воріт, який сполучає Дун-Морог із Лох-Моданом. Тут стоять горяни. Вони постійно відганяють диких тварин, які наступають із гір. Дехто пішов полювати на лютіших звірів і зник.]],
            ["north gate pass"] = [[Через прохід Північних воріт дорога веде з високих гір Дун-Морога до нижчих гір Лох-Модана. Ним найчастіше користуються подорожні до Заболоття й назад, бо він найближчий до спуску від озера. Тут стоїть застава Північних воріт.]],
            ["shimmer ridge"] = [[Морозогриві тролі утримують вершини Блискучого кряжа на захід від брами Залізогарта. Вони живуть у двох таборах, з’єднаних мостом, приручають кабанів і вирощують мерехтливу траву. Дворфи додають її в пиво, та доглядають траву саме тролі.]],
            ["south gate outpost"] = [[Дворфи тримають заставу Південних воріт посеред засніженого проходу до Лох-Модана. Тутешні горяни вже відігнали більшість звірів, що наступали на них. Тому цій залозі дошкуляють менше, ніж більшості інших у горах. Тут проходить багато подорожніх до Телсамара й назад.]],
            ["south gate pass"] = [[Подорожні до Телсамара йдуть через прохід Південних воріт, що сполучає високі гори Дун-Морога з нижчими горами Лох-Модана. Це найближчий до дворфського містечка прохід. Тут стоїть застава Південних воріт.]],
            ["steelgrills depot"] = [[Сховище Сталешквара лежить на схід від Хараноса. Це невеликий табір шахтарів та інженерів, які працюють на замерзлій землі Дун-Морога. Він належить Белдінові Стілґріллу. Тут чекають пілоти Облогової бригади, поки він лагодить їхні облогові машини.]],
            ["thunderbrew distillery"] = [[Ель винокурні Громовара відомий далеко за межами краю. Як каже Раґнар Громовар, цю дворфську таверну в Хараносі заснував його батько Аркілус Громовар. Раґнар керує нею, відколи зник його старший брат Лютобух. Корчму тримає корчмар Бельм.]],
            ["tundrid hills"] = [[Мало хто перетинає Тундрові пагорби без зброї в руках. У цих пагорбах на півдні центрального Дун-Морога, на захід від кар’єру Ґол’Болар, бродять кілька видів ворожих звірів. Дехто й досі йде навпростець звідси між Морозною долиною та східним Дун-Морогом, хоча дорога через Харанос набагато безпечніша.]],
        },
    },
    [1427] = {
        text = [[Понад двісті років тому земля тут розверзлася. До того цей край був частиною Багрянокряжових гір. Чаклун-тан Тауріссан із дворфів Чорного Заліза шукав сили, яка переломила б Війну Трьох Молотів на його користь. Він і семеро найдовіреніших дворфів покликали прадавні сили, що спали під світом. На їхній поклик озвався володар вогню Раґнарос, жахливіший за всі їхні кошмари. Чорноскельна гора вирвалася з кряжа, столиця Чорного Заліза Тауріссан обернулася на руїни, а долина на півночі стала почорнілим розломом — Випаленою ущелиною.

Чорному Залізу потрібна була земля для робіт, а в ущелині було мало мешканців і воїнів. Велике військо Чорного Заліза розгромило дворфські залоги й змусило рабів розкопувати середину долини. Поруч із ними ущелиною ходять бойові ґолеми й елементалі.

Торієве братство, дворфи Чорного Заліза, що відокремилися від клану, утримує власне містечко на півночі ущелини.]],
        areas = {
            ["blackchar cave"] = [[Чорновугільна печера на південному заході ущелини, поблизу Чорноскельної гори, запечатана. Що в ній приховано, ніхто не знає.]],
            ["blackrock mountain"] = [[Війська Бронзобородих і Диких Молотів ішли винищувати клан Чорного Заліза, коли кряж розверзся й з нього виросла Чорноскельна гора. Королі Мадоран і Хардрос повернули війська назад, щоб не стати до бою з володарем вогню, який з’явився разом із нею. На місці королівства Чорного Заліза піднявся вулкан. Раґнарос спустився в його ядро й змусив уцілілих дворфів видовбати під вулканом нове місто.

Тепер гору ділять дві сили. З Палаючого Ядра править Раґнарос зі своїми темнозалізними дворфами, ґолемами й елементалями. Вище, у лігві Чорного Крила, пильнує Нефаріан. Йому підкоряється Темна Орда орків Чорнокаменю. Обидва заміряються зібрати військо й захопити Азерот.]],
            ["cauldron"] = [[Темнозалізні вирили посеред ущелини Котел, величезні розкопки, обставлені їхніми великими землерийними машинами. Після виклику Раґнароса вони укріпили це місце. Унизу розпеченими розколинами ходять елементалі вогню й магми. Раби, здебільшого полонені вороги, працюють без упину. Праця, спека й господарі звели їх із розуму, і вони нападають на кожного, хто втручається, навіть на тих, хто прийшов їх визволити.]],
            ["dustfire valley"] = [[Вітри змітають пил із долу Вогнепилу, який тягнеться крізь ущелину на північ. Наприкінці долу стоїть брама Каменярського тунелю. За нею лежить долина Королів у Лох-Модані.]],
            ["firewatch ridge"] = [[Кряж Вогневарти височіє над величезним Котлом. Тут міститься головний табір темнозалізних дворфів у Випаленій ущелині. Дворфи тримають схили разом із механічними ґолемами й велетенськими вогняними павуками, тож ступати на кряж небезпечно.]],
            ["grimesilt dig site"] = [[На розкопках Бруднохмурого колись працювали дворфи із Залізогарта. Темнозалізні дворфи захопили розкопки й досі їх утримують. На дні ями лежить поранений Дорій Камнеглад, один із перших робітників.]],
            ["sea of cinders"] = [[Вугільне Море — відкрита рівнина на півдні Випаленої ущелини, трохи на північ від Чорноскельної гори. Тут нічого не росте. Земля ще тліє, а вітер без упину здіймає попіл і несе його над голою рівниною. Вогонь і вітер залишили по собі саму пустку, а горіння досі не припинилося.]],
            ["slag pit"] = [[Глибоко в Котлі лежить Шлакова Яма, підземна копальня, багата на руду. Нею правлять жорстокі темнозалізні дворфи. Копають раби, яких підганяють наглядачі й работорговці. Темнозалізні відкрито ворогують із кожним, хто заважає їм добувати руду, а в глибинах нишпорять ненажерливі вогнезаври.]],
            ["stonewrought pass"] = [[Цей тунель крізь гори спроєктував Франклорн Файноков, темнозалізний архітектор, який також наглядав за будівництвом Каменярської дамби. Тунель веде на північний схід від початку долу Вогнепилу до долини Королів у Лох-Модані.

Коли темнозалізні захопили дворфські залоги в ущелині, решта дворфів відступила до Лох-Модана й запечатала прохід. Брами досі замкнені, а ту, що з боку Лох-Модана, стереже горянка Щебінка. Вона відсилає подорожніх назад.]],
            ["tanner camp"] = [[Сара Кожум'яка, майстриня шкірництва стихій, живе в єдиному наметі цього невеликого табору. За наметом довгий звивистий прохід веде до лігва великої громової ящірки. Довкола табору повзають кришталеві павуки й вогняні жуки, а поміж ними полює лавовий павук Рекк'тілак.]],
            ["thorium point"] = [[Розпорядник Слизькорук очолює Торієве братство, темнозалізних дворфів, які покинули свій клан. Вони збудували Торієвий табір на урвищах крайньої півночі ущелини, над Котлом. Звідти вони пильно наглядають за тим, що роблять їхні колишні одноплемінники. Містечко нейтральне. Його кузня й ковадло завжди готові до роботи. Ковалів Братства вважають одними з найкращих, яких бачив Азерот. Кажуть, вони вміють кувати навіть зброю самого Раґнароса, та їм бракує людей, які зібрали б усе потрібне для роботи.]],
        },
    },
    [1428] = {
        text = [[Небо над Палаючим степом червоніє від вивержень Чорноскельної гори. Кам’янисте передгір’я перетинають ріки лави, земля обвуглилася, а повітря лишається гарячим і сухим. Тутешня дорога — єдиний сухопутний шлях зі Штормовію до Каз-Модана та Лордерона. Нею часто їздять, хоча це небезпечно, і Штормовій майже полишив її напризволяще.

Колись край був частиною Багрянокряжових гір. Під час Війни Трьох Молотів чаклун-тан Чорного Заліза Тауріссан спробував прикликати слуг-елементалів, але викликав володаря вогню Раґнароса. Гори розплавилися, а на місці його появи виріс вулкан. Уцілілі дворфи Чорного Заліза стали його маріонетками.

Після Другої війни тут оселилися орки. Орки Чорнокаменю утримують одне з небагатьох сталих орочих поселень в Азероті й не визнають перемир’я Тралла з Альянсом. Краєм блукають вогнечереві оґри. Чорні дракони під проводом Нефаріана утримують верхні рівні Чорноскельного шпиля, а в його глибинах правлять дворфи Чорного Заліза. Кажуть, там і досі чаїться Раґнарос.]],
        areas = {
            ["altar of storms"] = [[Під час Другої війни Олтарі Бур витесали з рунічного каменя Каєр-Дерроу й увінчали бронзовими постатями. Крізь них текли темна й арканічна сили, спотворюючи ельфійські чари каменя. На цих олтарях маги-оґри здобували свої закляття. Навіть решта Орди трималася подалі від холодного каменя. Ельфи довідалися, що їхній священний камінь осквернено, й поклялися знищити кожен олтар у Східних Королівствах.

Залишилося тільки кілька олтарів. Цей лежить у тіні Чорноскельної гори. Біля нього клан Чорнокаменю досі проводить свої обряди. Олтар стережуть чорнокнижники клану.]],
            ["blackrock mountain"] = [[Чорноскельна гора мала це ім’я за кілька століть до того, як сюди прийшли орки Чорнокаменю. Вона піднялася з руїн темнозалізного королівства, коли Раґнарос увірвався у світ. Війська Бронзобородих і Диких Молотів ішли винищити темнозалізних. Їхні королі Мадоран і Хардрос побачили, як вогняні бурі поглинають землю, й повернули війська до своїх королівств. Раґнарос відступив у розпечене серце гори й змусив уцілілих темнозалізних дворфів видовбати під нею твердиню — Тінегарт.

У Другій війні Орда захопила Чорноскельний шпиль, фортецю всередині гори, й зробила його опорним пунктом походу на Лордерон. Тепер за всю гору змагаються Раґнарос і Нефаріан. Володар вогню править із ядра вулкана разом із темнозалізними дворфами та елементалями. Вершину тримає Нефаріан з орками Чорнокаменю та своїми чорними драконами.]],
            ["blackrock pass"] = [[Чорноскельний прохід лежить на межі двох світів. З одного боку тихі зелені пагорби Багрянокряжових гір. З іншого — Палаючий степ, випалений і понівечений до невпізнання. На межі стоїть брама, яка чітко розділяє ці землі. Це головний шлях у степ із півдня.]],
            ["blackrock stronghold"] = [[У тіні Чорноскельного шпиля, фортеці з чорного каменю, клан Чорнокаменю тримає могутню твердиню на півночі Палаючого степу. Місцеві орки тримаються подалі від дороги й повсякчас пильнують, чи не нападе Альянс. Вони живуть за давніми жорстокими звичаями Першої й Другої воєн та видобувають у горах довкола шпиля метал для зброї й обладунків.

Твердиню утримують бойові майстри, убивці, чаклуни й чорнокнижники клану, а разом із ними заступають на варту караульні легіону Рубаного Щита.]],
            ["dracodar"] = [[Південний захід Палаючого степу вкритий обвугленими пагорбами, якими заволоділи чорні дракони. Землею повзає сила-силенна їхніх посіпак.]],
            ["dreadmaul rock"] = [[Вогнечереві оґри зробили скелю Жахобою, яку ще звуть вершиною Жахобою, своїм осідком. Стежки ведуть на саму верхівку, а всередині скелі розкинувся лабіринт печер з оґрськими житлами.

Вогнечереві — вигнанці Другої війни. Дехто вивчає арканічну магію, хоча з їхніми велетенськими тілами з них кращі бійці, ніж заклиначі. Вони хочуть забрати Палаючий степ самим оґрам. Альянс, орки Чорнокаменю, темнозалізні дворфи й чорні дракони їм цього не дозволять.]],
            ["flame crest"] = [[До голого скелястого виступу, де стоїть Жевріюча Вершина, веде лише грубий місток. Застава не належить ані Орді, ані Альянсу. У невеликій печері в глибині живе Кіблер із балакучим папугою на ім’я Опус. Спраглий до магії Матредіс Вогнезорий торгується за могутні арканічні складники.]],
            ["morgans vigil"] = [[Сторожею Моргана на південному сході Палаючого степу пройшов вогонь. Будинки згоріли дотла, а єдина магічна вежа розвалилася. Рештки поселення утримує Альянс, і його люди живуть у наметах серед уламків. Тут перебуває маршал Максвелл, який шукає звістки про старшого офіцера Штормовію.]],
            ["pillar of ash"] = [[На східному краю цього табору, який тримають орки Чорнокаменю, здіймається висока вежа з обпаленого каменю. Тут стоять убивці, чаклуни й чорнокнижники клану зі своїми варґами.]],
            ["ruins of thaurissan"] = [[Ці попелясті рівнини Палаючого степу колись зеленіли, і тут стояло місто Тауріссан. Його заснував клан Чорного Заліза, вигнаний із Залізогарта, а правив ним чаклун-тан Тауріссан.

Клан програвав Війну Трьох Молотів. Його військо щойно розбилося об твердині двох інших кланів, коли Тауріссан зібрав сімох найдовіреніших дворфів. Відчайдушно намагаючись переломити хід війни, він звернувся до сил, які спали під світом, і зажадав слугу, який приніс би йому перемогу. На поклик озвався Раґнарос, стихійний володар вогню. Вулкан розколов гори й спалив долину на попіл, і місто загинуло. Уцілілі темнозалізні, поневолені володарем вогню, покинули руїни й оселилися під горою, що виросла на їхньому місці.]],
            ["slither rock"] = [[За долиною Крилатих страхіть, у крайньому північно-східному кутку Палаючого степу, ховається маленька печера з одним мешканцем. Тут самотньо живе Кир Покаянний, чорний драконід. Проти спільного ворога він допомагає іншим, хоча ніколи не обходиться без грубощів і глузувань.]],
            ["terror wing path"] = [[Чорні дракони патрулюють долину Крилатих страхіть на сході Палаючого степу. Серед її скель і попелу гніздяться драконята й драконіди чорної зграї.]],
        },
    },
    [1429] = {
        text = [[У Першій війні тисячі орків пройшли крізь Ельвиннський ліс і оточили Штормовій. Єдиний шлях із міста лишився морем. Андуїн Лотар повів лицарів Штормовію в атаку крізь ліс і заскочив орочий ар’єргард зненацька. Орки відступили, але перепочинок був недовгим. Вогонь охопив значну частину лісу, а під час другої облоги Штормовій упав. Лотар посадив уцілілих на човни, що вирушили до Лордерона.

Відтоді ліс відріс. Між бурхливими річками й озерами знову стоять листяні дерева й зеленіють галявини, а часті дощі зберігають родючість землі. Тут працюють лісоруби, хлібороби, рибалки й шахтарі. Без їхніх поставок Штормовій довго не протримався б. Де-не-де ще гниють поламані орочі катапульти.

Каменярі роками відбудовували Штормовій, але так і не отримали платні. Коли голова їхньої гільдії Едвін ван Кліф зажадав виплатити борг, знать наказала розпустити гільдію. Почалися заворушення, з яких постало Братство Непокірних. Його розбійники утримують осередки по всьому лісу.]],
        areas = {
            ["brackwell pumpkin patch"] = [[На південному сході Ельвиннського лісу стоїть хутір, що колись належав родині Бреквеллів. Тепер його тримає Братство Непокірних, і ніхто не знає, куди зникли Бреквелли. На полях і за огорожею їх більше не бачили.

Про родину й досі розповідають одне. Їхня найкраща свиноматка, Принцеса, виросла велетенською, бо крадькома пробиралася на сусідню ферму Кам’янопільських і крала там овочі.]],
            ["crystal lake"] = [[На схід від Злотохрестя мурлоки повзають берегами Кришталевого озера й гуртами бродять його мілководдям. До води небезпечно підходити непідготовленим.]],
            ["eastvale logging camp"] = [[Лісопильні розкидані східним Ельвиннським лісом, а між ними стоять житла. Разом вони утворюють лісозаготівельний табір Східнодолу. Покупці невпинно замовляють деревину, тож лісоруби працюють у суворі строки.

Ліс підступає впритул. Вовки й ведмеді так часто нападають на табори, що відганяють робітників і ставлять поставки під загрозу. Варта Штормовію мусила покликати сторонніх на допомогу, щоб зменшити їхню чисельність.]],
            ["echo ridge mine"] = [[Маршал Макбрайд раз по раз посилає людей до копальні Ехокряжу на північному заході Північнокрайової долини. Він хоче зменшити чисельність кобольдів, які захопили її тунелі. Мешканці околиць уже натерпілися від них.]],
            ["fargodeep mine"] = [[Колись Штормовій видобував золото в Бездонній копальні. Нині її штольні покинуто й ними заволодів клан кобольдів, як шахтарів, так і копачів тунелів. Найглибші виробки називають Нижніми копальнями.]],
            ["forests edge"] = [[Смуга лісу на південний захід від Штормовію простягається півостровом між річкою Назферіті й меншим потоком, що тече до Західного краю. У підліску риються кабани, а вздовж берегів виступають жили міді.

Ліс утримує ватага ґнолів Річкової Лапи під проводом Кнурила. Їхній ватажок нападає на ферми й села по всьому Ельвиннському лісі, і військо Штормовію призначило за нього винагороду. Подейкують, що ватагу пов’язує з Братством Непокірних постачання зброї.]],
            ["goldshire"] = [[Злотохрестя стоїть посеред Ельвиннського лісу. Це одне з малих містечок, які виросли довкола Штормовію. У Першій війні воно й Місяцеграй були останніми двома містечками між орками й столицею. Воєвождь Чорнорук захопив обидва, щоб відрізати короля Ллейна Рінна від його народу перед розграбуванням фортеці Штормовія. Після Другої війни Альянс Лордерона відбудував містечко. Верховний командувач Тураліон наглядав за поверненням розпорошених мешканців королівства.

Нині порядок тут підтримує маршал Дуган із варти Штормовію. Вогнище й ель таверни «Гордість лева», однієї з найповажніших в Азероті, приваблюють подорожніх з усіх доріг, що тут сходяться. Мурлоки з озера Кам’яних Обелісків уже вбили кількох містян, серед них двох вартових. Варта боїться, що бої дістануться до самого містечка.]],
            ["heroes vigil"] = [[На острові посеред озера Кам’яних Обелісків стоячі камені кільцем оточують Камінь пам’яті. Він ушановує загиблих у Першій війні, коли орки пограбували Злотохрестя та його околиці. Нині острів тримають чаклуни-відступники.]],
            ["jasperlode mine"] = [[Кобольди заполонили тунелі Яшмової копальні, яка колись давала Штормовію руду для його воєн. Військо ледве дає раду іншим загрозам і не має вільних людей, щоб їх вигнати.

Та кобольди в копальні не самі. У найглибшій частині оселилася колонія шахтних павуків, для яких кобольди — пожива. Їхня королева Мати Ікло не вітає непроханих гостей.]],
            ["jerods landing"] = [[Братство Непокірних утримує заставу Джерода, човновий причал на ельвиннському березі річки Назферіті. Начальник причалу та його люди використовують його, щоб потай везти крадене з Багрянокряжових гір до вежі Клейвена в Західному краї.]],
            ["maclure vineyards"] = [[Родина Маклурів доглядає довгі ряди винограду на півдні Ельвиннського лісу. Вони запекло ворогують із сусідами Кам’янопільськими, і жодна родина не приховує неприязні до іншої. Однак двоє їхніх дітей покохали одне одного.]],
            ["mirror lake"] = [[Невелике тихе Дзеркальне озеро лежить на заході Ельвиннського лісу. Біля сусіднього саду блищить водоспад. Здається, це місце створене для купання чи риболовлі. Та довколишній ліс облюбували розбійники Непокірних. Там, де варто було б відпочити, тепер краще йти обережно.]],
            ["mirror lake orchard"] = [[На південному березі Дзеркального озера стоять сад і хатина. І те, й інше захопили розбійники Непокірних.]],
            ["northshire abbey"] = [[Століття тому клірики Церкви Святого Світла прийшли на південь із Лордерона й заснували в цьому абатстві Святий орден кліриків Північнокраю. Вони розраджували Штормовій у скрутні часи. Медів, Хранитель Тірісфаля, роками лежав під їхньою опікою в комі.

У Першій війні клірики стали на бік війська Штормовію. Коли оґрський володар Турок викрав Фоліант Божественності, сер Андуїн Лотар очолив похід, щоб його відбити. Фоліант повернувся до абатства. Невдовзі після того, як сюди привели полонену напіворку Ґарону, орки захопили й зруйнували абатство. Біженці рушили до Лордерона зі священними книгами, які витягли з руїн.

Під час Другої війни клан Чо’ґалла Сутінковий Молот зробив руїни своєю штаб-квартирою. Коли Альянс Лордерона повернув Ельвиннський ліс, архієпископ Алонсус Фаол допоміг відбудувати абатство й заснувати Братство Північнокраю, яке нині його утримує. Головна зала, зброярня й бібліотечне крило стоять у Північнокрайовій долині.]],
            ["northshire valley"] = [[Непрохідні гори оточують Північнокрайову долину майже з усіх боків. На півдні з неї веде перевал, захищений товстими кам’яними мурами й брамою під вартою. Долиною тече річка, яка впадає в Кришталеве озеро.

Маршал Дуґлас Макбрайд із варти Штормовію командує залогою абатства й відповідає за оборону долини. Його вартовим досі важко підтримувати спокій. У лісі розплодилися вовки, що втекли зі Смерколісся, копальню Ехокряжу заселили кобольди, а виноградники захопили головорізи Непокірних.]],
            ["northshire vineyards"] = [[Розбійники Непокірних вигнали хліборобів із виноградників Північнокраю, що лежать на схід від абатства за мостом. Тепер ряди лоз тримають агенти Братства. Серед лози вони розбили намет. Ґаррік М’якоступ, різун, який тижнями дошкуляє хліборобам і купцям, зібрав тут довкола себе ватагу головорізів. За його голову призначено винагороду.]],
            ["ridgepoint tower"] = [[Прикордонна вежа, одна з дозорних веж варти Штормовію, стереже межу Ельвиннського лісу. Вартові дивляться до Багрянокряжжя, де збираються ґноли й орки, до Смерколісся, де мертві не лишаються в могилах, і до сусідніх таборів Непокірних. Залога добре захищена від усіх трьох загроз.]],
            ["stone cairn lake"] = [[Озеро Кам’яних Обелісків лежить на північному сході Ельвиннського лісу. Воно дістало назву від Варти героїв, кам’яного насипу на великому острові посеред озера. Там стоїть кільце каменів із пам’ятником, відомим як Камінь пам’яті. Його звели на честь загиблих у Першій війні з орками.

Колись прочани приходили сюди безпечно. Нині острів тримають чаклуни-відступники. На південному березі плем’я мурлоків поставило грубі житла, байдужі до пам’ятника по інший бік води.]],
            ["stonefield farm"] = [[Ферма Кам’янопільських лежить на півдні Ельвиннського лісу. Родина Кам’янопільських обробляє її й запекло ворогує із сусідами Маклурами. Та двоє дітей з обох родин покохали одне одного всупереч давній образі. Дехто сподівається, що любов досягне того, чого не змогли роки сварок, і залагодить те, що зруйнувала ворожнеча.]],
            ["thunder falls"] = [[Гуркітливий водоспад — вузька ущелина в горах на північному заході Ельвиннського лісу. Вона незвичайна тим, що вода спадає з обох її кінців. Іще один водоспад каскадом падає з північних скель і живить ущелину згори.

Від водоспаду біля Дзеркального озера стрімко здіймається вузька стежка до маленької сільської хатини, де є ковадло й горить вогонь. На річці біля будинку — невеликий причал і човен. Кілька розбійників тримаються неподалік. Річка тече далі до іншого водоспаду біля межі Західного краю.]],
            ["tower of azora"] = [[Вежа Азори здіймається серед полів у центральному Ельвиннському лісі. Це мала вежа мага, якою опікуються слуги. Усі вони схожі на гномів і служать архімагові Теокріту. Далеко в Багрянокряжових горах злий чаклун Морґант править вежею Ілґалара. Між двома вежами триває ворожнеча, і кожна за допомогою магії підглядає за іншою.

Аура вежі діє на все, що опиняється надто близько, й перетворює його на щось дивне. Слугам доводиться битися з живими відрами й метеликами-мутантами.]],
            ["westbrook garrison"] = [[Варта Штормовію тримає казарми в гарнізоні Заходоводдя на західному краю Ельвиннського лісу, поблизу межі Західного краю. Корупція й політична нестабільність ослабили королівство. Оскільки більша частина війська Штормовію далеко від дому, гарнізонові ледве вистачає людей, щоб боронити дороги від дедалі численніших ґнолів і злодіїв із Західного краю.

Постом командує заступник Райнер. На оголошеннях про розшук значиться Кнурило, ватажок ґнолів Річкової Лапи. Усі спроби схопити його провалилися. Його ватага заполонила ліси на південь від вартової вежі.]],
        },
    },
    [1430] = {
        text = [[Посеред перевалу Мертвого Вітру стоїть Вежа зі слонової кістки — Каражан. Перевал прорізає гори центрального Азероту й сполучає Смерколісся з болотом Скорбот. Двадцять років тому його вважали частиною Багрянокряжових гір. Тут жив темний чаклун Медів, який відчинив Темний Портал для орків. Під час Першої війни його вистежили й убили. Відтоді вежа стоїть покинута, а її зла магія досі просочується в довколишні землі.

Тут нічого не росте. Дерева скам’яніли й утратили листя, а крізь гострі скелі ущелини, що дала перевалу ім’я, завиває лихий вітер. Усередині блукають оґри, демони, невмерлі й деякі людські мандрівники. З диких тварин тут лишилися тільки птахи-падальники.

Дворяни з Темнодолу прийшли дослідити це лихо. Ніхто з тих, хто увійшов до вежі, не повернувся. Подорожні кажуть, що вежею заволоділа нова сила й що оґри та демони їй коряться. Відомо, що Темні вершники, таємничий гурт, якого бачили в Смерколіссі, приходять із цього перевалу.]],
        areas = {
            ["aridens camp"] = [[Трохи на північ від головної дороги через перевал лежить покинуте стійбище, відоме як табір Арідена. Тепер там нікого нема.]],
            ["deadmans crossing"] = [[На східному роздоріжжі перевалу стоїть дерево-шибениця. На його гілках досі висять два трупи. На вказівнику поруч написано «Повертайте назад!» і «Полиш надію, кожен, хто сюди входить».

Від переправи одна дорога веде на захід до Смерколісся, друга — на схід до болота Скорбот, а третя — на південь до Каражану.]],
            ["deadwind ravine"] = [[Скеляста розколина тягнеться крізь гори на південь, до Каражану. Західна дорога йде її верхнім краєм. У далекому кінці міст веде на південь, і там уже зовсім близько зловісна вежа.]],
            ["groshgok compound"] = [[Поселення Ґрош'ґок — найбільша й найпівденніша з печер, які оґри Мертвого Вітру займають у Погані.]],
            ["karazhan"] = [[Час стер пам’ять про тих, хто звів Вежу зі слонової кістки в Каражані. Вона стоїть на перетині ліній сили в південній частині перевалу Мертвого Вітру й стала осідком Медіва, останнього Охоронця Тірісфаля. Як і личило Охоронцеві, Медів зібрав величезну колекцію рукописів і артефактів, більшу навіть за надбання Кірін-Тору. Під час Першої війни Кадґар, Андуїн Лотар і Ґарона вбили його в самій вежі.

Відтоді вежа стоїть покинута, а над нею й довколишніми землями тяжіє прокляття. Зали повняться привидами. Кажуть, серед них ходять і демони.]],
            ["masters cellar"] = [[Під руїнами невеликого села на південь від Каражану відкриваються підвали, повні привидів. Селяни, певно, служили у вежі. Ніхто не знає, хто їх убив. Одні звинувачують Медіва або щось, що він викликав, інші — Темних вершників.

Униз ведуть два входи. Один відкривається у просторий винний льох, де полиці й бочки давно залишилися самим мерцям. Другий веде до підвалу, чия підлога провалилася в печери глибоко під землею. Обидва підвали повняться невмерлими мешканцями й доглядачами, проклятими душами, неспокійними тінями та примарами, що голосно голосять.]],
            ["morgans plot"] = [[За Каражаном стоїть невелика занедбана церква. Її цвинтар і склеп потопають у мороці перевалу Мертвого Вітру. У каплиці блукають невмерлі мешканці, а ще один обходить пагорб трохи нижче.]],
            ["sleeping gorge"] = [[Невелика прірва розтинає східну частину перевалу Мертвого Вітру. Один зі шляхів, що ведуть на південь до Каражану, деякий час іде ущелиною, а потім повертає на схід у Погань.]],
            ["vice"] = [[На півдні перевалу, вздовж дороги до Каражану, тягнеться пустельна смуга скель під назвою Погань. Оґри Мертвого Вітру живуть тут у курганах і таборах, розкиданих обабіч дороги.

Ніхто не знає, чому вони осіли саме там, де єдине товариство їм складають неспокійні духи й стерв’ятники, що кружляють над ними.]],
        },
    },
    [1431] = {
        text = [[Смерколісся колись було південною частиною Ельвиннського лісу, володінням Штормовію на ім’я Світлолісся. Серед його господарств стояло два чималих містечка. Тепер між деревами висить чорний туман, стовбури покрутилися, а ніч ніяк не минає.

Разом із туманом прийшли ворґени. Мерці виходять із кладовищ, а з перевалу Мертвого Вітру сюди пробралися оґри. Штормовій далеко й давно покинув цей ліс. Та мешканці, які залишилися, тримаються своїх домівок. Їхнє ополчення, Нічна варта, патрулює дороги й боронить Темноділ від воїнів-скелетів, ґулів, ворґенів і Непокірних.

У серці краю лежить кратер давнього вулкана. Він давно згас і тепер сповнений життя. Сутінки в кратері лагідніші за темряву назовні. Далі лежать покинуті хутори й кладовище Воронячого пагорба. Там поховано всіх, кого звірі й невмерлі вбили відтоді, як настала темрява.]],
        areas = {
            ["addles stead"] = [[Братство Непокірних захопило ферму Еддла, один із багатьох хуторів, покинутих на південному заході Смерколісся, коли сюди підкралася темрява. Агенти Братства ходять полем, ховаються в коморі й нишпорять кімнатами маленької фермерської оселі.]],
            ["beggars haunt"] = [[Притулок Бідаків — покинута дозорна вежа варти Штормовію на північному сході Смерколісся. Вона стоїть на схід від маєтку Імлокрива та на північ від дороги до перевалу Мертвого Вітру. Тепер її тримають Відречені. У її стінах смертолов Зредус і аптекар Фаустін ставлять досліди.

Стежка звивається вниз до невеликого ставка, який живить водоспад. Там під двома велетенськими статуями, схожими на статуї Темного Порталу, є безіменна могила. Біля вежі лежить іще одне маленьке кладовище, де поховано Невідомого солдата.]],
            ["brightwood grove"] = [[Нечисленні будівлі на краю Сяючого гаю лежать у руїнах, а темними полями бродять ворґени Нічної Згуби. Вони ставлять примітивні табори серед руїн і нападають на кожного, хто підійде надто близько. Гай лежить одразу на захід від Темнодолу. Його назва береже пам’ять про весь ліс, який до приходу темряви звався Світлоліссям.]],
            ["darkened bank"] = [[Похмурий берег тягнеться вздовж півночі Смерколісся, від його крайнього заходу до мосту, що сполучає ліс із Багрянокряжовими горами. На західному кінці біженці розбили невеликий табір. Там Свен Йорґен живе разом із Ларсом. Дружина й діти Свена загинули від рук Темних вершників із перевалу Мертвого Вітру.]],
            ["darkshire"] = [[Колись Темноділ був затишним лісовим селом, що звалося Великим Селом, посеред Світлолісся. Потім прийшла темрява, і ліс обернувся на небезпечні хащі, повні колючок. Світлолісся стало Смерколіссям, а Велике Село — Темнодолом. Нині ходячі мерці заповнили цвинтарі, а ворґени захопили чимало хуторів навколо містечка.

Після зникнення короля Варіана Рінна Штормовій вивів зі Смерколісся всі війська. Тоді мешканці озброїлися самі. Нічну варту, місцеве ополчення, створили й навчили самі люди лісу. Очолює її командир Алтея Чорнолок. Її вартові боронять головну дорогу й містечко від вовків і ходячих мерців.

Мешканці Темнодолу полохливі й підозріливі, та потребують будь-якої допомоги.]],
            ["dawning wood catacombs"] = [[Під кладовищем Воронячого пагорба простягаються звивисті катакомби, де чаяться наймогутніші невмерлі в околицях. До катакомб ведуть два входи. Східний відкривається до лігва хворих і лютих ґулів. Західний веде до зали зі скелетами, які стережуть гробниці колишніх побратимів.]],
            ["forlorn rowe"] = [[Закинута садиба стоїть на пагорбі біля північного краю кладовища Воронячого пагорба. Там панує темрява, густіша за тінь довколишнього лісу. На вершині, у похмурому будинку над могилами, живе некромант Морбент Скверн. Злою арканічною магією він підкоряє невмерлих Смерколісся.]],
            ["hushed bank"] = [[Безвітряний берег тягнеться вздовж західної річки Смерколісся на південь. Він починається там, де сходяться Західний край, Ельвиннський ліс і Смерколісся, й веде в бік Тернистої долини. Критий міст перекинуто через річку між Смерколіссям і Західним краєм. Між деревами ходять павуки й вовки, а на північному кінці берега стоїть табір Свена Йорґена й Ларса.]],
            ["manor mistmantle"] = [[Маєток Імлокрива стоїть на північному сході Смерколісся, на північ від Темнодолу й на захід від притулку Бідаків. Його землі занепали, і ними бредуть ґулі. Сад здичавів. У ньому досі росте єдина квітка — сльоза Тіллої, остання ознака життя в маєтку.]],
            ["raven hill"] = [[Порожні оселі Воронячого пагорба на заході Смерколісся віддані тлінові й темряві. Майже нікого не лишилося. Наляканий Тремтіній ховається тут від власного похмурого минулого, а гоблін Бліцтік не показується з верхнього поверху однієї з будівель. Рештою містечка блукають Невидимі, переходячи з однієї порожньої кімнати до іншої.]],
            ["raven hill cemetery"] = [[Кладовище вийшло далеко за старі межі тільки після того, як у Смерколісся прийшла темрява. Між надгробками ходять невмерлі й велетенські павуки, а ватаги грабіжників могил нападають на кожного, хто завадить їхній роботі. Невмерлий Мор’Ладім петляє кладовищем дивним маршрутом. Необачних, які зустрінуть його, чекає смерть.

На пагорбі в північно-західному кутку стоїть Закинута садиба, дім некроманта Морбента Скверна. У північно-східній частині лежить спуск до катакомб Ранкового лісу.]],
            ["rolands doom"] = [[Погуба Роланда — копальня на південному сході Смерколісся, просто на схід від Гниючого саду. Її штольні заповнили ворґени зграї Нічної Згуби. Тут живуть Кишкодер і Мерзен, ватажки ворґенів у Гниючому саду.]],
            ["rotting orchard"] = [[Ворґени зграї Нічної Згуби захопили Гниючий сад на півдні Смерколісся й розбивають табори серед напівзруйнованих будівель. Тінеткачі Нічної Згуби вправляються тут у магії, а їхні переслідувачі чатують у тінях.]],
            ["tranquil gardens cemetery"] = [[На цвинтарі при Затишних садах давно немає спокою. Він лежить на південний схід від Темнодолу. Його мертві не спочивають, хоч вони слабші за невмерлих в інших куточках Смерколісся. Вони блукають поміж надгробків і зруйнованої церкви. Божевільний гуль вештається цвинтарем, то в церкві, то надворі. Трохи північніше стоїть дім Сліпої Мері.]],
            ["twilight grove"] = [[Посеред Смерколісся лежить кратер давно згаслого вулкана, повний життя. Тутешні сутінки зовсім інші, ніж темрява решти лісу. У самому серці кратера росте велике безіменне дерево поруч із місячною криницею й давньою альтанкою нічних ельфів. Під гілками — один із чотирьох порталів до Смарагдового Сну. На землі навколо помітний вплив сплячих друїдів.

Портал стережуть четверо великих драконів. Колись вони були гордими заступниками Ізери, Аспекту Снів, і захисниками Сну. Смарагдовий Кошмар спотворив їх. Нині вони прагнуть лише руйнування та смерті.]],
            ["vulgol ogre mound"] = [[Оґри Тріскучого Кулака захопили невелику улоговину на півдні Смерколісся, трохи південніше й західніше від роздоріжжя головної дороги. Згірок дістав назву від їхнього ватажка Ззарка’Вула. Колись тут жили люди, про що свідчать руїни хуторів. У печері оґри пожирають туші чорних ведмедів.]],
            ["yorgen farmstead"] = [[Свен Йорґен колись обробляв цю землю на півдні Смерколісся, доки Темні вершники з перевалу Мертвого Вітру не прийшли й не вбили його родину. Нині садиба занедбана й поля гниють, а Свен живе в маленькому таборі на Похмурому березі.

Садибу тримає Братство Непокірних. Його вбивці непомітно ходять полями.]],
        },
    },
    [1432] = {
        text = [[З усіх боків Лох-Модана здіймаються сірі гори, а їхні схили рідко поросли соснами й березами. Води озера стримує Каменярська дамба — витвір дворфської інженерії, якому немає рівних в Азероті.

Озеро здається тихим, та воно бачило війну. У Другій війні орки Орди захопили ці землі й зайняли позиції проти захисників Альянсу. Дворфи Залізогарта вистояли, а після війни повернули край. На дні озера та його островах досі лежать поламані катапульти й балісти, сліди тих боїв.

Спокій так і не повернувся. Розкопки дворфів відкрили підземні печери. Троґи, яких відкопали, осіли в горах. Вони облаштовують примітивні табори й печери, звідки нападають на подорожніх. Ворожі кобольди, дикі звірі та оґри на північному сході додають небезпеки.]],
        areas = {
            ["algaz station"] = [[На цій заставі, одразу на схід від проходу Північних воріт, стоїть чимало дворфів-горян. Вона лежить на південь від Дун-Альґаза, твердині в проході, від якої й дістала назву.]],
            ["dun algaz"] = [[Тунель через Дун-Альґаз існував ще до Війни Трьох Молотів. Коли війна вигнала дворфів Дикого Молота із Залізогарта, вони пройшли цим шляхом.

Орда теж відступала сюди. У Другій війні орків відкинули від Дун-Модра, і вони відступили на південь через долину Тандола й окопалися на місцевій заставі. Андуїн Лотар хотів витіснити їх із Каз-Модана й послав військо знести твердиню. Штурм провалився. Орки втрималися, і Дун-Альґаз став останнім клаптем землі в краї, що лишився за Ордою.

Дворфи-горяни, які стерегли цей прохід, здебільшого трималися пагорбів над ним. Клан Драконової Пащі захопив їхню заставу й відтіснив їх до верхнього тунелю. Відколи нижній прохід втрачено, дорога між землями дворфів і гаванню Менетілів стала значно небезпечнішою.]],
            ["farstrider lodge"] = [[Оселя Далекоходців стоїть серед південно-східних пагорбів Лох-Модана. Уже з кам’яної кладки видно, що цей мисливський дім збудували вищі ельфи. Нині відомо лише про одного вищого ельфа, що тут живе. В ельфійських стінах відтоді оселилися люди й дворфи, серед них і мисливці.]],
            ["grizzlepaw ridge"] = [[Сиволапе пасмо здіймається на південь від Телсамара. На його висотах повно ведмедів, які там почуваються господарями. Найлютіший із них, великий чорний ведмідь Старий Сажень, має лігво на схилі. Час від часу він спускається на дно долини й кидається на всякого, хто мав нещастя його роздратувати.]],
            ["ironbands excavation site"] = [[На південному сході Лох-Модана розвідувач Залізоплет керує розкопками давніх руїн. Сюди, як і на інші дворфські розкопки, вдерлися нападники й вигнали розвідувачів та шахтарів. То особливо великі й люті троґґи.]],
            ["loch"] = [[У Каз-Модані жодне озеро не зрівняється з озером Лох. У всьому відомому світі за нього більші лише Лордамерське озеро й озеро Дарроумер.

На його північному краю воду стримує Каменярська дамба. Відколи її звели, озеро стало більш ніж удвічі більшим. У ньому плавають молотозаври й хижі риби, а на дні й островах досі лежать розбиті катапульти та балісти Другої війни.]],
            ["mogrosh stronghold"] = [[Печери північно-східних пагорбів тримає плем’я оґрів Мо'ґрош. Чок'сул, якого вважають їхнім ватажком, організував напади на Телсамар, Каменярську дамбу й розкопки дворфів. Магістрат Телсамара призначив винагороду за його голову. Один загін улаштував засідку на дворфський караван із Заболоття. Після нападу живим лишився тільки один смертельно поранений вартовий.]],
            ["north gate pass"] = [[Прохід пролягає між високими горами Дун-Морога на заході й нижчими горами Лох-Модана на сході. Посеред нього стоїть застава Північних воріт, найпівнічно-східніше поселення, яке дворфи звели в Дун-Морозі.

Місцеві горяни раз у раз відганяють диких звірів від мурів. Дехто з дворфів зник у горах, коли шукав найнебезпечніших хижаків.]],
            ["silver stream mine"] = [[Колись із копальні Срібних потоків видобували вдосталь срібла й доправляли його дворфам Залізогарта. Жила давно вичерпалася, й Ліга шахтарів перетворила тунелі на склад.

Тепер їх захопили кобольди Тунельних Щурів, ласі до того, що ще ховає копальня. Позаду неї лежать розбиті вози й катапульти орків.]],
            ["south gate pass"] = [[На півдорозі через прохід стоїть дворфська застава. Її горяни відігнали більшість звірів, які колись нишпорили довкола. Земля тут укрита снігом, як і в горах на заході.

Цим проходом найшвидше спуститися до дворфського містечка Телсамар.]],
            ["stonesplinter valley"] = [[Долина Каменедробів колись була незайманим куточком серед гір південно-західного Лох-Модана. Тепер там кишать ворожі троґґи Каменедроби.

Дворфи вважають, що напад племені на їхні землі очолює троґґ на ім’я Ґромаґ, який живе в найдальшій печері. Двоє добірних охоронців, Скрегатель і Булдига, ніколи не відходять від нього. Капітан Руґельфуз жадає його смерті.]],
            ["stonewrought dam"] = [[Мало хто з тих, хто переходить Каменярську дамбу, знає, що її звів темнозалізний дворф. Франклорн Файноков, великий архітектор цього клану, керував будівництвом і винайшов спосіб кладки, від якого дамба дістала назву.

Дамба здіймається на схід від Дун-Альґаза вздовж північного краю Лох-Модана. Стримана нею вода більш ніж удвічі збільшила озеро. Нещодавно клан Чорного Заліза напав на дамбу, і дворфи Залізогарта посилили охорону. Тепер за нею наглядає старший інженер Греблер VII.]],
            ["stoutlager inn"] = [[Таверна «Міцне пійло» стоїть у Телсамарі. Дворфи й подорожні сходяться сюди випити й погомоніти. Таверну тримає корчмар Вогнежар, а стайнею опікується Ліна Вогнежар.]],
            ["thelsamar"] = [[Дворфське містечко стоїть на західному березі Лох-Модана, на північ від Сиволапого пасма й на північний схід від долини Каменедробів. Його оселі стережуть горяни, а містечком керує магістрат Тупоніс. Тут є таверна «Міцне пійло», а біля крайньої південно-західної оселі — кузня й ковадло. Ліга дослідників теж має тут будинок, а під містечком на березі озера ловлять рибу.

На захід від містечка йде дорога з півночі на південь. Нею можна дістатися проходів до Дун-Морога й Заболоття.]],
            ["valley of kings"] = [[Долина Королів лежить на південному заході Лох-Модана, де зелений край звужується перед брамою, що веде вниз до почорнілої Випаленої ущелини. Брама замкнена й під охороною. Її стереже горянка Щебінка.

Над проходом здіймаються дві великі статуї, короля Мадорана Бронзобородого й короля Хардроса Дикого Молота. Після смерті обох королів їхні сини разом замовили ці статуї на честь батьків. Землю на півдні після появи Раґнароса вкрили попіл і лава, а статуї стережуть дорогу до неї. Вони застерігають кожного, хто зазіхнув би на королівства дворфів, і нагадують, яку ціну темнозалізні заплатили за свої злочини.]],
        },
    },
    [1433] = {
        text = [[У Багрянокряжових горах над стрімкими річками ростуть в’язи, а земля невпинно підіймається до вершин. Гірський хребет лежить на схід від Ельвиннського лісу й на південь від Палаючого степу. Ці пагорби під захистом Штормовію, хоча від Другої війни формально незалежні. Люди живуть спокійно й задоволені своїм життям. Вони постачають Штормовію деревину з лісу, рибу з озера та врожай із полів. Це один з останніх мирних країв Азероту.

Однак спокій непевний. Загін орків Чорної Скелі спустився з Палаючого степу й захопив фортецю Кам’яної Варти. Ґноли та інші орки Чорної Скелі тиснуть із довколишніх пагорбів на Приозер’я. Шлях від роздоріжжя в Трикутті до фортеці тримають драконята, ґноли, мурлоки й дикі звірі.

Поверхня Безхвильного озера здається спокійною. Під нею живуть мурлоки, а люди й досі розповідають про морське чудовисько на глибині.]],
        areas = {
            ["althers mill"] = [[Лісопильня на північний схід від Приозер'я покинута. Це завжди був глухий закуток, яким люди проходили дорогою до фортеці Кам'яної Варти. Тепер її заполонили павуки, канюки й поодинокі заблукалі орки.]],
            ["galardell valley"] = [[Вежа Ілґалара стоїть у долині Ґаларделл на північному сході Багрянокряжових гір. Там живе Морґант, темний маг, якого вигнали зі Штормовію.

У долині під вежею кишать ґноли Тінешкурих, що йому служать. Найсильніший серед них — їхній ватажок, лейтенант Тельбухожбур. Щойно помічає чужинця, він кличе всіх ґнолів поблизу. Війт Соломон призначив винагороду за його голову.]],
            ["lake everstill"] = [[Широке, прозоре й блакитне Безхвильне озеро лежить посеред Багрянокряжових гір. На його березі дрімає Приозер'я. Річка, що витікає на сході, проходить повз темні мури фортеці Кам'яної Варти.

Колись озеро славилося риболовлею. Відтоді його захопили племена мурлоків, а в глибині нишпорить велика тварина, відома як Озерний молотник. Міст Безхвильного озера веде дорогою через воду. Його пошкодив клан Чорнокаменю, і десятник Ослоу зі своїми робітниками досі його лагодить.]],
            ["lakeridge highway"] = [[До Першої війни Приозерним трактом уздовж південного берега Безхвильного озера невпинно їздили. Відколи орки захопили фортецю Кам'яної Варти, старою дорогою майже не користуються. Більшу її частину патрулюють ґноли, і мало хто з подорожніх ризикує нею йти.]],
            ["lakeshire"] = [[Приозер'я стоїть на північному березі Безхвильного озера. За цю землю містечко не раз проливало кров. Під час Першої війни воєвождь Чорнорук привів у ці гори загін, щоб узяти його для Орди. Андуїн Лотар і лицарі Штормовію влаштували оркам засідку на схилах і мало їх не здолали. Двоє чорнокнижників Тіньової Ради переломили хід бою й змусили Лотара відступити. За кілька тижнів Чорнорук повернувся з більшим військом та захопив містечко. Після Другої війни Альянс Лордерона відбив і відбудував його, а верховний командувач Тураліон наглядав за поверненням мешканців.

Тепер Приозер'ям керує війт Соломон через місцевий суд, а вартою командує маршал Марріс. Ґноли й орки Чорнокаменю тиснуть на містечко, а зі Штормовію надходить мало допомоги. Під час одного з нападів орки пошкодили міст Безхвильного озера. Десятник Ослоу та його люди досі його лагодять, і робота гальмує, бо під час нападів вони втрачають припаси.]],
            ["redridge canyons"] = [[Каньйони тягнуться північним заходом Багрянокряжових гір. Тут тримає лігво Скавчало, ватажок місцевих ґнолів.]],
            ["renders camp"] = [[Орки Чорнокаменю утримують заставу на північному заході Багрянокряжових гір, поблизу входу до Палаючого степу.]],
            ["renders rock"] = [[Могутні орки Чорнокаменю займають велику печеру на північному заході Багрянокряжових гір, неподалік шляху до Палаючого степу.]],
            ["renders valley"] = [[Орки цієї долини на південному сході Багрянокряжових гір слабші за родичів далі на північному заході. Та табір усе одно належить їм. Це застава клану Чорнокаменю.]],
            ["rethban caverns"] = [[Ґноли захопили глибокі тунелі Ретбанських печер на північному заході Багрянокряжових гір. Їх очолює підступний Ардо Бруднолапий. Ґноли носять із собою ретбанську руду, названу на честь Барта Ретбана, який першим її знайшов. Печери, ймовірно, теж назвали на його честь.]],
            ["stonewatch"] = [[Люди Приозер'я тримали Кам'яну Варту, щоб боронитися від нападів орків із Палаючого степу. У ній є твердиня, яку легко захищати, укріплена вежа поруч і водоспади, що спадають скелею внизу.

Чорнокнижник Морґант уклав угоду з Ґат'Ільзоґґом, воєводою Чорнокаменю. Спираючись на темні чари Морґанта, орки з жахливою люттю напали на твердиню, розгромили 12-й шабельний полк і захопили фортецю.

Союз тривав недовго. Морґант обернувся проти орків і звів власну вежу, де зібрав військо ґнолів Тінешкурих. Відтоді орки Чорнокаменю боронять Кам'яну Варту самотужки й досі її тримають.]],
            ["stonewatch falls"] = [[Тут закінчується східна річка Безхвильного озера. Вона спадає зі схилу під Кам'яною Вартою в глибоке озеро в закутку східних гір. Уздовж його берегів живе невелике плем’я мурлоків. Вони ловлять у воді рибу й споруджують грубі прихистки, у яких сплять.]],
            ["stonewatch keep"] = [[Ґат'Ільзоґґ, воєвода клану Чорнокаменю, тримає фортецю Кам'яної Варти зі своїм довіреним помічником Таріл'зуном. Орки відібрали твердиню в людей Приозер'я, і звідти Ґат'Ільзоґґ веде напади на містечко.

Під час боїв орки захопили капрала Кішана з війська Штормовію й потягли його до своїх таборів далі на північ. Війт Соломон призначив винагороду за Ґат'Ільзоґґа, а маршал Марріс із Приозер'я хоче, щоб Таріл'зун відповів за свої злочини.]],
            ["stonewatch tower"] = [[Поруч із твердинею стоїть укріплена дозорна вежа Кам'яної Варти. Як і фортеця, вона колись належала людям Приозер'я. Тепер її тримають підлеглі Ґат'Ільзоґґа, орки Чорнокаменю, які звідси наглядають за місцевістю довкола захопленої кланом твердині.]],
            ["three corners"] = [[На Трикутті дорога розходиться в три боки, до трьох поселень. Один шлях веде до Злотохрестя в Ельвиннському лісі, другий — до Приозер'я, а третій — до Темнодолу в Смерколіссі. Лише роздоріжжя позначає межу між трьома землями. Його стереже один вартовий зі Штормовію, Паркер, а дорогами поблизу блукають ґноли.]],
            ["tower of ilgalar"] = [[Колись Морґант навчався у вежі магів Штормовію разом іще з двома магами, доки не піддався темному мистецтву. Його просили зректися цих чарів, та він не зміг і був вигнаний із кварталу Магів.

Тепер він живе у вежі Ілґалара на північному сході Багрянокряжових гір і далі веде свої темні дослідження. У вежі розвішано драконячі кістки, а на алхімічному столі нагорі стоять драконячий і людський черепи. Він командує ґнолами Тінешкурих, від рук яких гинули й орки, й люди.]],
        },
    },
    [1434] = {
        text = [[Упродовж віків тут панували тропічні тролі Ґурубаші. По всьому краю стояли їхні кам’яні міста. Імперія стала жорстокою. Тролів інших племен приносили в жертву богові крові Гаккару Здирачеві Душ, доки тривала міжусобна війна не розколола племена назавжди. Темний Спис пішов своїм шляхом, а ті, хто лишився в долині, відтоді воюють між собою.

Міста впали й заросли джунглями. Кровоскальпі утримують північний захід, а Черепотрощителі — схід. Обидва племені живуть серед руїн. Колишня столиця, Зул’Ґуруб, лежить у долині на північному сході. Уздовж узбережжя полюють наґи, а терен, від якого долина дістала назву, переплітає всі стежки вглиб краю.

Чужинці й далі прибувають. На південному березі гобліни керують гаванню, якою користуються пірати. На півночі експедиція полковника Конрада Курцена збудувала серед дерев укріплений табір, де його люди воюють між собою. Тролі за всім спостерігають і дедалі дужче прагнуть очистити землю від чужинців.]],
        areas = {
            ["baliamah ruins"] = [[На східному березі річки стоїть давня трольська кам’яна кладка. Серед неї оселилися тролі Черепотрощителі. Оґрський пагорб Мош'Оґґ лежить на північний схід звідси.]],
            ["ballal ruins"] = [[Від Бал'лала лишився ряд поламаних колон на північно-західному березі, навпроти Підступного рифу. Тролі, які їх звели, давно зникли. Нині серед поваленого каміння живуть Кровоскальпі.]],
            ["battle ring"] = [[Бійцівське коло лежить посеред арени Ґурубаші, пам’ятки стародавньої імперії, яка колись панувала на значній частині півдня Східних Королівств. У давнину тут билися до смерті, й пісок перетворювався на багно від трольської крові. Імперія давно впала, та арена вціліла. Тепер Коротун Джон Мітрил наглядає за менш смертоносними поєдинками.

За давнім переказом, душу кожного, хто опівночі знайде тут криваво-червоний амулет, до світанку пожере демон.]],
            ["bloodsail compound"] = [[Буканьєри Кривавого Вітрила, ватага моряків-відступників, мають розкиданий табір приблизно посеред західного узбережжя Тернистої долини. Серед піратів збираються відчайдухи й чорнокнижники.]],
            ["booty bay"] = [[Піші подорожні входять до Бухти Наживи крізь вибілені щелепи велетенської акули. За ними портове місто підіймається скелями довкола блакитної лагуни на південному краю Тернистої долини. Життя тут дешеве, а довіряти не варто нікому. Це рай для пройдисвітів, повний інформаторів.

Колись тут була Чорноводна бухта, невеликий людський порт, який захопили тролі джунглів. Гобліни Картелю Паровиманів вигнали тролів із берега й зробили бухту своїм осередком у Східних Королівствах. Це сталося ще до Першої війни.

Тепер портом керують Рейдери Чорноводдя, тісно співпрацюючи з Картелем. Тут приймають кожного подорожнього, під яким би стягом він не ходив. Барон Ревілґаз і командувач флоту Рейдерів Морський Ріг правлять із верхівки корчми. Барон наймає кожного бійця, якого може, проти Буканьєрів Кривавого Вітрила, що загрожують бухті.]],
            ["cape of stranglethorn"] = [[На півдні Тернистої долини повно трольських руїн, наполовину поглинутих джунглями. Там, де дерева відступають перед морем, тягнуться довгі піщані береги. Тут уже давно ворогують гоблінські пірати Бухти Наживи та їхні суперники, Буканьєри Кривавого Вітрила.]],
            ["crystal shore"] = [[Південні моря розбиваються тут об довгий піщаний берег навпроти східних пляжів острова Ягуеро. Стрімкий кряж відгороджує пляж від решти землі. Через нього проходять лише дві стежки, одна з них підіймається до Туманного долу. На північному кінці берега стоять руїни Абораз.]],
            ["crystalvein mine"] = [[У породі Кришталевої копальні неподалік Зул'Мамве є дивні кристали, які Вибрик Бульчук назвав Співучими кристалами. Їх знаходять лише в Тернистій долині, і коштують вони чимало. Тутешні василіски їх їдять, від чого їхня шкура твердішає. Компанія «Авантюра» прийшла по кристали, та василіски досі їй заважають. Біля входу стоять укриті кристалами тролі й люди, застиглі там, де їх спіткало лихо.]],
            ["gromgol base camp"] = [[Командир Аґґро'ґош утримує військовий табір Ґром'ґол, орочу фортецю на західному березі. Її міцно укріпили проти тролів джунглів, наґів із прибою й вояків Альянсу, які підходять уздовж берега. Табір підтримує безпечний шлях постачання до Камінарда на болоті Скорбот.]],
            ["gurubashi arena"] = [[У давнину на арені Ґурубаші билися до смерті, й пісок перетворювався на багно від трольської крові. Імперія Ґурубаші звела арену, коли правила величезними землями на півдні Східних Королівств. Вона стоїть на північному заході мису Тернистої долини, одразу на північ від Бухти Наживи, і пережила імперію.

Тепер Коротун Джон Мітрил наглядає за менш смертоносними поєдинками, в яких переможці здобувають славу й скарби. За давнім переказом, душу кожного, хто опівночі знайде криваво-червоний амулет, до світанку пожере демон.]],
            ["jaguero isle"] = [[Біля берега Тернистої долини лежить острів Ягуеро, укритий джунглями, де живуть пантери й горили. Править там король Мукла, велетенська мавпа. Він тримає в полоні тауренку, принцесу Пубу.]],
            ["janeiros point"] = [[На цьому маленькому острові біля Бухти Наживи стоїть велетенська статуя гобліна з розпростертими руками. Ніхто не знає, з кого її виліпили. Її звели як маяк, щоб вітати судна в порту. На острові оселився морський велетень Мок'раш.

Він горлає через воду до капітана Смоттса. Вихваляється, що обв’язав капітанів пояс довкола пальця, питає, чи не скінчилися в капітана кораблі, які можна сюди послати, і бурчить, що статуя — поганий співрозмовник.]],
            ["kalai ruins"] = [[Руїни Кал'ай у Тернистій долині наполовину поглинуло море. Їхню давню трольську кладку сточили припливи й час. Поміж повалених колон тепер гніздяться мурлоки Хмурожаброго племені, які заволоділи затопленими залами.]],
            ["kurzens compound"] = [[Експедиція полковника Конрада Курцена звела це незвичайне людське поселення з лісопильнею на схід від табору повстанців. Курцен збожеволів. Воїни, які не захотіли коритися йому, відкололися й заснували табір повстанців. Тепер між ними точиться смертельний бій, і люди, які колись служили під одним командуванням, убивають одне одного між деревами.

Біля стаєнь у клітках сидять пантери й тернисті тигри. Вояки дресирують їх для бою.]],
            ["lake nazferiti"] = [[На березі озера Назферіті стоїть велика база гоблінської компанії «Авантюра». У воді повно хижих риб і кроколісків.

Річка Назферіті тече крізь озеро й, можливо, є найдовшою річкою півдня Східних Королівств. Вона бере початок біля водоспаду в Багрянокряжових горах, хоча дехто вважає, що її витоки далі, на перевалі Мертвого Вітру.]],
            ["mistvale valley"] = [[Туманний діл лежить на півдні Тернистої долини. Серед його дерев живуть великі туманнодільні горили.]],
            ["mizjah ruins"] = [[Руїни Мізжа лежать на південний схід від військового табору Ґром'ґол. Їх тримають моцаки Мош'Оґґа та їхні знахарі. Серед цих поламаних каменів оґри влаштовують засідки на каравани з припасами до Камінарда.]],
            ["moshogg ogre mound"] = [[Оґрівський згірок Мош'Оґґ лежить на південь від Зул'Ґуруба. Його темні закутки стали домівкою оґрів племені Мош'Оґґ. Із самих глибин згірком править їхній ватажок, оґр-маг Май'Зот.]],
            ["nekmani wellspring"] = [[На західному краю Тернистої долини, високо в скелях над південним Диким узбережжям, б’є священне джерело. Це єдина чиста прісна вода на південь від Смерколісся.

Вчені сперечаються про нього. Кожен народ твердить, що воду освятили саме для нього, і ніхто не зміг розв’язати суперечку. Нещодавно до джерела дісталася експедиція наґів-дослідників. Вони люто його стережуть.]],
            ["nesingwarys expedition"] = [[Дворф Гемет Ернінґвей, майстерний мисливець, вирушив з експедицією до Тернистої долини, щоб полювати на дичину в джунглях. Його табір стоїть одразу під річкою, на північ від озера Назферіті.

Табір стережуть наймані стрільці. Слуга Ернінґвея Барніл Камнекухоль називає його героєм Альянсу.]],
            ["rebel camp"] = [[Цей табір звели вояки Штормовію, які порвали зі своїм полковником. Він стоїть на крайньому півночі Тернистої долини, на захід від дороги, що веде на південь зі Смерколісся.

Полковник Конрад Курцен вивів експедицію зі Штормовію, та її охопило безумство. Більшість вояків досі йде за ним. Лейтенант Дорен із малим загоном вирвався з поселення Курцена, утік на захід і розбив тут табір. Вони досі вірні Штормовію. Дорен жадає голови Курцена, щоб покласти край цьому безумству.]],
            ["ruins of aboraz"] = [[Занзіл-Вигнанець тримає ці давні трольські руїни на південно-східному узбережжі Тернистої долини. Черепотрощителі вигнали його за те, що він отруював власний народ.

Тут він варить зілля, від якого той, хто його вип’є, стає сильним і недоумкуватим. Зілля підкорило його волі гулів, наґів і тролів, які блукають руїнами.]],
            ["ruins of jubuwal"] = [[Старі трольські руїни стоять одразу на схід від арени Ґурубаші біля головної дороги, що тягнеться через усю Тернисту долину. Їх захопили гулі, наґи й тролі на службі в Занзіла-Вигнанця.

Поміж них є двоє людей, Джон-Джон Ворон і Морі «Дерев'яна нога» Вілкінс. Вони винні гроші безжальному «Морському вовку» Мак-Кінлі.]],
            ["ruins of zulkunda"] = [[Плем’я Кровоскальпих тримає великі руїни тролів джунглів Зул'Кунди на північному заході Тернистої долини. Тут командують Неззліок Зловісний і Ґан'зула.

Кровоскальпі відокремилися від імперії Ґурубаші під час її громадянської війни. Вони відбивають усіх чужинців, навіть Черепотрощителів, щоб зберегти відвойовану землю. До племені Темного Списа, перших тролів джунглів, які приєдналися до Орди, вони мають лише зневагу.]],
            ["ruins of zulmamwe"] = [[Гори замикають руїни Зул'Мамве з усіх боків, крім півночі. Тут живуть Черепотрощителі, друге велике трольське плем’я Тернистої долини, під орудою лютого вождя Ана'тека Жорстокого.

Як і Кровоскальпі, Черепотрощителі відокремилися від імперії Ґурубаші під час її громадянської війни. Вони зневажають плем’я Темного Списа й відбивають усіх чужинців, найбільше — сусідніх Кровоскальпих. Їхній знахар Мог Невмирущий підкорив кількох вояків експедиції полковника Конрада Курцена й тримає їх біля себе.]],
            ["savage coast"] = [[На мілинах Дикого узбережжя повно кроколісків, а на березі живуть василіски. Поряд стоїть кілька трольських поселень.

Узбережжя займає північний берег Тернистої долини від межі Західного краю на південь до військового табору Ґром'ґол. Воно лежить на схід від Підступного рифу.]],
            ["south seas"] = [[Між материками Південні моря омивають південні береги Східних Королівств і Калімдору. Вони належать до Великого моря, а серед їхніх островів лежить Зандалар. Ближче до Тернистої долини море стає небезпечним через рифи й невеликі острови, деякі з яких лише піщані коси.

Під час Другої війни клан Буревикрадачів ловив у цих водах велетенських черепах і використовував їх як підводні судна Орди.]],
            ["southern savage coast"] = [[Пляжі й мілини тягнуться західним краєм мису Тернистої долини, де Південні моря зустрічаються з берегом. Узбережжя пролягає на південь повз Бухту Наживи й мис Жанейро до Бурхливого берега.

Підступний риф відділяє його від Дикого узбережжя на півночі. Там Велике море переходить у Південні моря.]],
            ["spirit den"] = [[Троль-знахар Унбаґва тримається потаємної печери на північному кінці Туманного долу. У долині довкола печери духів живуть великі туманнодільні горили.]],
            ["stockpile"] = [[Печера в глибині поселення Курцена слугує зброярнею бійцям полковника Конрада Курцена, які тримають тут зброю та спорядження. Хоч би що трапилося з розумом полковника, більшість його людей досі йде за ним.]],
            ["tkashi ruins"] = [[Поламані трольські мури стоять у джунглях на південний захід від експедиції Ернінґвея. Поміж ними живе великий загін Кровоскальпих, зокрема воїни, сокирожбури й шамани. Мисливець Гемет Ернінґвей писав, що він і його люди пройшли руїнами без пригод.]],
            ["venture co base camp"] = [[Гобліни компанії «Авантюра» розчистили місце для табору біля озера Назферіті. Лісоруби й подрібнювачі заготовляють деревину в джунглях, а геологи копають пагорби в пошуках кристалів. Їх можна знайти лише в Тернистій долині, і деякі покупці дуже їх цінують.]],
            ["venture co operations center"] = [[На озері в північних джунглях стоїть нафтова платформа, зведена гоблінами компанії «Авантюра». На вишці тісняться механіки й геологи, а робочі загони просуваються звідси глибше в джунглі. Ці віддалені підприємства тримаються непевно. Тролі джунглів сповнені рішучості очистити свої давні землі від усіх чужинців.]],
            ["vile reef"] = [[Біля західного узбережжя Тернистої долини, неподалік військового табору Ґром'ґол, море іскриться над коралами. Під ним лежать затоплені трольські руїни. Поміж камінням оселилися мурлоки. Вони ходять залами, що колись належали іншим. Олтар Припливів досі там стоїть. Дно рифу всіяне велетенськими мушлями, в яких, подейкують, є блакитні перлини. На берег викидає корабельні уламки.]],
            ["wild shore"] = [[На крайньому південному березі Східних Королівств суходіл відступає перед Південними морями. Буканьєри Кривавого Вітрила поставили флот на якір біля пляжу, а піском блукає морський велетень.

На заході земля закінчується скелястим мисом, із північного боку якого лежить Бухта Наживи.]],
            ["yojamba isle"] = [[Біля північно-західного узбережжя Тернистої долини, поблизу межі Західного краю, лежать невеликі острови. На них розбило табір плем’я Зандалар. Давній бог крові Гаккар Здирач Душ захопив Зул'Ґуруб і зробив його місцем крові й безумства. Зандалар не може здолати його самотужки, а трольські племена роз’єднані. Тож вони посилають звістку Альянсові й Орді та просять героїв усіх народів відкласти свою війну й допомогти їм.]],
            ["ziatajai ruins"] = [[Тут у джунглях лежать трольські руїни. Черепотрощителі тримають їх проти кожного чужинця, який підходить.]],
            ["zulgurub"] = [[Зул'Ґуруб здіймається з джунглів на північному сході Тернистої долини. Це місто-храм із зикуратами, повитими ліанами, й зарослими ідолами. Воно було столицею імперії Ґурубаші, якій підкорялися всі племена тролів джунглів. Тепер його тримає лише плем’я Ґурубаші.

Задовго до відкриття Темного Порталу громадянська війна роздерла імперію. Коло жерців на ім’я Атал'ай викликало аватара Гаккара Здирача Душ, давнього бога крові. Жерців вигнали, та вони довідалися, що Гаккар може набути тілесної подоби лише в старій столиці.

Тепер Гаккар живе в самій її глибині. Джін'до-Відьмак поневолив кількох верховних жерців Ґурубаші й змусив служити йому. Поборники Первісних богів зайшли в місто, щоб утихомирити бога крові, та підпали під його владу. Їхня сила живить Гаккара.]],
            ["zuuldaia ruins"] = [[Серед стародавніх руїн на північному відтинку західного узбережжя Тернистої долини живе багато тролів Кровоскальпих. Вони проганяють усіх чужинців.]],
        },
    },
    [1435] = {
        text = [[Колись болото Скорбот було північною половиною велетенських боліт, відомих як Чорні драгви. На півдні відчинився Темний Портал. Через нього пройшли орки й звели у трясовині два поселення та опорний пункт. Коли Портал зруйнувався під час Другої війни, південна половина стала Спустошеними землями, а північна — болотом Скорбот.

Це застійний край трясовин, що затягують під воду, й плакучих дерев. Морська вода просочується в болото. Вода в плесах солонувата, і там повно кроколісків. Повалені колоди й каміння вкриті сіллю. У глибині бродять болотяні звірі, на берегах полюють ягуари, а єдина дорога виступає над водою лише на кілька сантиметрів.

Дехто з дренеїв пройшов через Темний Портал у пошуках нового життя й оселився тут. Туга за домом звела більшість із них з розуму, і тепер вони нападають на кожного. Далеко від Штормовію Орда заснувала власне поселення. За наказом Ізери Сновидиці зелені дракони патрулюють болото й стережуть зруйнований трольський храм під найбільшою трясовиною.]],
        areas = {
            ["fallow sanctuary"] = [[У цьому селі живе плем’я, відоме просто як Загублені. Ці дренеї пройшли крізь Темний Портал. Туга за домом звела їх з розуму, і вони здичавіли. Загублені нападають на кожного, кого бачать, і посилають проти орків убивць та диверсантів.]],
            ["harborage"] = [[На півночі болота Маґтур очолює невеликий гурт дренеїв. На відміну від більшості своїх одноплемінників, вони зберегли розум, пам’ятають своє шляхетне походження й живуть осторонь збожеволілих родичів. Маґтурові випала похмура доля вбивати тих, кого він колись вважав братами.

Село має справи й з Ордою, і з Альянсом. Із Загубленими Тьмяного пристановища воно відкрито воює, а Нобору-Дубина зі своєю ватагою блукає болотом і вбиває кожного, хто трапляється їм на шляху.]],
            ["ithariuss cave"] = [[У цій печері на крайньому південному заході болота живе загадковий вищий ельф на ім’я Ітарій. Надворі борюкаються й незграбно шкандибають непосидючі зелені драконята. Ітарій зголосився доглядати їх, поки вони ростуть.]],
            ["misty reed post"] = [[Ток'Кар тримає цей невеликий табір для Камінарда. Із ним Катар, кілька мисливців і шаман із містечка. Застава лежить між Трясовинням та узбережжям Туманного Очерету. Тут нема ні землянки, ні вежі, а Ток'Кар мріє про землянку або хоча б вежу.]],
            ["misty reed strand"] = [[Похмурий берег усіяний викинутими водою колодами й уламками. Більше на цьому широкому пляжі майже нічого нема. Берег ділять кроколіски, краби й мурлоки.]],
            ["misty valley"] = [[Низький туман стелиться Туманним поділлям на північному заході болота, на північ від дороги до перевалу Мертвого Вітру. Тут повно болотних блукачів і кривулястих страховищ. У печері в самій глибині долини тримається елементаль, Повелитель болота.]],
            ["pool of tears"] = [[Широкий і тихий став Сліз лежить на східній межі болота Скорбот. Під його спокійною поверхнею лежить затоплений трольський храм Атал'Гаккара, а зелені дракони стережуть і землю довкола, і руїни під водою.

У воді плавають кровожерні риби. Уламки кам’яних споруд Атал'ай лежать на березі й під водою.]],
            ["shifting mire"] = [[Дрібний намул Мінливого болота ніколи не лежить спокійно. Таємнича сила згрібає його в кучугури й тягне землею. Намул завивається й збирається в калюжі, наче живий. Ця трясовина займає більшу частину середини болота Скорбот, на захід від ставу Сліз. Тут полюють кроколіски й болотні ягуари, а поміж ними блукають Загублені.]],
            ["sorrowmurk"] = [[У цій трясовині одразу на схід від ставу Сліз і храму Атал'Гаккара повзають зелені драконіди. Край патрулює великий зелений дракон. Сюди заходять лише найвідважніші подорожні.]],
            ["splinterspear junction"] = [[Дорога в болото тут розходиться надвоє. Одна гілка веде на північ, а друга — на південь до Камінарда. На роздоріжжі стоїть стара ороча дозорна вежа, а перехрестя патрулює варта Орди.]],
            ["stagalbog"] = [[На південь від ставу Сліз лежить густа трясовина, де болото впирається в гори, що замикають його з півдня. Під горою в скелі відкривається вхід до печери.]],
            ["stagalbog cave"] = [[У цій великій печері на сході трясовини живе чимало мурлоків Болотного племені під проводом Болотного Базікала.]],
            ["stonard"] = [[Орки Старої Орди звели Камінард у Чорних драгвах невдовзі після першого відкриття Темного Порталу. Це одне з найстаріших орочих поселень в Азероті. Перша війна сильно його пошкодила. Орки відбудували містечко після того, як Орду очолив Тралл.

Це єдине містечко Орди на болоті Скорбот. Посеред нього досі стоїть велика зала, рідкість для орочих громад. Підхід стережуть дві землянки. Звідси розходяться дозори, а невеликі табори поблизу зміцнюють владу Орди в краю. Більша частина болота досі відсутня на орочих мапах, тож звідси висилають провідників і картографів. Сюди також прибули дослідники вивчати стародавні магічні артефакти, рослини й звірів.]],
            ["temple of atalhakkar"] = [[Понад тисячу років тому імперію Ґурубаші роздерла громадянська війна. У її осерді були Атал'ай, трольські жерці, які прагнули повернути у світ бога крові Гаккара Здирача Душ. Їх перемогли й вигнали, і вони втекли на північ до болота Скорбот. Тут вони звели великий храм, щоб підготуватися до його приходу.

Ізера Сновидиця, Аспект зелених драконів, дізналася про їхній задум, зруйнувала храм і затопила його. Зелені дракони стережуть затоплені руїни й нікого не впускають і не випускають. Вважається, що деякі фанатики Атал'ай пережили її гнів і повернулися до темної служби Гаккару. Їхнім володарем у храмі є Джаммал'ан-Пророк.]],
        },
    },
    [1436] = {
        text = [[Вітер без перешкод гуляє полями Західного краю. Колись ця горбиста земля з пасовищами й полями була житницею Штормовію. Тепер трава пожовкла й порідшала, а поля заполонили птахи-падальники.

Гільдія каменярів відбудувала Штормовій після Другої війни, але так і не отримала платні. Голова гільдії Едвін ван Кліф повів каменярів у сільську місцевість, де вони стали Братством Непокірних. Хлібороби ще не оговталися після орочих набігів і майже не чинили спротиву. Братство вигнало багатьох і найняло ґнолів Річкової Лапи, щоб утримати землю. Його люди палили поля й засолювали ґрунт. Коли до них приєдналися гобліни, Братство озброїлося жниварськими ґолемами, які полюють на кожного, хто йде занедбаними борознами сам.

Штормовію бракує золота й воїнів, тож він полишив край напризволяще. Ґріан Міцнокрив заснував Народне ополчення — загін добровольців, що тримає тут останній опорний пункт проти Братства.]],
        areas = {
            ["alexston farmstead"] = [[Поля садиби Алекстона колись годували родини, доки землю не захопило Братство Непокірних. Це одна з багатьох ферм на півночі й у центрі Західного краю, які тепер утримує Братство. Механічні жниварські ґолеми ходять борознами й стережуть рядки, яких уже ніхто не засіває.

Барос Алексстон, архітектор на службі Штормовію, ще хлопцем працював на цих полях. Згодом земля, що його зростила, перейшла до чужих рук.]],
            ["dagger hills"] = [[За Місяцеграєм через південь Західного краю тягнеться довга гряда пагорбів. Тут мало життя. За місцевістю стежать кулачники, слідопити й грабіжники Непокірних. У пагорбах тримається веселий дворф-пивовар Лютобух Громовар, який говорить римами. Неподалік, кажуть, із землі підводиться гуль Леприт.]],
            ["dead acre"] = [[Колись тут, на південному сході Західного краю, біля мосту до Смерколісся, стояла ферма. Братство Непокірних спалило її разом із полями. Нині тут не ходить жоден хлібороб. Руїни ще димлять, а тліючими ланами блукають жниварські ґолеми.]],
            ["deadmines"] = [[До Першої війни тунелі під Місяцеграєм були найбільшою золотою копальнею на людських землях. Перша війна вигнала звідти шахтарів, і копальні покинули. Казали, що в них ходять привиди. Згодом загін Ліги шахтарів на чолі з десятником Лютополохом розробляв частину тунелів. Братство Непокірних напало на них під час роботи, один із тунелів обвалився, і загиблі шахтарі тепер блукають темрявою як неспокійні невмерлі.

Братство зробило копальні своєю штаб-квартирою. За допомогою гоблінів Едвін ван Кліф будує в їхній глибині велетенський бойовий корабель, яким хоче знищити Штормовій із моря.]],
            ["demonts place"] = [[Від старого хутора на клаптику Демонта, на захід від Місяцеграю, мало що лишилося. Тут осіли агенти Непокірних і вважають землю своєю.]],
            ["dust plains"] = [[Південь Західного краю — суха відкрита рівнина. Декілька таборів тут тримають ґноли, які загрожують кожному, хто проходить. На сході стоїть стара вежа мага, нині твердиня Непокірних. Її назвали вежею Клейвена на честь господаря, розбійника Непокірних Клейвена Мортвейка. Звідси Братство часто починає свої вилазки.]],
            ["furlbrows pumpkin farm"] = [[Фермер Хмуробров і його дружина Верна вирощували тут гарбузи, доки Братство Непокірних не пройшло Західним краєм із механічними жниварськими ґолемами й не захопило ферму. Будівлі тепер тримають Непокірні. Хмуроброви втекли до дороги на півночі Західного краю, покинувши гарбузи.]],
            ["gold coast quarry"] = [[Кар’єр Золотого берега довго постачав Штормовію золото й руду, аж доки Західний край не занепав. Нині кар’єром володіє Братство Непокірних, чиї люди патрулюють кам’янисті виробки.]],
            ["jangolode mine"] = [[Штольні копальні Джанґолода нині займають кобольди. Подейкують, що Братство Непокірних веде з ними справи. Колись це було одне з основних джерел руди в Західному краї, і видобуте йшло до Штормовію.]],
            ["jansen stead"] = [[Ферма Дженсена, найпівнічніша в Західному краї, стоїть біля мосту до Ельвиннського лісу. Братство Непокірних вигнало господарів, і тепер її контролюють агенти Братства та жниварські ґолеми.]],
            ["longshore"] = [[Берег Західного краю довгий і широкий. Це один із найбільших пляжів Азероту. Ним блукають цілі зграї мурлоків, а серед них ходить Старий Мутноок. У морі лежать рештки багатьох кораблів, зокрема ельфійських есмінців.

На далекому південно-західному узбережжі стоїть ферма Дафни Стілвелл. Братство Непокірних уже захопило майже всі землі довкола.]],
            ["molsen farm"] = [[Ферма Мольсена — одна з багатьох ферм Західного краю, які утримує Братство Непокірних. Його жниварські ґолеми патрулюють поля й убивають кожного, хто підходить надто близько.]],
            ["moonbrook"] = [[Місяцеграй був шахтарським містечком і центром угідь Західного краю, житниці королівства. До приходу орків поклади золота під містечком давали третину скарбниці Штормовію. Орки зрівняли його із землею в Першій війні. Воно було одним із останніх, що впали перед знищенням фортеці Штормовія. Після Другої війни його відбудували.

Тепер містечко тримає Братство Непокірних. Воно вигнало містян. На поверхні лишилося тільки кілька вартових Непокірних. Решта живе внизу, у старих шахтарських тунелях під містечком.]],
            ["saldeans farm"] = [[Фермер Салден і його дружина Сальма відмовилися виїхати. Це єдина ферма Західного краю, якої Братство Непокірних так і не захопило, хоча його жниварські ґолеми ходять полями. Оселя вже багато років служить тимчасовим прихистком. Подружжя робить усе можливе, щоб їхні гості вижили.]],
            ["sentinel hill"] = [[Сторожовий пагорб височіє на сході Західного краю. На вершині стоїть дозорна вежа, а нижче на схилі — хатини, кузня, корчма й лісопильня. Народне ополчення Ґріана Міцнокрива тримає пагорб як останню військову твердиню краю й закликає всіх охочих битися з Непокірними. Штормовій допомагає мало.]],
            ["stendels pond"] = [[Невеликий ставок лежить на південний захід від Сторожового пагорба. Його оточили ґноли. На березі лежать кілька старих кісток і є дві могили — ознака того, що вода, вочевидь, уже непридатна для пиття.]],
            ["westfall lighthouse"] = [[Маяк стоїть біля далекого південного узбережжя Західного краю. Вночі його промінь і досі кружляє над водою, хоч підтримує вогонь рука мерця. Світло береже привид капітана Сивенка. За життя він був піратським капітаном. Однієї ночі, коли маяк не світив, його корабель розбився об скелі. Після смерті капітан прийшов до вежі й побачив, як Старий Мутноок виганяє родину доглядача.

Родина повернулася й знову запалила вогонь. Старий Мутноок прийшов назад із береговими мурлоками, і цього разу родина загинула на очах у Сивенка. Крім нього, вже немає кому дбати про світло. Він стоїть на варті біля вежі.]],
        },
    },
    [1437] = {
        text = [[Низький туман висить над Заболоттям, а небо від краю до краю рівно-сіре. Землю перетинають малі річки, озера й ставки. Із трьох боків край оточений горами, а на заході відкривається до океану. Колись по всій землі стояли дворфські твердині. Війна лишила від них самі руїни. Тепер край утримують мурлоки, дикі звірі й орки-відступники.

Під час Другої війни клан Драконової Пащі захопив фортецю Ґрім-Батол у східних горах. Орки та їхні дракони майже винищили диких тварин. Разом із ними занепали й рослини.

Клан утратив край, коли поневолені ним червоні дракони вирвалися на волю й спалили його бази та катапульти. Уцілілі втекли на південь у гори, де живуть досі. Гавань Менетілів, що стоїть на невеликому острові в затоці Барадін, — єдиний опорний пункт Альянсу в Заболотті.]],
        areas = {
            ["angerfang encampment"] = [[Табір Лютоклика розкинувся посеред Заболоття. Це найбільший табір клану Драконової Пащі в краю й домівка орків Лютоклика. Ними командує Нек'рош Черепотрощитель, син Некроса Черепотрощителя. Він хоче зібрати тут військо для нападу на гавань Менетілів і наказав збудувати для штурму катапульти.]],
            ["baradin bay"] = [[Води затоки Барадін омивають узбережжя, де Каз-Модан сходиться з Лордероном. На її дні лежать уламки її історії. Кул-тіраський флот регулярно патрулював затоку під час Другої війни й після неї. Саме в тій війні загинув його Третій флот. Одні кораблі розбилися об узбережжя Заболоття, інші пішли на темне морське дно.

На мілинах плавають мурлоки й кроколіски. У глибшій воді хазяйнують краби й акули.]],
            ["black channel marsh"] = [[Раптори тримають лігва по всій трясовині Чорної Ріки на південному заході Заболоття. Дорога до гавані Менетілів огинає трясовину, а голодніші раптори блукають біля узбіччя.]],
            ["bluegill marsh"] = [[У болотах західного Заболоття стоїть кілька таборів синьожабрових мурлоків. Тутешні мурлоки ходять по двоє чи троє, а очолює їх найлютіший із них, Ґобблер.]],
            ["deepwater tavern"] = [[У таверні «Глибоководдя», жвавому місці зустрічей у гавані Менетілів, часто спалахують бійки. Багато з них починає Тапоке «Слім» Джагн.]],
            ["direforge hill"] = [[На пагорбі Жахокузні, на північному сході Заболоття, темнозалізні дворфи тримають великий табір. Ними керує чорнокнижник Балґарас Паскудний.]],
            ["dragonmaw gates"] = [[Чотири величні брами перекривають звивисту стежку, що здіймається із Заболоття до Ґрім-Батола. Червоні дракони під проводом могутнього Акстроза стережуть брами й не пропускають нікого. За брамами вздовж дороги лежать уламки орочого каравану, який намагався втекти з фортеці.]],
            ["dragonmaw retreat"] = [[Орки Драконової Пащі тримають тут табір уздовж дороги. Серед них є зв’язувачі душ, шпигуни й воїни, які прагнуть відвоювати колишні володіння. Вони клянуться, що Ґрім-Батол знову стане їхнім.]],
            ["drunken dwarf"] = [[Дворф Аґріель Вогневар та його товариші перетворили на таверну старий дозорний пост, утримувати який їхньому королівству набридло. Вони тримають таверну вже понад рік. Поголос розійшовся, і тепер торгівці й купці хочуть бачити їхнє пиво на своїх полицях, а в’яленину на своїх тарілках. Дворфи займаються своїми справами й приймають усіх, хто приходить.]],
            ["dun algaz"] = [[Тунель через Дун-Альґаз існував ще до Війни Трьох Молотів. Коли війна вигнала дворфів Дикого Молота із Залізогарта, вони пройшли цим шляхом.

Орда теж відступала сюди. У Другій війні орків відкинули від Дун-Модра, і вони відступили на південь через долину Тандола й окопалися на місцевій заставі. Андуїн Лотар хотів витіснити їх із Каз-Модана й послав військо знести твердиню. Штурм провалився. Орки втрималися, і Дун-Альґаз став останнім клаптем землі в краї, що лишився за Ордою.

Дворфи-горяни, які стерегли цей прохід, здебільшого трималися пагорбів над ним. Клан Драконової Пащі захопив їхню заставу й відтіснив їх до верхнього тунелю. Відколи нижній прохід втрачено, дорога між землями дворфів і гаванню Менетілів стала значно небезпечнішою.]],
            ["dun modr"] = [[Хто тримає старе дворфське місто Дун-Модр, той володіє довколишнім краєм. Місто часто переходило з рук у руки. У Другій війні Орда звела заставу біля руїн. Звідти вона відбивала війська Альянсу й нападала на сусідні угіддя. Воїни зі Стромварта взяли заставу в облогу й відкинули орків на південь, та Орда вдарила у відповідь і повернула її. Коли Андуїн Лотар погнав Орду назад через віадук Тандола, місто повернулося до рук Альянсу й лишилося його після війни.

Тепер місто в руках темнозалізних дворфів. Поки вояки Залізогарта гинули у війнах далеко від дому, темнозалізні під орудою чорнокнижника Балґараса Паскудного спустошили віадук. Невдовзі впав і південний Дун-Модр. Серед уламків досі стоять кузня та корчма з броварнею.]],
            ["excavation site wetlands"] = [[Тут лежать дворфські розкопки, які захопили орки Драконової Пащі. Їхні чудотворці викликають вогняних елементалів, а диверсанти носять бомби. Розкопами повзають великі павуки — печерні ловчі та п’явколови.]],
            ["green belt"] = [[Зелений Пояс на сході Заболоття повниться кроколісками, болотними звірами й слизнями. Ретіл те Ґрінварден, сам болотний звір, наглядає тут за землею. Ґноли пробралися в трясовину, а декого з молодших болотних звірів спотворила скверна.

У Поясі лежать уламки каравану Драконової Пащі. Серед них мають лігва червоні драконята. Схоже, караван розбили, коли звільнені дракони обернулися проти клану.]],
            ["grim batol"] = [[Мури й шпилі Ґрім-Батола здіймаються до сталево-сірого неба над східним Заболоттям, та більша частина фортеці лежить під землею. Дворфи Дикого Молота заснували її й жили там, доки під час Війни Трьох Молотів на неї не впало прокляття. Вони залишили фортецю порожньою.

У Другій війні Орґрім Молот Згуби послав клан Драконової Пащі зайняти порожню твердиню. У її глибинах орки тримали в полоні королеву драконів Алекстразу й примушували червоних драконів служити Орді. Їхня влада скінчилася, коли дракони здобули волю й спалили орків, які їх поневолили.

Більшість вважала, що зло фортеці загинуло разом із кланом. Дворфи відчули, що в горі досі чаїться темрява, й пішли. Тепер Алекстраза поставила довкола фортеці червоних драконідів. Вони нікого не пускають усередину.]],
            ["ironbeards tomb"] = [[Над цвинтарем біля могили Залізобородого стоїть статуя дворфа, схоже, вирізьблена на подобу самого Залізобородого. Склеп лежить одразу на захід від дороги до Дун-Модра в північно-центральній частині Заболоття. Чорні, багряні й потворні слизні осквернили його. Тепер сюди вже не приходять ховати померлих.]],
            ["lost fleet"] = [[«Володарка хвиль» і «Безстрашний» лежать на дні затоки Барадін біля північного узбережжя Синьожабрового болота. Вони належали до кул-тіраського Третього флоту, яким у Другій війні командував Дерек Праудмур, старший син лорда-адмірала Деліна Праудмура. У битві біля Крестфола червоні дракони, поневолені Драконовою Пащею, напали на флот і підпалили його. Дерек видерся на вороняче гніздо попередити батька, та його там убив дракон. Судно невдовзі затонуло. Вижив лише старший помічник Фітзсіммонс із «Володарки хвиль».

Мерці не знайшли спокою. Прокляття підняло затонулі екіпажі як невмерлих. Лише перший помічник Снелліґ зберіг розум, і його привид блукає сусіднім берегом.]],
            ["lost marsh"] = [[За розкопками в Заболотті лежить Загублене болото, яким патрулює великий кроколіск на ім’я Солешип.]],
            ["menethil bay"] = [[У затоці Менетілів кишать кроколіски різного віку й розміру. Мисливці полюють на них заради гарної шкіри. Це відгалуження затоки Барадін між гаванню Менетілів і північними скелями Дун-Морога. Біля входу лежать уламки «Летючої скопи», судна кул-тіраського Третього флоту.]],
            ["menethil harbor"] = [[Перше, що впадає в око, — товстий кам’яний мур довкола портового містечка на маленькому острові біля західного берега. Над муром височіють чотири вежі. Усередину можна потрапити мостом, морем або таємним підземним ходом із материка. Вулиці повні моряків, подорожніх, контрабандистів і піратів.

Першу корабельню тут звела Орда. Після Першої війни воєвождь Орґрім Молот Згуби обрав цей берег для будівництва флоту. На ньому він хотів провести військо в обхід сухопутної оборони Лордерона, тож орки завозили залізо й деревину з дворфських шахт Каз-Модана. Коли Друга війна закінчилася, Альянс захопив місце й відбудував його як портове містечко. Великий адмірал Делін Праудмур назвав його гаванню Менетілів на честь короля Лордерона Теренаса Менетіла II. Раптори з пагорбів час від часу нападають на містечко, але завжди малими гуртами.]],
            ["menethil keep"] = [[Капітан Стоутфіст командує ополченням Менетілів із фортеці Менетілів. Чотири її вежі пильнують портове містечко внизу, наче суворі вартові.]],
            ["mosshide fen"] = [[Мохошкурі ґноли тримають цю залиту водою твань на сході Заболоття. По всій окрузі розкидані їхні табори. Жорстокий ватажок Кісткогриз наказує племені хапати й з’їдати кожного чужинця, якого помітять у болоті.]],
            ["raptor ridge"] = [[На сході Заболоття, одразу на північний захід від небезпечної брами Драконової Пащі, безліч рапторів мають лігва вздовж кряжа Рапторів. У печері кряжа ховається люта Бритвозуб-матріарх і береже свій виводок.]],
            ["saltspray glen"] = [[Коли із затоки дме сильний вітер, море закидає бризки далеко вглиб землі. Від цього лощина Солекрапель і дістала назву. Це невелика ділянка північно-західного Заболоття, відкрита до затоки Барадін із півночі й заходу. Тут густо гніздяться раптори.]],
            ["site of the guardian"] = [[На Місці Вартового серед розкопок Заболоття стоїть стихійний ґолем, якого звуть Охоронцем реліквій.]],
            ["stalkers thicket"] = [[Раптори тримають Хащі сталкера на розкопках Заболоття. Мисливці, засідники й ловчі, здатні зникати з очей, ходять хащами з малечею та матріархинею. Стежкою з двома мисливцями патрулює раптор Тінезуб.]],
            ["sundown marsh"] = [[Найглибша частина Заболоття лежить на північному заході, на болоті Заграви. Тут стоїть станція Хуткозчіпа, невеликий кам’яний дім із вітряком, де живе дивна пара — Фрадд Хуткозчіп і Венна Шовкоборода. Вони продають незвичайні речі, які знаходять на болоті. Довкола повно агресивних кроколісків, ґнолів, рапторів, болотних звірів і слизнів.]],
            ["thandol span"] = [[Дві велетенські кам’яні арки несуть дорогу над прірвою між Заболоттям і височиною Араті. Це одна з найбільших інженерних споруд, які звели дворфи. Її збудували після Війни Трьох Молотів, коли Залізогарт хотів зберегти торгівлю й зв’язки з родичами з Дикого Молота на Орлиному піку. Мости стали і дорогою, і символом зв’язку між двома дворфськими королівствами. Торгівля збагатила обидва. Рід Ковмарів стереже віадук щонайменше три покоління.

Тепер мости носять шрами. Темнозалізні дворфи напали, і одну арку майже знищили. Дворфські війська завзято боронили іншу й билися, щоб відбити сусідній Дун-Модр. Багато з них загинуло.]],
            ["thelgen rock"] = [[Велика печера тягнеться глибоко в гори південного Заболоття. Від неї й дістало назву це місце, печера Тельґена. У печерах повзають отруйні павуки, а десь у глибших тунелях залягають жили вогнекам’яної руди.]],
            ["whelgars excavation site"] = [[Дворфи прийшли мирно копати тут, на схід від гавані Менетілів. Потім розкопки заполонили плямисті раптори. Невеликий гурт дворфів, серед яких розвідувач Вельґар зі своєю командою, опинився в пастці на кряжі над власними розкопками. В ямах унизу блукають раптори.]],
        },
    },
    [1438] = {
        text = [[Після Третьої війни Малфуріон Шаленство Бурі зник у Смарагдовому Сні. Верховний друїд Фендрал Оленеріг перебрав провід над друїдами нічних ельфів. Він сказав Колові Древніх, що настав час виростити нове Світове дерево й повернути нічним ельфам утрачене безсмертя. Об’єднавши сили, вони підняли з Потайного моря велетенське дерево й назвали його Тельдрассілем, вінцем землі.

Нічні ельфи оселилися серед його гілок. Там, на могутніх відгалуженнях, виріс сутінковий ліс із величезними деревами, струмками й озерами. На заході вони звели Дарнас. Але Ноздорму назвав їхнє бажання зарозумілим і відмовився благословити дерево. Воно росло з вадою, і безсмертя так і не повернулося.

Тепер над краєм нависло щось лихе. Фурболґи й ґреллі збожеволіли, а серед дерев з’явилися сатири. Великі черепахи й морські хижаки тікають із довколишніх вод, викидаються на береги Темнобережжя й гинуть. Джерело скверни досі невідоме.]],
        areas = {
            ["aldrassil"] = [[У серці Тінистої долини височіє Альдрассіль. У гілках цього велетенського дерева розкинулося ціле селище. Провідник долини Тенарон Штормохап оселився на самій верхівці, вище від усіх інших осель, і звідти наглядає за долиною. З-під крони Альдрассіля він виряджає здібну молодь нічних ельфів у широкий світ.]],
            ["banethil barrow den"] = [[Нічні ельфи спорудили обитель кургану Бен'етіль як святилище, де могли спочивати у сні друїди Кігтя. Обитель має дві частини, нижню й верхню. Її захопили спотворені фурболґи племені Кривої Сосни. Нічному ельфові небезпечно заходити туди самому.]],
            ["banethil hollow"] = [[На південь від дороги з Доланаара до Дарнаса в землю врізається невеликий яр. На його схилах засіли ворожі фурболґи, які час від часу нападають на подорожніх із засідки. У глибині западини, під землею, лежить обитель кургану Бен'етіль.]],
            ["cleft"] = [[Розколина лежить на північний захід від Доланаара, біля спотвореної печери Каменя Скверни. Тут ніхто не живе.]],
            ["dolanaar"] = [[Коли молоді нічні ельфи покидають Тінисту долину, то насамперед дістаються Доланаара. Селище стоїть у центрально-східній частині Тельдрассіля, трохи на південний захід від долини. Завдяки своєму розташуванню воно відіграє важливу роль у житті острова. Таллонкай Спритнокорінь керує звідси боротьбою проти спотворених фурболґів і сатирів Великого дерева.]],
            ["fel rock"] = [[Одразу на північ від Доланаара лежить колись прекрасна печера, тепер спотворена скверною. У її темних закутках кишать ґреллі, а в глибині оселився жорстокий сатир лорд Меленас. На охорону лігва він зібрав невелике військо ґреллів під проводом Треґґіла.]],
            ["gnarlpine hold"] = [[У найдальшому південно-західному кутку Тельдрассіля лежить поселення Кривої Сосни. Це дім фурболґів однойменного племені й осідок їхнього вождя Урсала Молотобоя.

Колись плем’я жило мирно й вважало нічних ельфів союзниками. Нині фурболґи збожеволіли й нападають на них. Безумство погнало їх зі старих сіл на півдні й заході острова до селища Зоряний Бриз та обителі кургану Бен'етіль.]],
            ["lake alameth"] = [[На південь від Доланаара розкинулося озеро Аль'Амет, одна з найбільших водойм Тельдрассіля. На берегах майже нічого нема, крім невеликої пристані. Останнім часом там бачили багато розлючених деревників, тож на озері вже небезпечно. Деналан поставив поблизу води невеликий намет і намагається з’ясувати, що за недуга шириться островом.]],
            ["oracle glade"] = [[Перша й наймогутніша місячна криниця Тельдрассіля стоїть у святилищі на північному заході острова, на поляні Оракула. Поруч росте Дерево Оракула. Його стовбур широкий, а гілки утворюють подобу великого орла на спині могутнього ведмедя. Багато хто вірить, що таку форму дереву надала магія природи. Разом із друїдами воно наглядає за ростом Тельдрассіля і здатне скидати клапті кори з написами, щоб передавати вісті верховному друїдові Фендралу Оленерогові в Дарнас.

Поблизу звили гнізда кривавопері гарпії. Вони загрожують дереву, тож проти них вислали невеликий загін Вартових.]],
            ["pools of arlithrien"] = [[На заході Тельдрассіля, на південь від входу до Дарнаса, лежать невеликі Арлітріенські стави. Колись це було тихе місце, й серед ставів досі стоїть самотня місячна криниця. Нічні ельфи залишили її, коли фурболґи Кривої Сосни стали загрозою. Тепер берегами нишпорять ворожі звірі.]],
            ["ruttheran village"] = [[Селище Рут'Теран лежить при самому підніжжі Світового дерева й слугує портом Дарнаса, міста нічних ельфів високо вгорі. Звідси до столиці веде портал, а в самому селищі є стоянка гіпогрифів. Від єдиної пристані відходять «Місячні бризки», судно до Аубердіна на Темнобережжі. Коли настає Свято вогню Сонцевороту, у селищі запалюють жаровні.]],
            ["shadowglen"] = [[Над Тінистою долиною вічно стоять сутінки. Ця невелика галявина на північному сході Тельдрассіля майже не бачить повного денного світла. З усіх боків її оточують гори. Єдиний просвіт лежить на півдні, де стежка між горами веде до Доланаара. Посеред галявини височіє Альдрассіль, наче вся долина виросла довкола цього великого дерева.]],
            ["shadowthread cave"] = [[У печері Тіненитки в північно-західному кутку Тінистої долини здавна жили велетенські павуки. Останнім часом вони стали агресивніші, тож у печері тепер значно небезпечніше. Найбільша з них, Ґітісс Мерзенна, згубила вже не одного недосвідченого нічного ельфа.]],
            ["starbreeze village"] = [[На південний схід від Тінистої долини стоять кілька невеликих будинків селища Зоряний Бриз. Колись тут жили нічні ельфи, та селище захопили спотворені фурболґи Кривої Сосни. Вулиці патрулює Урусон, а на околицях можна зустріти Феросітаса Пожирача Снів.]],
            ["wellspring lake"] = [[Колись рибалки нічних ельфів полюбляли Джерельне озеро, невелику водойму на північний схід від Дарнаса. Його живить джерело в глибині Світового дерева, а витікає з нього Джерельна ріка. Тепер тут оселилися спотворені деревники, а в околицях кишить нічними шаблезубами й павуками.]],
            ["wellspring river"] = [[Джерельна ріка бере початок у джерелі в глибині великого дерева. Від Джерельного озера вона тече на північ і з краю Тельдрассіля спадає широким водоспадом у море далеко внизу. Береги патрулюють збожеволілі деревники й нападають на кожного, хто підходить близько.]],
        },
    },
    [1439] = {
        text = [[Своєю назвою Темнобережжя завдячує туману. Більшість днів над берегом висить сіра імла, а дощ і вітер шмагають кам’янисті пляжі.

Десять тисяч років тому цей край лежав далі від моря. Нічні ельфи збудували тут великі міста, зокрема Амет’Аран і Башал’Аран. Міста впали, коли першу Криницю Вічності зруйнували, а Великий Розкол проклав нову берегову лінію. Їхні руїни досі стоять на урвищах. Кажуть, їх потроху захоплюють мурлоки й наґи.

Нечисленні нічні ельфи, що тут жили, пішли під час Третьої війни. Після неї дехто повернувся відроджувати порт. Руїни, яких не змогли відбудувати, вони розчистили. Фендрал Оленеріг також привів на цей берег друїдів. Саме звідси вони посадили Тельдрассіль.

Гори на сході стримують більшу частину скверни зі Сквернолісся, та річки все одно несуть її вниз. Від неї земля сіріє, тварини труяться, а фурболґи, яких вона сягає, впадають у лють, що вже не минає.]],
        areas = {
            ["ametharan"] = [[Руїни Амет'Арана лежать на південний схід від Аубердіна. Королева Азшара звела це місто та його близнюка, Башал'Аран, для улюблених високородних. Там були базари й храми Елуни, а від імені королеви містом правив Атрік Нарассін. В останні дні старої імперії місто вже лежало в руїнах, а його мешканці чіплялися за землю, наче це могло врятувати їх від загибелі. Атрік прийшов і запевнив їх, що закляття їх захистить. Поки він говорив, ельфи довкола помирали, а їхні душі переходили в його камені душ. Він запевняв, що в каменях на них чекає вічне життя.

Неспокійні духи досі повнять руїни. Серед каміння стоять дві великі плити, на яких викарбувано історію міста та його падіння. Коли одна з Вартових спробувала їх прочитати, високородні прогнали її.]],
            ["auberdine"] = [[Аубердін стоїть на березі, який утворився під час Великого Розколу, коли море знищило великі міста стародавньої імперії нічних ельфів. Відтоді Темнобережжя залишалося безлюдним. Аубердін на березі Потайного моря — єдине містечко, якому вдалося тут прижитися.

Його вулицями ходять дворфи, гноми, люди й навіть вищі ельфи, що незвично для селища нічних ельфів. Порт приваблює купців зі Східних Королівств. Заради їхньої зручності місто освітлюють яскравіше за більшість поселень нічних ельфів, а на деяких вказівниках написи дарнаською та загальною мовами. Щоденними справами керує старійшина Тандріс Вітроткач, а охороняють містечко Вартові. На цьому узбережжі мурлоки топлять судна. Містяни роблять обладунки з луски вбитих нападників.

Біля маяка на скелях лежать уламки корабля, яким командувала ельфійка Елура. Її вантаж елунітової руди пішов на дно разом із нею.]],
            ["bashalaran"] = [[Маг Астеріон однаково майстерно володів клинком і таємною магією та був правою рукою Атріка Нарассіна в Башал'Арані. Він жив серед містян і часто їздив до Амет'Арана дбати про тамтешніх мешканців. Потім Атрік магією створив печать із місячного каменю й ув’язнив Астеріона в руїнах. Ніхто не знає, чому він обернувся проти свого помічника. Астеріон дожив віку в муках, а коли помер, виявив, що його дух прикутий до руїн так само міцно, як колись тіло.

Саме місто впало, коли першу Криницю Вічності зруйнували. Відтоді серед каміння оселилися сатири й ґреллі. Вони живляться магією, що залишилася в руїнах, і дужчають. До святилища, де ув’язнений Астеріон, вони ніколи не наближаються.]],
            ["blackwood den"] = [[На крайньому півдні Темнобережжя, поблизу межі Ясенедолу, кілька таборів фурболґів і невелика печера утворюють лігво Чорнолісних, яке також називають їхньою твердинею. Тутешніх чорнолісних фурболґів спотворив скверномох. Табори й печеру тримають їхні воїни, шамани й великі урси.]],
            ["cliffspring falls"] = [[Скельноджерельні водоспади живлять Скельноджерельну річку й дають Темнобережжю більшу частину питної води. Колись вона була чистою. Тепер печеру, з якої вона витікає, опоганено, як і чимало земель довкола.

Про причину сперечаються. Одні кажуть, що скверна просочується зі Сквернолісся. Інші звинувачують Молот Сутінків. Його культистів бачили в глибині печер, звідки витікає вода. У печері також повзають наґи.]],
            ["cliffspring river"] = [[На півночі Темнобережжя Скельноджерельна річка тече від Скельноджерельних водоспадів до моря. Штормолускі наґи отруїли її, і звірі, які п’ють із неї, часто хворіють.]],
            ["grove of the ancients"] = [[Ону, древній знань, живе серед каменів діброви Древніх, священних руїн давнього храму нічних ельфів у горах південно-східного Темнобережжя. Храм звели обабіч бурхливої Дикогнутої ріки. Тут збирається Коло Древніх. Мудрому й терплячому Ону складає товариство сплячий друїд. Древнього непокоять наґи й діяльність культу Молота Сутінків у цих краях.]],
            ["long wash"] = [[Попри свою назву, Довга хвиля — найкоротша ділянка узбережжя Темнобережжя. Сірий пісок тягнеться від Аубердіна на південь, до берега на захід від Амет'Арана. Небо тут завжди затягнуте хмарами. Пляж усіяний уламками, а мурлоки навідуються сюди дедалі частіше.]],
            ["masters glaive"] = [[На південному заході Темнобережжя лежить велетенський череп, пробитий адамантиновою глефою. Це рештки Соґґота Повзуна, вісника Древніх Богів, а клинок називають Глефою властителя. Колись нічні ельфи вважали це місце священним.

Плити, які відкопала Ліга дослідників, розповідають, що тут сталося. Титани послали проти Соґґота двадцять кам’яних велетнів. Битва була така жахлива, що до її кінця дожив лише найбільший із них, Кронн. Він дав Соґґотові обвити себе щупальцями й підняти так високо, щоб дістати великим мечем до черепа. Меч так і залишився в кістці.

Тепер цим місцем володіє Молот Сутінків. Культисти розкопують рештки Соґґота, сподіваючись повернути його до життя.]],
            ["mists edge"] = [[Сірі пляжі й похмурі бухти утворюють Кромку туману, найдовшу ділянку Темнобережжя. Вона тягнеться від околиць Аубердіна до північного краю області. На піску лежать велетенські туші морських тварин, а у воді видніються уламки затонулих кораблів. Уздовж усього берега снують краби, а в бухтах завжди можна натрапити на мурлоків.]],
            ["remtravels excavation"] = [[Ці розкопки названі на честь розвідувача Сноходня, відомого археолога Ліги дослідників. Його команда знайшла тут сліди величної цивілізації. Сам Сноходень знайшов скам’янілість із незвичайними магічними властивостями й забув, куди її поклав. Згодом із землі повиривалися велетенські ґолеми й заполонили розкопки. Схоже, Сноходень цього навіть не помітив.]],
            ["ruins of mathystra"] = [[На півночі Темнобережжя, за вежею Алталакс, лежать руїни Матистри. До Великого Розколу це було місто нічних ельфів, зведене в добу високородних. Коли Криниця Вічності розірвалася й світ під нею розколовся, Матистра загинула разом із безліччю інших міст. Нічні ельфи, які вціліли, не повернулися її відбудовувати. Вони оселилися в менших селищах далі на південь уздовж берега й покинули руїни.

Відтоді руїни захопили штормолускі наґи. Вони люто боронять їх від усіх, хто наближається. Серед повалених каменів досі трапляються реліквії давніх високородних. Молоді нічні ельфи часом приходять сюди по них, остерігаючись наґів і примарних шаблезубів, що нишпорять поміж руїн міста їхніх предків.]],
            ["tower of althalaxx"] = [[Атрік Нарассін правив містами-близнюками від імені королеви Азшари. Згодом ця посада йому надокучила, і він проводив дні у власній вежі Алталакс, задалеко від обох міст. Вибух Криниці Вічності відкинув його далеко звідси та зробив безсмертним. Він дістав здатність виснажувати інших магів і живитися їхньою силою.

Тепер у вежі збирається культ Темного Пасма. Серед його чорнокнижників є й сатир, а очолює їх Атрік.]],
            ["twilight shore"] = [[Сірі пляжі тягнуться вздовж південного берега Темнобережжя від кінця Довгої хвилі, на захід від Амет'Арана, аж до Ясенедолу. Це найурвистіша частина узбережжя. На півдні піщані смуги переривають скелі й невеликі острови. На пляжах товпляться сіромлисті мурлоки, у прибережній воді полюють акули-лисиці, а на березі збираються також наґи Чорноводних глибин. Піском снують рифові та припливні повзуни, а серед сіромлистих блукає мурлок на ім’я Болотяник Жорстокий.]],
            ["twilight vale"] = [[Сутінкова долина охоплює ліси на південь від Амет'Арана й сягає межі Ясенедолу. Серед дерев чатують спотворені фурболґи, здичавілі нічні шаблезуби й скажені ведмеді. Подорожнім радять триматися дороги.]],
            ["wildbend river"] = [[Дикогнута ріка несе хворобу з гір. Це продовження Кровотруйної ріки, яка витікає зі Сквернолісся в південну частину Темнобережжя поблизу діброви Древніх. Її отруєні води несуть скверну з лісу в низини.]],
        },
    },
    [1440] = {
        text = [[Дощ у Ясенедолі йде майже без упину, але дерева такі старі й густі, що до землі дістаються лише тонкі цівки. Після Великого Розколу нічні ельфи полювали в цих лісах, та міст тут не будували. Ліс бережуть Дозорні й древні — живі дерева-охоронці. Вони нападають на кожного, хто рубає живе дерево.

Орда прийшла сюди під час Третьої війни. Гобліни під проводом Нілока Жадібнопалого взялися рубати дерева, а за ними прийшов клан Воєнної Пісні. Кенарій прибув відновити зрубане, але Ґроммаш Пеклокрик, обдурений повелителями Палаючого Легіону, вбив напівбога. Тоді палаючі інфернали Архімонда впали з неба, а невмерлі й демони рушили крізь ліс до гори Гіджал.

Тепер нічні ельфи утримують Астранаар та інші притулки на заході. Орда тримає схід із застави при Тріснутому Дереві й заготовляє деревину в лісорубних таборах Пісні Війни. У лісі досі лишилися демони Легіону, а сатири заволоділи старими ельфійськими руїнами.]],
        areas = {
            ["astranaar"] = [[Астранаар стоїть на острові посеред озера. З берегом його з’єднують два мости, а через містечко пролягає головна дорога. Це найбільше поселення Ясенедолу. Біля озера лежить кладовище.

Рене Вовкогін командує тут Вартовими й розвідниками та намагається послабити скверну, що проникла в давній ліс. На півночі побільшало колючохутрих фурболґів, і Рене боїться, що вони наберуться відваги напасти на сам Астранаар.]],
            ["bathrans haunt"] = [[Поламані колони й повалений мармур виділяють руїни, які нічні ельфи давно покинули. Тут осіли агенти Відречених, здебільшого травники й громили, що їх охороняють. Там, де вони працюють, трава побуріла, а квіти зів’яли. Серед каміння агенти влаштували тимчасову лабораторію й використовують місцеві трави для лихих справ.

Цілюща рослина під назвою «Волосся Батрана» росте лише тут.]],
            ["blackfathom deeps"] = [[На Зорамському узбережжі колись стояв храм Елуни, богині місяця в нічних ельфів. Великий Розкол розтрощив його й затопив під хвилями Потайного моря. Тисячі років руїн ніхто не чіпав.

Потім сюди прийшов Молот Сутінків, покликаний шепотом і лихими снами. Культ приніс у жертву незліченну кількість невинних і дістав завдання стерегти й годувати Аку'май-Пожирачку. Вона триголова гідра й улюблениця Древніх Богів. Культисти мусять дбати про неї, доки вона не буде готова обрушити на світ темну силу. У затоплених печерах ними керує сутінковий лорд Келріс, а місячну криницю храму отруїла скверна Древнього Бога. Наґи й сатири теж прийшли сюди, принаджені давньою силою руїн, щоб знайти їхні таємниці. Тепер це місце називають Чорноводними глибинами, і назва личить йому.]],
            ["bloodtooth camp"] = [[Ран Кривавозубий, король усіх фурболґів Ясенедолу, тримає цей табір одразу на захід від Далекоплинної річки й на південний захід від південної місячної криниці. Табір дістав назву від нього. Усіх тамтешніх фурболґів спотворила скверна. Вони нападають на кожного чужинця, хто наближається.]],
            ["bough shadow"] = [[Тут росте Велике дерево, яке є брамою до Смарагдового Сну. Портал стережуть зелені дракони Фантім і Ловець Сну. Крізь нього до лісу прокралися прокляті зелені драконіди. Тепер вони патрулюють ліс гуртами.]],
            ["demon fall canyon"] = [[Тут повелитель безодні Маннорот бився з Траллом і Ґроммашем Пеклокриком. Від його удару Тралл знепритомнів, та сам Маннорот не встиг ухилитися від сокири Ґроммаша, яка розсікла йому груди. Помираючи, Маннорот вибухнув полум’ям і світлом, і цей вибух забрав життя Ґроммаша. Зі смертю Маннорота спало прокляття Палаючого Легіону, накладене на орків. Від тієї битви каньйон дістав назву.

Тут стоїть пам’ятник Ґроммашеві. Багато орків приходять сюди вшанувати воїна, який їх визволив. Земля досі просякла скверною, а каньйон повниться меншими демонами.]],
            ["demon fall ridge"] = [[Менші демони блукають схилами кряжа й покинутою курганною обителлю, вирубаною в його боці. У найглибшій частині обителі чекає Діатор-Шукач, повелитель жаху, який очолює демонічний конклав Ясенедолу.]],
            ["dordanil barrow den"] = [[Друїди нічних ельфів здавна приходили спочивати до обителі кургану Дор'Даніл. Коли Орда зайшла в Ясенеділ, обитель лишилася в неї в тилу. Оркам було байдуже до сплячих ельфів. Відречені, які пізніше приєдналися до Орди, зацікавилися ними. Вони ставили досліди над сплячими друїдами, розривали зв’язок між тілом і духом і доводили друїдів до божевілля.

Тепер у кургані скрадаються вбивці Відречених, а поміж ними блукають розлючені душі друїдів. Троє духів сильніші за решту — Утіл Місяцезов, Маворіс Хмаролом і Таніл Темноліс.]],
            ["falfarren river"] = [[Далекоплинна річка тече Ясенедолом із північного сходу на південний захід. Вона приблизно відділяє землі нічних ельфів під владою Астранаара на заході від володінь орків, які тримають заставу при Тріснутому Дереві на сході. Річка неглибока й неширока, та після зливи розливається.

Річка бере початок на схилах гори Гіджал, каскадом водоспадів спадає в озеро й зрештою зникає під горами на півночі Степів. Біля Сквернопалаючого пагорба у воді блукають агресивні болотні звірі.]],
            ["fallen sky lake"] = [[На південь від Срібнокрилої застави лежить невелике озеро з одним островом посередині. Берегами блукають тінезарості, болотні звірі цього лісу. Найсильніший із них, Оракул Тінезарості, тримається острова.]],
            ["felfire hill"] = [[Сквернопалаючий пагорб досі носить шрами Третьої війни, коли тут із неба впали палаючі інфернали й ударили в землю. Відтоді серед каміння мешкають мерзенні демони. Орда укріпила обидва мости на пагорб, щоб напади не сягали її поселень поблизу.]],
            ["fire scar shrine"] = [[Демонічний вплив Тіньової Ради спотворив вівтар Вогняного Шраму на південному заході Ясенедолу й обернув його на осередок великого зла. Тут мешкає Ілкруд Маґтрулл, орк-чорнокнижник із культу Темного Пасма.

Тепер святилище кишить демонами. Час від часу тут з’являється рідкісний вартовий погибелі на ім’я Аккрилус.]],
            ["forest song"] = [[Друїд Кейнет Штиль — єдиний мешканець Лісової Пісні, давніх руїн нічних ельфів на північному сході Ясенедолу. Звідси він керує боротьбою з Відреченими в краї.

Відречені прокралися в Ясенеділ і причаїлися серед руїн та курганів нічних ельфів. Ельфи вважають, що ті хочуть поширити лісом хвороби.]],
            ["greenpaw village"] = [[Спотворені фурболґи з племені Гидколісних оселилися в селищі Зеленолапому, посеред Ясенедолу на південь від прихистку Незайманого лісу. Серед них є шаман Дуболап.]],
            ["howling vale"] = [[У печері поблизу межі Сквернолісся стоїть святилище Мел'Тандріс. Перед ним вирізьблено давній напис на славу Елуни, а на самому святилищі є слова дарнаською: «Істина — провідне світло».

Святилище лежить у руїнах. Його захопила зграя ворґенів, Жахововки. Від їхнього моторошного виття долина й дістала назву.]],
            ["iris lake"] = [[Скверна Сквернолісся просочилася до Райдужного озера в північно-центральній частині Ясенедолу, одного з багатьох куточків лісу нічних ельфів, які піддалися її впливу. Вода стала хворобливо жовтаво-зеленою. Уздовж берега блукають спотворені болотні звірі й нападають на кожного, хто наближається.]],
            ["kargathia keep"] = [[Офіцери Пісні Війни мають осідок у фортеці Карґатія на сході лісозаготівельного табору клану, одразу на захід від Південнолютної річки. Довкола твердині стоять загострені загорожі. Якщо Альянс піде на табір великим військом, з Орґріммара швидко надійде підмога.

Фортецю названо на честь легендарного орка-героя Карґата Гострорука.]],
            ["lake falathim"] = [[Місячне світло Елуни падає на озеро Фалатім у будь-яку годину дня й ночі. Колись нічні ельфи приходили сюди купатися й ловити рибу. Відтоді озеро захопили люті мурлоки. Вченого на ім’я Тероніс востаннє бачили біля самого берега. Він так і не повернувся.]],
            ["maestras post"] = [[Застава Маєстри складається з вежі та однієї великої зали нічних ельфів. Тут живе лише кілька осіб, серед них двоє людей, єдині в Ясенедолі. Дельґрен Очиститель і Фіро Залізорук прибули від Сріблястого Світанку, щоб допомогти нічним ельфам очистити ліс від демонів і невмерлих. Із застави вони підривають діяльність культу Темного Пасма.]],
            ["moonwell"] = [[Нічні ельфи наповнюють місячні криниці священною водою Криниці Вічності, переливаючи її з уже очищеної криниці. Місячне світло Елуни береже її чистоту. Кам’яні водойми сяють срібною водою. Вона зцілює і землю довкола, і кожного, хто її п’є. Жриці обмивають у ній померлих нічних ельфів перед похованням, а Вартові шанують криниці як святилища Елуни.

Ця криниця лежить на схід від Райдужного озера. Біля неї тримається дріада Шел'дрін.]],
            ["mystral lake"] = [[Водяні елементалі озера Містраль колись були вірні нічним ельфам. Їх спотворив маг із Відречених. Це найбільше озеро лісу, а через спотворених елементалів підходити до його берега небезпечно.]],
            ["night run"] = [[Кілька поламаних колон і уламків кам’яної кладки дають прихисток сатирам-скверноштинам у Ночеплині, найменшому володінні сатирів у Ясенедолі. Руїни стоять на виступі землі серед лісу. З боків їх захищають стрімкі скелі, на які не видертися.

Скверноштини уклали союз із культом Темного Пасма.]],
            ["nightsong woods"] = [[Найзапекліші бої Орди й Альянсу точаться в лісах Нічної Пісні, на сході Ясенедолу. Тут утримують землі й клан Пісні Війни, і Вартові Срібного Крила. Вартові тримають захід за Альянсом, а клан Пісні Війни — схід за Ордою.

Найзапекліше сперечаються за землі на крайньому сході. Кожен свій клапоть тримають сатири, орки Пісні Війни й демони Палаючого Легіону. На півдні орки вирубали значну частину давнього лісу й зводять поселення з товстих колод. На місці старих непрохідних хащів вони лишають голу, понівечену землю.]],
            ["raynewood retreat"] = [[На верхівці Великого дерева Незайманого лісу ховається хранитель гаю Ордан, один із найстарших синів лісового бога Кенарія.

Під ним кенарійські захисники, миготливі дракончики й сміхотливі сестри тримають заставу Альянсу. Вони стережуть стежку, що веде на північ, у спотворене Сквернолісся.]],
            ["ruins of ordilaran"] = [[Від давнього міста Орділ'Аран лишилося небагато. Серед розбитого каміння росте дерево, відоме як Серцедрево.

Руїни захопив культ Темного Пасма. Його послідовники чатують серед каміння, готові напасти на кожного, хто наблизиться.]],
            ["ruins of stardust"] = [[Руїни Зорепилу стоять на острові посеред озера. Колись їх вважали священними. Відтоді сюди докотилася демонічна скверна Сквернолісся. Вода й каміння однаково нею просякли, а між руїнами блукають великі болотні звірі, спотворені отруєною водою.

Лише кущі зорепилу, розкидані довкола, уникли скверни. Відомо, що напій із них має сильну цілющу дію.]],
            ["satyrnaar"] = [[Серед зруйнованих будівель Сатирнаара стоять намети хмуросердих сатирів. Із руїн, які сатири тримають у лісі, ці збереглися найкраще. Їхні пеклокличі викликають бісів і порожнечників. Вони уклали союз із культом Темного Пасма.

Руїни лежать поблизу головної дороги від Тріснутого Дерева до Азшари. Тож за цю частину володінь сатирів точаться найзапекліші сутички.]],
            ["shady nook"] = [[У Тінистому закутку, маленькій долині Ясенедолу, живе родина ведмедів. У схилі пагорба зяє вхід до печери. Вочевидь, там їхній барліг.]],
            ["shrine of aessina"] = [[У лісі на захід від Астранаара стоїть вівтар Аессіни, духа дикої природи. Нічні ельфи звели їй святилища по всьому Калімдору, хоча мало хто зі смертних багато про неї знає.]],
            ["silverwind refuge"] = [[Притулок Срібновію стережуть Вартові, а пліч-о-пліч із ними служить ціле військо водяних елементалів. Разом з Астранааром нічні ельфи вважають його однією з головних застав Ясенедолу. Притулок лежить одразу на північ від озера Містраль. Гостей тут радо зустрічають, а місцева корчма розкішніша за більшість корчем цього лісу.]],
            ["silverwing grove"] = [[Вартові Срібного Крила мають осідок у цьому гаю в південній частині Ясенедолу, на захід від озера Впалого Неба. Тут тримає варту стражниця Далепісня. Через чотири роки після Третьої війни нічні ельфи почали великий наступ, щоб відвоювати ліси Ясенедолу й вигнати Вершників Пісні Війни зі своїх земель. Срібнокрилі відгукнулися на заклик і поклялися не спочивати, поки кожного орка не переможуть і не виженуть з Ущелини Пісні Війни.]],
            ["silverwing outpost"] = [[На боці Далекоплинної річки, який тримає Орда, стоїть східний бастіон оборони Альянсу в Ясенедолі. Вартові на Срібнокрилій заставі відбивають безперервні напади місцевих орків, які прагнуть раз і назавжди вигнати Срібнокрилих із лісу.]],
            ["southfury river"] = [[Південнолютна річка починається з озера на горі Гіджал. Звідти вона спадає низкою разючих водоспадів, широка й стрімка. Мабуть, це найпомітніша річка Калімдору. Вона позначає межу Ясенедолу й Азшари, а далі на південь відділяє Степи від Дуротару.

Одразу на північ від західного мосту до Орґріммара є місце на воді, де сходяться чотири землі — Ясенеділ, Азшара, Дуротар і Степи. У гирлі річка останнім водоспадом спадає у Велике море на північний схід від гоблінського порту Брашпиль.]],
            ["splintertree post"] = [[Ґроммаш Пеклокрик і його клан Пісні Війни звели заставу при Тріснутому Дереві під час Третьої війни, коли орки вперше зайшли в Ясенеділ. Це одне з найдавніших поселень Орди в Калімдорі.

Нічні ельфи Ґроммаша не забули. Палаючий Легіон ошукав його, і він убив у цих лісах напівбога Кенарія. Через це й через крихкий мир між Ордою та Альянсом на заставу часто нападають у відповідь, особливо після набігів на Астранаар.

Тепер заставу утримують орки й таурени, переважно розвідники та вартові.]],
            ["talondeep path"] = [[Звивистий тунель пролягає крізь скелю між Ясенедолом і Каміннопазуристими горами. З одного боку він виходить на захід від озера Містраль, з іншого — в північно-західній частині Вітрокосих скель. Від нього відходять невеликі тупики, а в стінах видніються дивні заглибини. Усередині ніхто не живе. На скелі над тунелем можна знайти залишки старої дороги.]],
            ["thistlefur village"] = [[У цьому селищі на північ від Астранаара живуть фурболґи племені Колючохутрих. Вони спотворені скверною, вороже налаштовані й нападають на кожного, хто забреде надто близько. Ними керують двоє лютих воїнів — Дал Кровопазур і Рорґіш Щелепа.]],
            ["warsong labor camp"] = [[Орочі вартові наглядають за лісорубами й збирачами в трудовому таборі Пісні Війни на південному сході Ясенедолу, на схід від озера Впалого Неба. Табір далеко від підмоги, тож загони Альянсу час від часу нападають на варту, не боячись відплати.]],
            ["warsong lumber camp"] = [[Поблизу лісозаготівельного табору Пісні Війни ліси Ясенедолу дзвенять від сокир. Тут клан рубає давні дерева на деревину. Працюють батраки й вирубники з подрібнювачем, а вартують бугаї, розвідники й шамани Орди. У таборі є псарня, а його твердиню, фортецю Карґатія, названо на честь героя орків Карґата Гострорука. Фортеця стоїть одразу на захід від Південнолютної річки, тож підмога з Орґріммара може прибути швидко.]],
            ["xavian"] = [[Сатири оселилися в руїнах давнього храму нічних ельфів на північному сході Ясенедолу. Із трьох поселень сатирів у лісі осередком їхньої сили, схоже, є Завіан, бо тут живуть і принц Щент, і Ґелтаріс. Руїни повняться пройдисвітами, пеклокличами, скверноклятами й зрадниками секти.]],
            ["zoram strand"] = [[До Великого Розколу поблизу цього пляжу стояло поселення нічних ельфів Зорам. Розкол зруйнував його, а Потайне море забрало те, що лишилося.

Тепер берег тримають наґи. На піску лежать уламки кораблів і викинуті на берег морські істоти, а наґ аж кишить. Орда має тут невеликий форпост і б’ється з гнівохвостими наґами за узбережжя. Тут також лежать Чорноводні глибини.]],
            ["zoramgar outpost"] = [[На форпості Зорам'ґар, порту Орди на Зорамському узбережжі, над водою простяглися причали. Орда звела тут форпост і звідси воює з гнівохвостими наґами.]],
        },
    },
    [1441] = {
        text = [[Вважають, що колись цей каньйон прорізала річка. Вона лишила по собі високі стовпи пісковику й зелений ліс уздовж берегів. Потім Великий Розкол розірвав світ. Річка змінила русло, дерева загинули, а ґрунт став помаранчевим пилом. Озеро на сході висохло й перетворилося на велетенський солончак нижче рівня моря. Попри безплідну землю, схід сонця із застави Розкутого Вітру чи з пласких вершин довкола Темнохмарного верхів’я буває разючим.

Із дна каньйону й досі здіймаються десятки кам’яних стовпів, наче ліс. Верхівки багатьох з’єднують мости. Так можна перетнути каньйон, оминувши загони кентаврів, що патрулюють унизу.

Каньйони здавна належать тауренам. Щоб триматися подалі від племен кентаврів, які мало не винищили їх, таурени живуть на вершинах високих скель. Тепер за підтримки Орди вони дають відсіч і кентаврам, і фанатичному племені Зловісного Тотема.]],
        areas = {
            ["camp ethok"] = [[На північному заході Тисячі Шипів тримають табір кентаври Ґалаки. Це менше з двох їхніх володінь. Більшість племені живе на скелях Розщепленого Копита. Табір стоїть неподалік дороги й Білосяжної застави Орди. Звідси кентаври вирушають у набіги на каравани й мандрівних купців. З іншими кентаврськими племенами Ґалаки не мають союзів.]],
            ["darkcloud pinnacle"] = [[На трьох невеликих пласких вершинах оселилися таурени Зловісного Тотема. Довкола є ще кілька менших порожніх вершин. Верхів’я сполучають мотузяні мости. Нагору ведуть тільки два шляхи: природний схил підіймається на четверту вершину й закінчується мостом, а другий шлях проходить іншим мостом. Обидва добре охороняють.

Тут Зловісний Тотем очолюють Арнак Зловісний Тотем і Гарб Гидка Круча.]],
            ["freewind post"] = [[Застава Розкутого Вітру стоїть на пласкій вершині, поза досяжністю бойових загонів Ґалаків, які таборують унизу. Мешканці підіймаються з дна каньйону дерев’яними підйомниками. Від вершини до вершини тягнуться мотузяні мости аж до селища. Верескливі гарпії становлять меншу загрозу.

Таурени застави насторожилися, коли на Темнохмарному верхів'ї осів Зловісний Тотем. Тауренів викрадали, приходили й ішли таємничі темні посланці, а в убивствах звинуватили Зловісний Тотем, передусім їхнього вождя Арнака.]],
            ["great lift"] = [[Цей підйомник збудували таурени. Він перевозить подорожніх між Степами й Тисячею Шипів. Його стережуть Ґріш Довгобіг і сміливець Місячний Ріг.]],
            ["highperch"] = [[На цій височині на заході гніздяться горді виверни Високого Сідала. Молоді таурени приходять із застави Розкутого Вітру вивчати їх і брати яйця зі споконвічних гніздівель. Виверн із цих яєць вирощують як їздових тварин Орди. Дикі виверни нападають на кожного, хто заходить між гнізда.]],
            ["ironstone camp"] = [[На межі Мерехтливих рівнин таборує невеликий загін Орди. Його послали вигнати дворфів із розкопок Іржавобою, та справа обернулася гірше, ніж гадали. Із сусідньої печери вирвалися силітиди й напали на загін. Ним керує Моктар Крін, а розкопки досі кишать силітидами.]],
            ["mirage raceway"] = [[Гоблін Поззік і гном Фіззл Латуноболт були певні, що саме їхній народ має кращих інженерів. Щоб це довести, вони збудували трек і ракетні машини та зібрали команди водіїв.

Гоблінські й гномські боліди змагаються тут щодня. Прихильники і з Орди, і з Альянсу приходять уболівати за улюбленців, а підозрілі типи ставлять гроші на переможця. Після кожних перегонів обидві команди гарячково шукають, що вдосконалити, щоб наступного разу здобути перевагу.]],
            ["razorfen downs"] = [[За легендою, там, де поліг напівбог Аґамаґґан, із його крові виросли величезні зарості колючих лоз. Найбільше сплетіння свинобрази шанують як місце його спочинку, а нори Бритвоболотих — їхнє родове місце поховання. Кажуть, вхід і є пащею Аґамаґґана, арковим просвітом у зовнішньому куполі, так добре захованим, що його знайде лише той, хто знає, де шукати.

Нори — споконвічна столиця свинобразів. У терновому лабіринті живуть верховні жерці племені Мертвоголових серед великого війська відданих воїнів. Після Третьої війни ліч Амненнар Стужевій і посланці Скари підкорили свинобразів і зробили лабіринт твердинею невмерлих. Свинобрази б’ються, щоб відвоювати місто, перш ніж Амненнар поширить свою владу на всі Степи.]],
            ["roguefeather den"] = [[Цю маленьку печеру на півдні Тисячі Шипів заполонили гарпії. Вони верещать на кожного, хто наближається. У глибині лігва гарпії складають здобуту їжу й ревно її стережуть.]],
            ["rustmaul dig site"] = [[Дворфи Ліги дослідників відкопували тут давні руїни, коли бойовий загін Орди під проводом Моктара Кріна напав і перебив їх усіх. Бій розбурхав гніздо силітидів у печері на розкопках. Рій, який звідти хлинув, прогнав уже ослаблений загін. Тепер розкопки покинуті, а землю тримають силітиди.]],
            ["screeching canyon"] = [[Войовничі й галасливі крикняві гарпії заполонили цей каньйон на півдні Тисячі Шипів. У глибині каньйону лежить лігво Оперених пройдисвіток.]],
            ["shimmering flats"] = [[На півночі Мерехтливих рівнин, далеко від води, лежать уламки вітрильника. Вони нагадують, що це було дно озера, яке висохло. На цій пласкій солі на південно-східному краї Тисячі Шипів нічого не росте. Тут живуть василіски, скорпіди, черепахи й грифи.

Рівнина привабила гоблінів і гномів, які влаштували тут перегони на своїх машинах. Їхні винаходи часто нестійкі. Земля вся у вирвах, а по солі розкидані уламки безлічі невдалих пристроїв.]],
            ["splithoof crag"] = [[Кентаври Ґалаки тримають селище під північною стіною Тисячі Шипів, одразу на схід від Темнохмарного верхів'я. У печері на гірському схилі посеред селища лежить їхня твердиня, укріплення Розщепленого Копита.]],
            ["splithoof hold"] = [[Ця печера в скелях Розщепленого Копита — твердиня кентаврів Ґалаків. Усередині стоїть стародавня жаровня, в якій вічно горить Священне Полум’я.]],
            ["tahonda ruins"] = [[Давнє селище тауренів занепало й потонуло в пісках Мерехтливих рівнин. Про нього відомо мало. Серед руїн живуть солекам’яні василіски. Можливо, саме через них покинули селище.

Інші сліди вказують на ворожий напад. На одній зі шкіряних споруд видно дві групи по три паралельні розриви. Руїни лежать на півдні рівнин, біля стежки крізь гори до Танаріса.]],
            ["weathered nook"] = [[Дорн Рівнинний Ловець і Прата Пантрувачка Хмар живуть у невеликій добре схованій печері в північній стіні Тисячі Шипів. Дорн навчає віри, витривалості й сили.]],
            ["weazels crater"] = [[На півночі Мерехтливих рівнин зяє велика глибока вирва. Звідки вона взялася, ніхто не знає. Назва натякає або на того, хто її знайшов, або на того, хто її зробив. Довкола розкидані уламки й менші вирви. У цих краях гобліни й гноми ганяють на небезпечних машинах, тож, можливо, це слід нестійкого винаходу. Тепер у вирві живуть солекам’яні василіски.]],
            ["whitereach post"] = [[Уздовж дороги поблизу табору І'ток стоїть невеликий табір Орди. Серед тих, хто тут зупиняється, — Канаті Сіра Хмара й гоблін Візло Блископідшипник.]],
            ["windbreak canyon"] = [[Вітрозмії заповнили цей каньйон своїми гніздами. Він охоплює більшу частину землі між заставою Розкутого Вітру й Мерехтливими рівнинами, на північ від дороги.]],
        },
    },
    [1442] = {
        text = [[Найсвятіше місце Каміннопазуристих гір лежить на їхній найвищій вершині. Нічні ельфи доглядають там курган і галявину, де спілкуються з духами природи. Таурени теж шанують цю вершину. Колись тут жив безсмертний Оракул і спостерігав, як Мати-Земля сплітає нитки долі.

У давнину Елуна благословила в горах Джерело здоров’я. Під час Третьої війни гарпії схопили виверн, які гніздилися поруч, і забруднили воду. Проти них виступили Тралл, Керн Криваве Копито та його таурени. Вони розбили загін кентаврів, здобули Знак очищення й очистили ним джерело.

Нижче землю спустошено. Гобліни компанії «Авантюра» вирубали майже всі дерева на Вітрокосих скелях, наповнили повітря сажею й отруїли воду нафтою та відходами. Це розлютило орків і тауренів. Духи гір волали так голосно, що їх почули навіть шамани Орґріммара.]],
        areas = {
            ["blackwolf river"] = [[Річка Чорного вовка витікає зі Скельнодонного озера й тече долиною Вітрокосих скель. Річка мала й брудна. Вирубування лісу компанією «Авантюра» отруїло її води.]],
            ["boulderslide cavern"] = [[У цій печері в кінці ущелини гніздяться кобольди Крутих валунів. Вони без упину копають у пошуках резоніту, рідкісного фіолетового кристала, який світиться й несе слід магії землі. Кобольди стережуть його ціною життя.]],
            ["boulderslide ravine"] = [[На схилах цієї невеликої ущелини пасуться барани, а над головою часом кружляє скельний буревій. Ущелина веде до печери, у якій оселилися кобольди Крутих валунів.

Навпроти їхнього лігва є маленька покинута печера. Усередині стоять бочки й горять грубі смолоскипи. Стіни вкриті племінними малюнками, можливо, тауренськими.]],
            ["camp aparaje"] = [[Воїни із застави Зловісного Тотема під проводом Ґрандіґа Темної Хмари напали на табір Апарахе, село тауренів на сході Каміннопазуристих гір. Тут жив Макаба Пласке Копито.]],
            ["charred vale"] = [[Обвуглена долина колись зеленіла. Тут жили криваволюті гарпії, а древолюди ходили її лісом як охоронці.

Потім прийшли гобліни компанії «Авантюра» й спустошили долину. Її духи розлютилися. Коли древолюди відігнали гоблінів, на волю вирвалося багато елементалів. Імовірно, гоблінська зброя встигла отруїти древолюдів, перш ніж гобліни пішли.

Долина на південному заході Каміннопазуристих гір тепер здебільшого в полум’ї й лаві. Серед випаленої землі живуть почорнілі древні й обпалені василіски.]],
            ["cragpool lake"] = [[Над цим невеликим озером тягнеться велетенська споруда компанії «Авантюра». З її платформи Ґерензо Свистоключ наглядає за вирубуванням лісу на Вітрокосих скелях.]],
            ["greatwood vale"] = [[Долину оточують лісисті передгір’я. Рідкі вічнозелені дерева ростуть навіть там, де південні гори майже голі. До долини веде Павутиновита стежка.

Воїни Зловісного Тотема, які напали на табір Апарахе, тепер у долині. Їхні розбишаки й найманці розосередилися серед дерев.]],
            ["grimtotem post"] = [[Воїни Зловісного Тотема, від моцаків і розбишак до чаклунів і найманців, патрулюють заставу й довколишні схили. Звідси плем’я керує своїми діями в Каміннопазуристих горах. Очолює його лютий вождь Ґрандіґ Темна Хмара.]],
            ["malakajin"] = [[Тролі Темного Списа живуть у Малака'джині, невеликому селі Орди одразу на південь від застави Зловісного Тотема. Мисливці скромно заробляють, продаючи здобич подорожнім Орди, які проходять повз.]],
            ["mirkfallon lake"] = [[Хмуромутне озеро заповнює улоговину в серці Каміннопазуристих гір, а посеред води здіймається пагорб. Виверни гніздяться довкола озера, а його берегами блукають слизні й громові ящірки.]],
            ["sishir canyon"] = [[Глибокомохові павуки цілком захопили Сиширський каньйон. Їхні яйця й павутиння вкривають виступи й заглибини скель. У самій глибині чекає Бесселет, наймогутніша з виводка.]],
            ["stonetalon peak"] = [[На крайньому північному заході хребта в зеленій гірській долині стоїть Каміннопазуристий пік. Гору вважають священною, а крізь її камінь тече магія.

У Третій війні Джайна Праудмур зі своєю експедицією влаштувала базу біля входу до печер під піком. Згодом сюди прийшов Тралл зі своєю Ордою в пошуках Оракула. У тих печерах Альянс і Орда якийсь час стояли разом проти Палаючого Легіону.

Тепер пік тримають нічні ельфи й Альянс, а друїди лігва Кігтя дбають про долину.]],
            ["sun rock retreat"] = [[У давнину таурени приходили в Сонцескельну криївку на прощу й відправляли обряди переходу у світ духів. Місце міцно пов’язане з тим світом. Кажуть, колись сам Ан'ше поцілував гору, на якій тепер стоїть криївка.

Тепер її разом тримають орки й таурени. Вона схована між вершинами на південь від Хмуромутного озера. Це найжвавіше поселення гір. Його мешканці відновлюють землю після спустошення компанією «Авантюра» та іншими лихими силами.]],
            ["talon den"] = [[На Каміннопазуристому піку земля відкривається в лігво Кігтя, курганну обитель. Тут живуть дріади й хранителі Хмуромутного озера разом із кенарійськими доглядачами нічних ельфів.]],
            ["talondeep path"] = [[Пазуродертий тунель звивається крізь гори від Ясенедолу до Вітрокосих скель. Від нього відходять невеликі тупики, а в стінах є дивні заглибини. Усередині ніхто не живе.]],
            ["webwinder path"] = [[Павутиновитою стежкою, головною дорогою між Малака'джином і Хмуромутним озером, ходять павуки, барани й громові ящірки.]],
            ["windshear crag"] = [[На Вітрокосих скелях колись стояв великий праліс, і вся долина була зелена й густа. Тепер лишилися пні, брудна вода й механізми, що без упину риплять. Ліс вирубала гоблінська компанія «Авантюра». Усіма роботами керує прокажений гном Ґерензо Свистоключ. Його плоть, схоже, гниє, тож він приладнав до тіла метал і шестірні. Він збудував Супержнивар 6000, машину, здатну перетворювати найбільші дерева на тирсу, і стежить за скелями з платформи над Скельнодонним озером.]],
            ["windshear mine"] = [[Вітрокосі кобольди займають Вітрокосу печеру, олов’яну копальню в кінці річки Чорного вовка на південно-східному краю Вітрокосих скель. Вони копають олово для компанії «Авантюра».]],
        },
    },
    [1443] = {
        text = [[Спустошище — сіра кам’яниста пустка, усіяна кістками, під чорним небом і безупинним вітром. Із напівзасипаних могил визирають черепи давніх кодо. Стовбури давно мертвих дерев — усе, що лишилося від зеленого минулого. Лише західне узбережжя ще буяє зеленню.

Легенда каже, що кентаври народилися від союзу Заетара, сина напівбога Кенарія, і Терадрас, князівни земних елементалів. Перші хани вбили батька, бо соромилися власної потворної подоби. Їхній народ походить із Мародона в західних каньйонах. Коли нічні ельфи перестали їх стримувати, кентаври накинулися на тауренів і зрештою вигнали їх зі Спустошища.

Тепер чотири племені кентаврів, кожне під проводом свого хана, б’ються між собою так само запекло, як із чужинцями. Орда й Альянс розбили тут табори, а культ Палаючого Клинка відкрив портали, щоб привести в цей край демонів.]],
    },
    [1444] = {
        text = [[Довколишні землі безплідні, а Фералас — джунглі з велетенськими прадавніми деревами. Колись нічні ельфи поширили свою владу цим лісом. Усюди лишилися їхні руїни, обплетені корінням і ліанами. Найбільші з них — місто, яке тепер називають Грізним Молотом.

Оґри Ґордунні стали господарями руїн і більшої частини лісу. Вони сплюндрували свої володіння й лишили на землі скверну. У південних лісах їхні загони палять села й роблять засідки на подорожніх. Орда побоюється, що клан міцнішає.

Таурени Похмурого Тотема живуть розпорошено по лісу. За наказом Бельґрома на них полюють агенти Орди. Острови поблизу західного берега заполонили наґи, а нещодавно в лісі знайшли вулики силітидів. Тут росте одне з чотирьох Великих Дерев, що відкривають шлях до Смарагдового Сну. Його бережуть зелені дракони.]],
    },
    [1445] = {
        text = [[Колись Бруднолипка трясовина була високою рівниною, де великі стада паслися у високій траві. Великий Розкол обвалив її в долину, а з-під землі просочилася вода. Відтоді край не висихає. У кожній водоймі чи кущі чатують кроколіски, раптори й павуки. На півдні гніздиться стільки чорних драконів, що місцевість назвали Змієдолом.

До Третьої війни в болотах жили самі дикі звірі. Після битви за гору Гіджал леді Джайна Праудмур привела свій народ на східний берег і звела Терамор на кам’янистому острові. Її батько, великий адмірал Делін Праудмур, привів кул-тіраський флот проти Орди, і трясовина стала полем бою.

Нині ні Орда, ні Альянс не утримують значної частини краю. Вздовж дороги до Степів стоять кілька веж і застав. Залога Терамора тане, бо воїни дезертирують із незрозумілих причин. Єдиний опорний пункт Орди — селище Папорохащі на північному заході. Тут під владою Мок’Морокка живуть оґри Кам’яного Молота.]],
    },
    [1446] = {
        text = [[Кажуть, Ноздорму, дракон часу, оселився в цьому краю ще до того, як хтось почав лічити роки. Йому припали до вподоби спека й безкраї піски. Танаріс був безмежним піщаним морем іще від незапам’ятних часів.

Край укритий хвилястими дюнами під безхмарним небом. Піщані бурі здіймаються зненацька. На півдні земля суворіша. Під горами простягаються глибокі, ледь досліджені мережі печер. Серед пісків звичні гієни, скорпіди, василіски й силітиди, а над ними часом ширяють у гарячих потоках молоді дракони. Силітиди давно будують вулики у глухих куточках. Тут є й володіння титанів — прадавнє місто Ульдум.

Гобліни з картелю Паровиманювання збудували в пустелі Штуковинськ і порт Паровиманювання. На материках ближче до рідного краю їм не дістатися.]],
    },
    [1447] = {
        text = [[Осінь ніколи не полишає Азшару. Дерева вздовж берега палають помаранчевим і червоним. За ними високі урвища спадають до світлих пляжів і мілкого моря, з якого стирчать зубчасті скелі.

Колись берег був частиною Зін-Азшарі, столиці нічних ельфів. Коли демонів вигнали зі світу, Великий Розкол розірвав землю й сюди ринуло море. Більша частина міста затонула. Кілька пошарпаних будівель і досі туляться на урвищах над руїнами серед коралів. Нічні ельфи, що пережили лихо, назвали понівечений берег Азшарою на честь своєї королеви, яку демонічний вплив звів із розуму. Вони вважають край проклятим.

Під час Третьої війни Іллідан Шаленство Бурі пройшов тут із наґами й сатирами та зруйнував ельфійські гавані, щоб ніхто не міг піти слідом. Маєв Пісня Тіні та її Наглядачки пішли його слідом і мусили припинити страждання істот, яких він лишив по собі. Дехто з нічних ельфів каже, що під водою досі ховаються демони. Інші вважають, що королева пережила затоплення й перетворилася на жахливу морську істоту.]],
    },
    [1448] = {
        text = [[Колись Сквернолісся було північним лісом Ясенедолу. Нічні ельфи доглядали його, а Кенарій стеріг. Потім Палаючий Легіон рушив до гори Гіджал. Архімонд наказав осквернити ліс, щоб ослабити нічних ельфів, які його боронили. Володар жаху Тіхондрій виконав наказ за допомогою Черепа Ґул’дана, реліквії чорнокнижника. Іллідан Шаленство Бурі наважився ввійти до лісу, переміг Тіхондрія й забрав череп. Його брат Малфуріон вигнав Іллідана за використання демонічної сили, та скверна залишилася в землі.

Тепер на луках нічого не росте. Древні, що колись охороняли ліс, блукають наосліп. З їхніх покручених гілок сочиться отрута Скверни. Найлютіше вони нападають на все, що нагадує ельфа. Травоїдні уникають проклятих рослин, тож звірі пожирають одне одного й божеволіють від люті. Поміж деревами бродять спотворені скверною фурболґи, а біля осквернених місячних криниць збираються сатири. Нічні ельфи соромляться, що не вберегли цей ліс, і досі намагаються його зцілити.]],
    },
    [1449] = {
        text = [[Три пустелі стискають кратер Ун’Ґоро й майже цілком відтинають його від решти світу. Попри це, кратер заповнюють густі джунглі з дивовижними рослинами й іще дивнішими звірами. Мирні земні елементалі ходять поміж розлюченими дияволозаврами. Посередині здіймається вулкан, на якому нишпорять вогняні елементалі, а земля всіяна незвичними кристалами. Мало хто знає їхнє призначення, хоча дехто з учених у тутешньому таборі їх досліджує.

На кряжах угорі стоять пілони. Навіть ретельне вивчення не пояснило, навіщо вони тут. Кіражі звуть кратер Землями богів. Він давніший за пам’ять усіх живих.]],
        areas = {
            ["fire plume ridge"] = [[Вогнепера скеля здіймається в серці кратера Ун'Ґоро. Це гора з обпаленого каменю, де схилами повзе лава, а в спеці ворушаться елементалі вогню. Тут закінчуються джунглі, випалені лавою. Наймогутніший із вогняних елементалів, Жаропломінь, мешкає в печері на вершині й править палким серцем гори.

Неглибокі жили магми під дном кратера нагрівають водойми й гейзери, які шиплять по всьому Ун'Ґоро. Здається, ніби вся улоговина дихає вогнем гори.]],
            ["fungal rock"] = [[У північно-східній стіні кратера Ун'Ґоро відкривається велика печера. Серед примарних грибів усередині оселилися горили. За входом є невеликий ставок із водоспадом. Там стоїть А-Ме 01, механічна мавпа Карни Сноходень.]],
            ["golakka hot springs"] = [[Від гейзерів Ґолакка без упину здіймається пара. Цей відтинок на заході кратера вкривають водойми й гейзери, нагріті сусіднім вулканом. Довкола водойм блукають старі деметродони й навіжені жаходактилі.

Біля джерел поставив табір гоблін Кракл. Він вивчає, як вони пов’язані з вогнем Вогнеперої скелі.]],
            ["ironstone plateau"] = [[Голий камінь деінде проривається крізь зелень уздовж північно-східного краю Ун'Ґоро, біля самої стіни кратера. Залізокам'яне плато тихе порівняно з рештою кратера. Тут не полюють потвори. На плато живуть пташенята жаходактилів, а його тиша вирізняється серед невпинного буяння Ун'Ґоро.]],
            ["lakkari tar pits"] = [[На півночі кратера Ун'Ґоро лежать озера густої смердючої чорної смоли. Вона міцно хапає істот, які туди потрапили, і над її поверхнею стирчать кістки сотень звірів. Поблизу нишпорять падальники, шукаючи легкої здобичі. У самих озерах живуть смоляні звірі.

На дні ростуть рідкісні смоляні квіти. Їх цінують за красу й витривалість, та вони глибоко в смолі, тож збирати їх важко.]],
            ["marshals refuge"] = [[Прихисток Маршала на північному краю кратера Ун'Ґоро заснувала експедиція під проводом Віллідена Маршала й Холанії Маршал. Вони не були готові до того, що знайшли в кратері. Звірі Ун'Ґоро виявилися надто лютими й один за одним захопили табори. Уцілілі втекли на височину й розбили табір тут, на краю кратера.

З того відступу й виріс прихисток, клапоть землі, який ледве вдалося втримати. Це нейтральне місце.]],
            ["marshlands"] = [[Більшу частину південного сходу кратера займає велике болото із застійною водою й буйною рослинністю. Поміж очеретом ходять численні раптори. Деякі з них отруйні. Сині кристали сили можна знайти лише тут.

На великому пагорбі стоїть Торва Слідопит. Схоже, він приплив сюди човном з іншого місця в кратері.]],
            ["shapers terrace"] = [[Серед пагорбів кратера Ун'Ґоро стоїть тераса Творця, покинутий комплекс титанів, якого, здається, віками ніхто не чіпав. Назва нагадує про Каз'ґорота, титана-Творця. Відколи найбільші хижаки кратера зайняли її, минуло стільки часу, що ніхто не пам’ятає коли саме. Давні споруди обплели ліани, між ними оселилися дикі звірі, а в залах пульсують кристали сили поблизу пультів, які чекають на джерело живлення. Усередині блукають багряні дияволозаври.]],
            ["slithering scar"] = [[Ґоріші, одна з груп силітидів, тримають більшу частину півдня кратера Ун'Ґоро завдяки своєму вулику. У ньому рояться оси й робітники, яких стережуть сікачі, жалоколи й землериї. Одна з них відома як Мати вулика Завас.]],
            ["terror run"] = [[На південному заході кратера Ун'Ґоро, одразу на захід від Слизького шраму, збираються численні стегодони, деметродони, жаходактилі й дияволозаври. Усі вони ворожі. Червоні кристали ростуть лише тут.

Уздовж східного краю лежить покинутий дослідний табір експедиції Маршалів.]],
        },
    },
    [1450] = {
        text = [[Місячна галявина лежить у кільці гір. Цю приховану долину пагорбів і старого лісу ніколи не торкалася скверна. Серед дерев здіймаються численні кургани, а під ними лежать святилища друїдів минулого.

Колись тут жив Кенарій. Під час Війни Древніх, коли Палаючий Легіон набирав сили, Малфуріон Шаленство Бурі зрозумів, що нічні ельфи самі не переможуть. Він привів Тіранду Шелест Вітру й свого брата Іллідана до священної тиші долини, щоб благати Кенарія про допомогу. Напівбог відгукнувся. Після Великого Розколу хранителі гаю й дріади, що знайшли тут прихисток, пішли у світ.

Через кілька років після Третьої війни Місячну галявину відкрили всім народам друїдів, а Хранитель Ремул став її охоронцем. Таурени й нічні ельфи живуть пліч-о-пліч, і місцева варта не дозволяє їм сваритися. У глибині центрального озера спить божевільний напівбог Омен, який щороку ворушиться, коли наближається Свято місяця.]],
        areas = {
            ["lake eluneara"] = [[Кришталево чиста вода в серці Місячної галявини спокійна, мов скло під деревами. Озеро названо на честь самої Елуни.

Кілька століть тому герої зібралися в Нічній Гавані, щоб стати проти збожеволілого напівбога Омена. Вони осліпили його й загнали в озеро. Він досі спочиває на дні й щороку ворушиться, коли наближається Свято місяця.]],
            ["nighthaven"] = [[На березі озера Елуна'ара стоїть Нічна Гавань, селище з кам’яними спорудами нічних ельфів і двома місячними криницями. Тут живуть друїди Кенарієвого Кола. Це тихе, віддалене місце, зазвичай закрите для чужинців. Його мешканці присвятили себе друїдству й догляду за дикою природою.]],
            ["shrine of remulos"] = [[На заході Місячної галявини стоїть вівтар Хранителя Ремула, сина напівбога Кенарія й охоронця долини. Біля вівтаря можна зустріти самого Ремула, а у святилищі живе нічна ельфійка Таяррі.]],
            ["stormrage barrow dens"] = [[Під тихим дерном Місячної галявини лежать курганні обителі. Багато друїдів нічних ельфів ніколи по-справжньому не покидають цих підземель. Їхні тіла спочивають тут, поки духи мандрують Смарагдовим Сном.

Тут колись спав Малфуріон Шаленство Бурі, на честь якого й названо обителі. Коли під час Третьої війни прийшли Тіхондрій і його повелителі жаху, вони напали на Малфуріона там, де він лежав, і мало не розтрощили його обитель. Тіранда Шелест Вітру розбудила його, щоб він став проти Архімонда й Палаючого Легіону.

Згодом, коли Кенарієве Коло заговорило про вирощування другого Світового дерева, Малфуріон повернувся до курганних обителей для медитації. Коли Тіранда прийшла по нього, то знайшла його нерухомим, наче він спав, та розбудити його не змогла. Коло вирішило, що краще його не чіпати. Якщо дух Малфуріона досі блукає Сном і шукає дороги додому, йому треба знайти тіло там, де він його залишив. Тож Малфуріон досі лежить там під наглядом Кенарієвого Кола й Сестринства Елуни.]],
            ["timbermaw hold"] = [[Столиця фурболґів Деревопузих лежить на північному сході Сквернолісся, а тунель крізь їхній оплот веде до Місячної галявини й Зимоключа. Коли скверна Палаючого Легіону заповзла до священних лісів Калімдору, більшість фурболґів піддалася її впливу. Деревопузі врятувалися й сховалися в оплоті. Звідти вони бачили, як улюблений ліс спотворився й загнив. Навіть після того, як знищили джерело скверни, вона залишилася в лісі.

Деревопузі хочуть припинити страждання своїх спотворених родичів і зцілити землю, щоб у стародавньому лісі одного дня знову залунали співи та сміх.]],
        },
    },
    [1451] = {
        text = [[Пісок і уламки скель укривають південно-західний кут Калімдору. Над пусткою здіймаються лише велетенські вулики силітидів.

Тут лежить частина давньої імперії акірів — земля під назвою Ан’Кіраж. Нині вона безлюдна, а її головний храм запечатано. Наприкінці Війни Зибучих Пісків нічні ельфи й бронзові дракони замкнули кіражів за муром Скарабеїв. Пустеля тримає їх у цій в’язниці тисячі років. Слуг кіражів, силітидів, не замкнули разом із ними. Вони розмножилися й поширилися півднем Калімдору.

Кенарійське коло безперервно стежить за пустелею з Кенарійської цитаделі. Бронзові дракони, нащадки Ноздорму, повернулися сюди вперше за десять тисяч років.]],
    },
    [1452] = {
        text = [[Над Місячною галявиною гора підіймається крізь густий шар білих хмар, а за ним лежить Зимоключ. Повітря тут свіже й чисте. Землю вкриває сніг, і коли він не падає, часто світить сонце.

Під час битви за гору Гіджал дерева покрутило в дивні форми. Оголене коріння Світового дерева височить над головою, мов велетенські дубові арки. Тисячі років тому, після Великого Розколу, нічні ельфи прийшли в цю долину, щоб почати все спочатку. Ще давніша ворожнеча точиться тут між зловмисними синіми драконами й білими морозними шаблезубами, що блукають схилами.

Долину й далі стрясають сутички. Війська синіх драконів, серед яких генерал Кобальтан, воюють із нічними ельфами, що хочуть вигнати їх зі схилів гори Гіджал. Демони цілком захопили південну частину краю. Торгове містечко Завшегляд утримують гобліни.]],
    },
    [1453] = {
        text = [[Орки Орди спалили Штормовій у Першій війні. Після Другої війни мешканці повернулися до руїн, і Гільдія каменярів відбудувала місто з білого каменю. Роботи коштували більше, ніж могла сплатити корона. Знать уже набрала величезних боргів, розосередивши військо по Ельвинну й далі, до Тернистої долини. Гільдії так і не заплатили.

Коли її голова Едвін ван Кліф зажадав платні, Палата шляхти наказала розпустити гільдію. Здійнялися заворушення, у яких випадково загинула королева Тіффін Рінн. Король Варіан Рінн поклявся покарати винних і суворо розправився з бунтівниками. Каменярі втекли з міста й сховалися в Західному краї, де стали Братством Непокірних.

Згодом король Варіан зник за підозрілих обставин. Задля збереження порядку корону передали його юному синові, принцові Андуїну. Верховний лорд Болвар Фордраґон служить регентом і командує військом королівства.]],
        areas = {
            ["champions hall"] = [[На півдні Старого міста, у залі Чемпіонів, розташовані казарми офіцерів Альянсу. У глибині зали вони збираються довкола столу, вкритого мапами Азероту. Серед них архімаг Ґайман зі Штормовію та сержант-майор Небесна Тінь із Дарнаса.]],
            ["deeprun tram"] = [[Після Другої війни дворфи Залізогарта поспішили допомогти союзникам-людям відбудувати Штормовій. Королю Маґні Бронзобородому здалося, що допомога надходить надто повільно. Він також хотів мати змогу швидко перекинути дворфських вояків на допомогу людям, якби війна спалахнула знову. Король звернувся до верховного штукаря Ґелбіна Меккакрутя, найкращого інженера Азероту. Той спроєктував залізницю під землею, щоб з’єднати обидві столиці.

На шляху будівничих опинилося підземне озеро, а потім їх спіткала навала щурів. Попри все трамвай добудували. Гноми працюють на лінії щодня, а щурів так і не вивели.]],
            ["stormwind harbor"] = [[Коли Орда розграбувала Штормовій, сер Андуїн Лотар прикривав відступ уцілілих до причалів. Вони відпливли до Лордерона, а більшість суден, що залишилися, знищили, щоб орки не змогли рушити слідом. Гавань лежить на північному заході міста, на березі Великого моря.]],
            ["valley of heroes"] = [[Перед брамою Штормовію кам’яний міст перетинає рів і веде в пишну зелену долину. Уздовж дороги стоять п’ять великих статуй. Штормовій звів їх під час відбудови після Другої війни на честь очільників експедиції Альянсу. Вони пройшли крізь Темний портал, щоб закрити його з іншого боку.

Ліворуч стоять Курдран Дикий Молот, тан Орлиного піка, й архімаг Кадґар із Кірін-Тору. Праворуч — командувач Данат Тролебій і капітанка слідопитів Аллерія Вітрогін. Наприкінці дороги, де вона розгалужується перед входом до міста, стоїть генерал Тураліон, який очолював їх усіх. Ніхто з п’ятьох не повернувся.

Генерал Маркус Джонатан, верховний командувач оборони Штормовію, тримає тут свій пост.]],
        },
    },
    [1454] = {
        text = [[Невдовзі після битви за гору Гіджал воєвождь Тралл привів свій народ на безлюдний відтинок узбережжя Калімдору. Він назвав землю Дуротаром на честь покійного батька Дуротана, а зведену тут фортецю — Орґріммаром, на честь свого друга й наставника Орґріма Молота Згуби. Місто звели швидко й міцно. Його захищають товсті мури, масивна брама й високі вежі. Навіть гори позаду міста вирізьблено так, що вони стали частиною самої фортеці.

З орків спало прокляття, й Орда більше не була невпинною воєнною машиною. Народ Тралла хотів вижити й розквітнути. Будувати місто допомагали гобліни, таурени, тролі Темного Списа й мок’натал Рексар. Кентаври, гарпії та колючошкури дошкуляли будівничим, та місто зростало.

Тепер тут живуть орки й тролі Темного Списа разом із тауренами та Відреченими, яких Орда прийняла нещодавно. Старі шамани передають знання новим провідникам Орди. Долинами ж гуляють гострі вітри, здатні зірвати дах із погано збудованої оселі.]],
        areas = {
            ["hall of legends"] = [[Офіцери Орди тримають свої казарми в залі Легенд. Посеред зали біля столу, вкритого мапами Азероту, стоять вождь Землев'яз із Громового Круча, радник Віллінґтон із Підміста й кривавий вартовий Гіні'вана з тролів Темного Списа.]],
            ["ragefire chasm"] = [[Під Орґріммаром земля розступається, відкриваючи прірву, повну лави й диму. З глибоких тунелів почали вилазити троґґи, яких Орда називає троґґами Лютого Полум’я. Тауренка Маґата Провидиця спробувала укласти з ними мир, та наразилася на ворожість. Ці створіння не бажають розмовляти. Якщо дати їм волю, вони можуть здолати всю Орду.

У прірві також сховалася секта Тіньової Ради, Випалений Клинок. Її очолює вартовий скверни Тараґаман Ненажерливий разом із чорнокнижником Єргошем-Заклинателем і сатиром Баззаланом. Зі своєї схованки вони замислюють знищити все, що Орда збудувала в цих землях.]],
        },
    },
    [1455] = {
        text = [[Перші дворфи вийшли з Ульдамана й рушили на захід, до гір Дун-Морога. У найвищій вершині вони видовбали зали, звели вівтар титанові Каз’ґороту, якого звали батьком, а під ним збудували Велику кузню. Довкола її вогню виросло місто й узяло собі ім’я кузні.

Залізогарт — видовбана в горі печера. Її зали лежать кільцями довкола Великої кузні в самому серці міста, а глибше під землею є менші яруси. Стінами стікає розплавлений камінь, крамниці вбудовано в скелю, і в кожній корчмі палає вогнище. Місто гомінке, метушливе й промислове, та водночас затишне.

Коли Орда пройшла Каз-Моданом у Другій війні, одна дворфська твердиня падала за іншою. Усюди вцілілі тікали до Залізогарта. Кілроґ Мертве Око й клан Кривавої Очниці місяцями билися з дворфами, але не змогли захопити місто. Тепер тут править король Маґні Бронзобородий, а гноми, вигнані з Гномреґана, отримали власний квартал — Штукарівку.]],
        areas = {
            ["deeprun tram"] = [[Між Залізогартом і Штормовієм двома коліями курсують два потяги, по три вагони в кожному. Частину шляху вони проходять під водою підземного озера. Верховний штукар Ґелбін Меккакруть, найшанованіший інженер Азероту, спроєктував лінію для короля Маґні Бронзобородого. Король хотів мати змогу відправляти дворфських воїнів на допомогу людям, коли знадобиться. Під час будівництва тунелі заполонили щури, і тепер гноми щодня стежать за безпекою лінії.]],
            ["gates of ironforge"] = [[Брама Залізогарта здіймається там, де широкий підйом із середини Дун-Морога впирається в гору. Її видно за багато миль через сніги. Вона відділяє відкритий дворфський край від самого міста.

Усередині стоїть велетенська статуя верховного короля Модімуса Ковмара. Її поставили стерегти вхід, щоб кожен, хто заходить у місто, пройшов під його поглядом.]],
            ["hall of thanes"] = [[Дух старого тана не може знайти спокою в цій залі, охоплений давньою образою. Поруч із ним тримається його примарний слуга, який уривчасто просить лише одного — дати його танові заснути.

У залі зберігають плиту з умовами миру між кланами Бронзобородих і Диких Молотів. Вона походить із часів одразу після Війни Трьох Молотів. Мадоран, перший король Залізогарта з Бронзобородих після громадянської війни, звелів її виготовити, щойно його клан здобув гору. Дикі Молоти й Бронзобороді підписали угоду. Темнозалізні свого підпису не поставили.]],
        },
    },
    [1456] = {
        text = [[Незліченні покоління тауренів мандрували рівнинами, де на них полювали кентаври. Потім воєвождь Тралл і Орда прибули до Калімдору. З їхньою допомогою Керн Криваве Копито зі своїм племенем відкинув кентаврів і здобув трав’янисті рівнини Мулґора. Уперше за сотні років таурени мали власну землю.

Керн звів притулок на низці обвіяних вітром пласких вершин, високо над рівниною. Підйомники з дерева й мотузок, винахід тауренів, підіймають людей від підніжжя скель. Довгі мости з тих самих матеріалів з’єднують вершини. На кожній стоять намети, довгі будинки й розмальовані тотеми.

Тут раді тауренам із будь-якого племені. Колись розпорошені племена об’єдналися під правлінням Керна. Дехто сперечається з ним про те, куди має рухатися нова держава. Та всі згодні, що мудрішого за нього немає.]],
        areas = {
            ["elder rise"] = [[Рада старійшин править із Верхів'я Старійшин, що лежить одразу на схід від центрального круча. Серед тауренських друїдів і жерців тут оселилося й Кенарієве Коло. На верхів’ї живе верховний друїд Гамуул Рунний Тотем, друг дитинства Керна Кривавого Копита. Хатина між двома мостами належить Маґаті Зловісному Тотему, очільниці однойменного племені.]],
            ["hunter rise"] = [[Південне верхів’я Громового Круча належить тим, хто полює й воює. Пасткарі, слідопити й гарбарі працюють біля славнозвісної зали Мисливців, де таурени навчають воїнів і мисливців. Надворі стоять навчальні манекени для вправ зі зброєю.]],
            ["pools of vision"] = [[У тунелях одразу під вершиною Верхів'я Духів Відречені мають осередок у самому серці земель тауренів. Їхні маги й жерці збираються довкола Джерел Видіння, над якими під горою здіймається пара.]],
            ["spirit rise"] = [[Шамани навчаються на Верхів'ї Духів, що лежить на північний захід від центрального круча. Великий вплив тут має плем’я Небесних Мисливців. Під пласкою вершиною парують Джерела Видіння.]],
        },
    },
    [1457] = {
        text = [[Після Третьої війни нічні ельфи втратили безсмертя, і багатьом було нестерпно змиритися зі старістю, хворобами й неміччю. Кілька друїдів задумали повернути його, посадивши велике дерево, яке знову поєднало б їхні душі з вічним світом. Коли Малфуріон Шаленство Бурі зник, провідник цих друїдів Фендрал Оленеріг став верховним друїдом. Дерево, Тельдрассіль, виросло вище хмар поблизу бурхливого узбережжя північного Калімдору. Серед його сутінкових гілок постало місто Дарнас, зведене на честь того, що нічні ельфи вижили.

Місто стоїть довкола озера просто неба. Витончені мости перекинуті через воду, а будівлі розташовані вільно, далеко одна від одної. Уздовж берегів стоять оселі з обробленого дерева й ростуть доглянуті гаї, а стежки вкриває опале листя. Над деревами, мов маяк, здіймається Храм Місяця. Звідти править верховна жриця Тіранда Шелест Вітру, а місто стережуть Дозорні. Дарнас досі є тихим прихистком і пам’ятником народові, який вчиться жити зі своєю смертністю.]],
        areas = {
            ["cenarion enclave"] = [[На північному заході Дарнаса Кенарійський Анклав оточує гай, де дуби та ясени здіймаються вище за кам’яні зали в інших частинах міста. На кожному дереві є таємничі руни, утворені з його власної кори. Друїди збираються серед гаю в спорудах із живого дерева й ретельно обтесаного каменю. У найбільшій із них, у самому серці гаю, мешкає верховний друїд Фендрал Оленеріг. Анклав названо на честь давнього напівбога Кенарія. Замість Дозорних його стережуть древолюди, яких звуть захисниками Дарнаса.

Тут осідок міських друїдів, як у Храмі Місяця — осідок жерців. Тут друїди вчать давніх звичаїв, а мисливці тренуються на крайньому східному дереві. Під землею має оселю потайна гільдія пройдисвітів, про яку знають лише посвячені.]],
            ["craftsmens terrace"] = [[Тераса Ремісників лежить на півночі Дарнаса. Тут тримає зали й майстерні більшість міських ремісників — алхіміки, кравці, шкіряники, чарівники, кухарі й цілителі. Подорожні можуть зупинитися в корчмі Саліенни, одній із найбільших у місті. Тут також є посольство Сріблястого Світанку, осередок чужинців у місті ельфів.

Майстриня-шкіряниця Телоніс каже, що трава тут м’яка, а повітря повниться світлом і співом. Усе, що вона бачила, свідчить, що Тельдрассіль — здійснена мрія. Та чому їй так тривожно на серці, вона пояснити не може.]],
            ["temple gardens"] = [[У серці Дарнаса лежать Прихрамові сади, простір із водоймами, доріжками й острівцями. Вони названі на честь Храму Місяця, що здіймається одразу на південь. Мости ведуть звідси в усі боки, наче тут сходяться всі міські дороги. На острівцях ростуть одні з найкращих рослин міста. Нічні ельфи дбають про воду, щоб вони й далі пишно росли. Тут усамітнювалася для роздумів Тіранда Шелест Вітру.

На крайньому заході садів портал веде до селища Рут'Теран при підніжжі Світового дерева.]],
            ["tradesmens terrace"] = [[Більшість крамарів і купців Дарнаса тримаються тераси Торговців на півдні міста. Тут осередок торгівлі нічних ельфів і міський аукціон. Тутешні легкі й витончені будівлі вирощено з дерева за звичаєм нічних ельфів.]],
            ["warriors terrace"] = [[На терасі Воїнів, яку також називають залою Правосуддя, стоїть східна брама Дарнаса. Вона відкриває шлях у нетрі Тельдрассіля. Тут тримають позиції Дозорні, а браму стережуть дозори на нічних шаблезубах. Нічні ельфи військових чинів вправляються на стрільбищах і майданчиках для двобоїв. Тераса затуляє місто від усього, що може прийти дорогою з лісу.]],
        },
    },
    [1458] = {
        text = [[Підмісто було старим іще до того, як ним заволоділи Відречені. Глибоко під палацом Лордерона лежали давні крипти й катакомби, де спочивали королі. Поруч були міські підземелля й стічні ходи, де поміж в’язнями й мерцями жили найбідніші мешканці Лордерона.

Артас Менетіл хотів зробити Підмісто осередком влади Скари в Лордероні, але Король-Ліч відкликав його до завершення будівництва. Коли влада Короля-Ліча ослабла, леді Сильвана Вітрогін вивела зі Скари гурт невмерлих, які здобули власну волю. Вона заманила Артаса в пастку, проте він утік. Коли битви за Лордерон скінчилися, Сильвана назвала своїх послідовників Відреченими й оголосила зруйновану столицю їхньою.

Відречені роками добудовували лабіринт катакомб, який почала Скара. Уздовж кожної вулиці течуть ріки отруйного мулу. Їхні випари майже нестерпні для живих членів Орди. Для Сильвани й її проклятого народу це прихисток у світі, де їх бояться й переслідують.]],
        areas = {
            ["ruins of lordaeron"] = [[Над похованим містом досі стоїть палац Лордерона. Його зали відкриті до неба, а сади занепали. Принц Артас Менетіл повернувся сюди на чолі війська. За брамою його зустріли дзвоном і вигуками радості. Тоді ще ніхто не збагнув, ким він став. У тронній залі Артас убив батька, короля Теренаса, а Скара знищила столицю. Королівство впало.

Руїни зберегли звуки того дня. При вході калатають дзвони, звідкись долинають тихі вітальні вигуки, а в тронній залі шепочуть голоси. Серед них чути Артаса, який проголошує, що королівство впаде й з попелу постане новий лад. У дворі досі блукають привиди мешканців Лордерона, а за мурами нишпорять темні гончі й сутінкові кажани.]],
        },
    },
    [2482] = {
        text = [[Гора Гіджал була святилищем Диких богів під опікою Хранительки Фреї. Нічні ельфи вважали її священною, і королева Азшара не дозволяла своїй імперії її чіпати. Гора встояла, коли світ розколовся. Уцілілі нічні ельфи зібралися на ній, щоб відбудувати своє суспільство, цього разу без арканічної магії.

Іллідан Шаленство Бурі створив на вершині гори другу Криницю Вічності. Нічні ельфи посадили над нею Світове дерево Нордрасіл, і три драконячі Аспекти — Алекстраза, Ноздорму та Ізера — благословили його. Дерево зцілило землю й захистило нічних ельфів від старості та хвороб.

У Третій війні демон Архімонд повів Палаючий Легіон схилами гори. Орки, люди й нічні ельфи стали проти нього разом. Віспи Гіджалу зібралися в Нордрасілі, і вибух знищив Архімонда. Та дерево втратило свої чари, а нічні ельфи — безсмертя. Відтоді густі зарості відгороджують гору, поки Нордрасіл поволі відновлюється.]],
        areas = {
            ["cradle of tranquility"] = [[У Колисці Спокою живе Джереман, жахокрук і дух дикої природи.]],
            ["malornes retreat"] = [[Тут лежить глибока долина, густо вкрита деревами. На її краю зяє вхід до великої печери. У ній оселилися ворожі фурболґи.]],
            ["mournings rest"] = [[У Спочинку Скорботи живе Марросіс, гриф і дух дикої природи.]],
            ["summit of eternity"] = [[На вершині гори Гіджал стоїть Світове дерево Нордрасіл. У Третій війні Архімонд вів до нього своє військо, знищуючи ліси на шляху. Після війни Малфуріон Шаленство Бурі відгородив гору й дерево густими заростями. Нордрасіл поволі відновлюється.]],
        },
    },
    [2521] = {
        text = [[Майже десять тисяч років тому повстанець у масці, відомий як Шал’нан, очолив бунт проти принца Тортельдріна в Ельдре'Таласі, місті Високородних. Повстанці втекли морем на захід і знайшли край, яким правили духи вітру. Духи уклали з ними угоду, підняли частину землі в небо як острів Зефрас і закріпили його в Небесній Стіні, стихійному світі повітря.

Небонароджені, нащадки вигнанців, відтоді живуть тут. Небо змінило їх. Вони стали стрункими й легкими, і дедалі більше їхніх дітей народжуються з блакитною шкірою. Та духи вітру зникли, і ніхто на острові не знає чому. Пілони, що тримають острів, виходять із ладу. Інші острови Небонароджених розпадаються, біженці стікаються на Зефрас, а сам Зефрас теж почав розвалюватися.

За решту змагаються три сили. Високий Орден шукає арканічні знання предків-Високородних. Формувачі Вітру бережуть давній зв’язок зі стихіями. Культ Ал'Акету служить Ал'Акіру.]],
        areas = {
            ["bandit hideout"] = [[Тут ховаються бандити, які крадуть камені вітру із сільських припасів, щоб прожити. Дехто з них утік із поселень, що розвалилися, і подався в розбій, коли більше не було куди йти.]],
            ["east pylon watchtower"] = [[Культисти Ал'Акету взяли в облогу Вартову вежу Східного пілону. Миротворці тримають оборону. Пілони, від яких вежа дістала назву, — стародавні якорі, подаровані духами вітру. Вони утримують острів у повітрі.]],
            ["fairweather stables"] = [[Ґенн Фейрвезер тримає вітроходів у Стайнях Фейрвезера й навчає вершників їздити на них. Ці великі птахи норовливі й скидають вершників, які невміло з ними поводяться. Тож Ґенн бере лише тих, хто має трохи досвіду й може заплатити. У загонах вітроходи — бурі, грозові й небесні — чистять пір’я, щебечуть і роздивляються гостей, а один аж підстрибує від нетерпіння.]],
            ["falaath village"] = [[Культ Ал'Акету зайняв село Фалаат. Тут жив кравець Зендраас. Коли культисти захопили його дім, він одягнув їхню мантію й оголосив, що поділяє їхню віру. Згодом він створив чимало їхніх убрань. Дехто приєднався до культу, щоб вижити, і не поділяє його вірувань.]],
            ["gustberry lowlands"] = [[Низовиною Гастберрі тече річка. Уздовж неї живуть жаби, над землею літають метелики, а хмаробіжки-матріархи ходять із малечею. Тут також осіли культисти Ал'Акету на чолі з командиркою Белґілос, яку вони звуть Руйнівницею. Колись вона служила в Миротворцях.]],
            ["nightclaw cavern"] = [[Друїди Нічного Кігтя, коло шен'дорай, облаштували схованку в печері на північному сході лісу Тіньового Вітру. Друїди серед шен'дорай тепер рідкість. Нічний Кіготь тримається осторонь від усіх інших угруповань острова.]],
            ["overlook standing stones"] = [[Між стоячими каменями Оглядової скелі пурхають духи вітру, крихітні елементалі повітря. Коли їх налякати, вони пискають і зникають. За каменями наглядають охоронці й елементалісти Формувачів Вітру.]],
            ["rohashi spires"] = [[Шпилі Рохаші здіймаються в небі над Святилищем Акіра. Тут тримаються небесні жерці й почесна варта культу Ал'Акету.]],
            ["ruins of banaethal"] = [[Маги-ковалі Бан'еталу були найкращими майстрами островів небонароджених. Коли чари, що тримали поселення, вичерпалися, воно почало падати в небо. Мешканці втекли вночі. Тепер серед руїн пливуть порожні вітри, примарні елементалі повітря.]],
            ["sanctum of storms"] = [[Святилище штормів повниться небесними жерцями й почесною вартою культу Ал'Акету.]],
            ["shadowgale forest"] = [[У лісі Тіньового Вітру живуть друїди Нічного Кігтя. Це потайне коло тримається осторонь від усіх інших угруповань острова. Відколи духи вітру зникли, серед дерев з’являються примарні духи, яких звуть порожніми вітрами. Деякими ночами біля них чути тужливий спів.]],
            ["shendar highlands"] = [[Формувачі Вітру, шамани, які спілкуються з духами стихій, бережуть стоячі камені Шен'дарського нагір'я, священне місце стихійної магії. Нагір’ям також блукають бандити.]],
            ["shendar village"] = [[У селі Шен'дар стоїть корчма «Тихий вітер». Тут живуть старійшина Формувачів Вітру й старійшина Високого Ордену. Констебль Аонда з кількома Миротворцями тримає варту, а серед селян ходить місіонер культу Ал'Акету.]],
            ["shriekling den"] = [[У цій печері неподалік Валанаара гніздяться верескуни з пташенятами й матріархинею.]],
            ["shrine of akir"] = [[Святилище Акіра тримає культ Ал'Акету. Його стережуть охоронці, майстри клинка, почесні вартові, заклиначі духів і небесні жерці. Серед них Заал Штормощит і Тель'деор Штормомов. Тут також служить брат Зендраас.]],
            ["skywall"] = [[Небесна Стіна — стихійний план повітря, царство давніх духів вітру, у якому висить острів Зефрас. Два інші острови небонароджених, Анвілас і Сіроккас, теж десь у ньому пливуть, але зв’язок із ними урвався, коли зникли духи вітру.

Культ Ал'Акету вважає справжнім володарем Небесної Стіни Ал'Акіра, Володаря Вітру, й поклоняється йому. Повітряні катери небонароджених можуть пройти крізь цю стихійну площину до Азероту, лише коли правильно розрахувати плин стихійної сили.]],
            ["thendal cave"] = [[У печері Тендала на захід від села Тендал мають лігво урсери-падальники. Ними править матріархиня, яку слідопити гаю Тендала звуть Урс'аною.]],
            ["thendal grove"] = [[Слідопити стережуть гай Тендала, звідки видно один зі стародавніх пілонів острова. Його чари стали нестійкі й нерівномірні.]],
            ["thendal standing stones"] = [[Біля стоячих каменів Тендала крізь землю прорвалася лінія сили, як і в кількох інших місцях на Зефрасі останнім часом. Це підвело арканічну енергію близько до поверхні. Тут пливуть прості духи вітру, чутливі до настроїв і намірів усіх поблизу. Культисти Ал'Акету підбурюють їх. Між каменями блукають елементалі бурхливих вітрів і навернені культу.]],
            ["thendal village"] = [[Слідопити гаю Тендала патрулюють ліси довкола рідного села Тендал. Селом керує Роріан Шукач Дня. Формувачі Вітру й Високий Орден, які в інших місцях острова не довіряють одне одному, тут живуть у відносній злагоді. Селяни вже якийсь час знають про Ал'Акет і досі воліли спостерігати за культом здалеку.]],
            ["valanaar"] = [[У Валанаарі живе Талааніс Пісня Тіней, верховний старійшина острова Зефрас. Високий Орден і Формувачі Вітру мають у містечку свої осідки. Вулиці стережуть Миротворці, острівне ополчення під проводом капітанки Валеннії Штормокулак. Тут є своя корчма «Тихий вітер».]],
            ["valanaar skydocks"] = [[Тут швартуються повітряні катери небонароджених. Колись вони ходили між островами, поки переправи не стали небезпечними.]],
            ["west pylon watchtower"] = [[Воїни Ал'Акету тримають Вартову вежу Західного пілону. На верхівці стоїть небесний жрець культу.]],
            ["windfield orchard"] = [[Родина Віндфілдів тримає тут сад, де вирощує грозові яблука. Величезний конструкт із часів духів вітру десятиліттями ходить полями, а з-під пластин його обладунку чути тихе дзижчання. Родина здебільшого не зважає на нього.]],
            ["windsong lake"] = [[Деякі конструкти, подаровані небонародженим духами вітру, впали в озеро Пісні Вітру, коли пілони відмовили. У його водах живе молотозавр, відомий як Загублений.]],
            ["windsong standing stones"] = [[Між стоячими каменями Пісні Вітру живуть маленькі елементалі повітря, яких звуть духами вітру.]],
        },
    },
    [2524] = {
        text = [[Буря розсіяла викрадений флот Тралла, коли кораблі великого адмірала Деліна Праудмура гналися за ним морем. Пошкоджені орочі кораблі знайшли бухту на низці островів із діючим вулканом і стали там на ремонт. Тут жили тролі Темного Списа. Вони покинули Тернисту долину, бо інші племена Ґурубаші жорстоко з ними поводилися.

Знахар Сен’джин зустрів орків мирно й сказав Траллові, що бачив його у видінні. Кул-тіраські моряки, відрізані від флоту Деліна, збудували на островах заставу й воювали з тролями. Під час боїв мурлоки схопили Тралла, Сен’джина й людей та затягли їх у печери під вулканом. Тралл пробився до мурлоцького вівтаря, але Сен’джин уже був смертельно поранений. Останніми словами він сказав Траллові, що у видіннях бачив, як той виведе тролів звідси. Темний Спис відплив слідом за Ордою.

Тепер за острови б’ються рейдери Темного Списа й експедиційний корпус Терамора.]],
    },
    [2548] = {
        text = [[Штормовій полишив Річкові галявини в Першій війні. Стара Орда захопила край, а королівство вирішило, що військо потрібніше вдома. Уже двадцять років лицарі Братства Коня б’ються, щоб повернути цю землю. Їхній провідник Демар Брант вважає воїнів Штормовію боягузами, що ховаються за мурами. Твердиня братства — замок Фарголд.

Наприкінці Другої війни оґри Молота Сутінків і орки Буревикрадачів утекли на схід і приєдналися до оґрів, які вже тут осіли. Головна річка петляє краєм і утворює три озера-стариці, а гобліни продають зброю кожній стороні протистояння.]],
        areas = {
            ["ashwoods fall"] = [[Довкола зруйнованої дозорної вежі лежать розбиті вози. Поміж її обвалених стін — уламки й дерев’яні барикади. Розалінд Ешвуд, розвідниця Братства, приїхала до Віндстеда попередити тамтешні родини про наближення Орди й повела валку біженців до Фарголда. Орда наздогнала їх біля дозорної вежі. Ніхто не вижив. Вози й назва свідчать, що це та сама вежа.]],
            ["bolderok"] = [[Оґри утримують Болдер'ок, поселення на північний захід від Віндстеда. Колись вони були на боці Молота Сутінків, та покинули його й уклали союз з Ордою.]],
            ["farholde keep"] = [[Фарголд стоїть на прибережному острові, який лицарі обрали за його природний захист. Вони укріпили острів разом із людьми, яких урятували в Першій війні, бо Орда перекрила шлях додому.

Через кілька років після Другої війни військо Орди взяло замок в облогу. Нападники підійшли з води й вивели з ладу пришвартовані морські судна, щоб ніхто не зміг утекти чи послати по допомогу. У замку тіснилися цілі родини, припаси вичерпувалися, а бойовий дух падав. Уночі агентка Братства Ферн Багрянолиста пробралася у ворожий табір і вбила очільників Орди. На світанку сер Говард Армстронґ повів вояків у наступ від брами. Вояки Орди чекали наказів, яких так і не отримали, а тоді кинулися навтьоки. Говард і кілька його товаришів загинули в тому бою. У замку стоять їхні пам’ятники. Сам замок досі тримає лицар-командир Демар Брант.]],
            ["kroldok stronghold"] = [[Твердиня Крол'док — фортеця оґрів. Військо Орди, що облягало Фарголд, відступило сюди, коли облогу зняли.]],
            ["meadowsbrook"] = [[Лицарі, що визволили полонених із Сонячної галявини, виявили, що Орда відрізала їм дорогу додому, й оселилися тут із уцілілими. Згодом загін Братства, відступаючи від Орди, натрапив на село. Допомога місцевих дала Братству змогу закріпитися в Річкових галявинах.]],
            ["powderfuse port"] = [[Гоблін-інженер Мелбін Порохогніт запевняє, що сам збудував усе в цьому порту на східному узбережжі й що все тут його. Каже, коли він прибув, тут був пустир. Джаззл Підлостріл облаштовує арену, яку ще не відкрив, і скаржиться, що Орда й Альянс б’ються в полях, хоч могли б заплатити за бій на його арені.]],
            ["rogmar"] = [[У Роґ'марі Орда тримає одне зі своїх головних поселень у Річкових галявинах.]],
            ["sunnyglade"] = [[Сонячна галявина була заможним і квітучим містом королівства Штормовій. У Першій війні Стара Орда зруйнувала більшу частину міста, а вцілілих забрала в рабство. Одну вежу магів лишили цілою, щоб орки могли довідатися, як діє людська магія. Пізніше руїни тримало Братство Коня. Коли Орда знову прийшла, капітан Братства Родерік Незламний тримав тут міст, поки розвідник ніс звістку до Фарголда. Він утратив руку, та вижив. Тепер руїни тримає Молот Сутінків, а вежа магів досі стоїть.]],
            ["terrals watch"] = [[Над заблокованим входом до Варти Террала висить стяг із зображенням коня. Це кам’яна дозорна вежа, верхні мури якої частково обвалилися. До дверей ведуть широкі кам’яні сходи. Обабіч входу горять світильники.]],
            ["twilights shroud"] = [[Сутінковий саван — один з опорних пунктів Молота Сутінків у Річкових галявинах, поряд із твердинею Крол'док. На північ від нього лежать Безплідні краї.]],
            ["wheelers grange"] = [[Бенджі Вілер стоїть біля свого будинку на фермі неподалік замку Фарголд. Поля ферми заполонили ворожі жнивальні збирачі.]],
            ["windstead"] = [[Родини, які врятувалися від знищення Сонячної галявини, знайшли потаємне озеро в горах і заснували біля нього Віндстед. Вони боялися, що Орда колись їх знайде. Після багатьох років усамітнення селяни знехтували попередженням Фарголда, що в разі великої битви замок не зможе їх захистити. Коли загроза наблизилася, одні пішли узбережжям, інші — дорогою. Тепер село стоїть порожнє, а в його руїнах осіли пірати Східного моря.]],
        },
    },
    [2652] = {
        text = [[На північ від Грізного Молота лежить Шен’дралас, колишня частина Ельдре’Таласа, міста Високородних. Його руїнами досі блукають дружні духи Шен’драларів. На ці землі також претендують кентаври Маґрами й колючошкури Щетиноспини. Край лежить на південний схід від Спустошища, між Фераласом і Мулґором.

Долина Кісток, скеляста місцевість на південному краї Спустошища, належить до Шен’драласа. На її дні лежать два велетенські скелети невідомого походження. Поміж кістяками ходять некроманти й невмерлі спустошники, а північчю краю блукають некроманти Маґрамів.]],
        areas = {
            ["bristleback retreat"] = [[Синьошкірі ґноли з племені Бляклогривих розбили табір у Прихистку Щетиноспинів. Серед них є браконьєри, шкуродери й кожум’яки.]],
            ["evenshades overlook"] = [[Архімага Мордента Івеншейда можна зустріти за руїнами на північ від міста. Він високородний із Шен'драларів і досі називає місто його справжнім іменем — Ельдре'Талас. Каже, що за тисячоліття храм і його угіддя занепали, а від колишнього Шен'драласа лишилася тільки оболонка, повна привидів. Місто пережило Великий Розкол, та загинуло стільки його народу, що він не може цього забути. Він дивиться в бік братської могили, де поховано його рідню. З уцілілих він зустрів тільки членів свого ордену, які усамітнилися з принцом Тортельдріном у глибинах міста. До бібліотеки, яку колись звав домом, він навідується рідко.]],
        },
    },
}
